CREATE OR REPLACE FUNCTION qr_api.fn_check_media_limits() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    v_photo_type_id  BIGINT;
    v_video_type_id  BIGINT;
    v_grave_type_id  BIGINT;
    v_photo_count    INTEGER;
    v_video_seconds  INTEGER;
    v_max_photos     INTEGER;
    v_max_video_sec  INTEGER;
BEGIN
    IF NEW.deleted_at IS NOT NULL THEN
        RETURN NEW;
    END IF;

    SELECT id INTO v_photo_type_id FROM qr_ref.media_types WHERE code = 'photo';
    SELECT id INTO v_video_type_id FROM qr_ref.media_types WHERE code = 'video';
    SELECT id INTO v_grave_type_id FROM qr_ref.media_types WHERE code = 'grave_photo';

    SELECT m.max_photos, m.max_video_seconds
    INTO v_max_photos, v_max_video_sec
    FROM qr_memorial.memorials m
    WHERE m.id = NEW.memorial_id AND m.deleted_at IS NULL;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'MEMORIAL_NOT_FOUND: id=%', NEW.memorial_id;
    END IF;

    -- Фото могилы не входит в лимит галереи, но только одно
    IF NEW.media_type_id = v_grave_type_id THEN
        IF EXISTS (
            SELECT 1 FROM qr_memorial.media_files mf
            WHERE mf.memorial_id = NEW.memorial_id
              AND mf.media_type_id = v_grave_type_id
              AND mf.deleted_at IS NULL
              AND mf.id IS DISTINCT FROM NEW.id
        ) THEN
            RAISE EXCEPTION 'GRAVE_PHOTO_ALREADY_EXISTS: memorial_id=%', NEW.memorial_id
                USING ERRCODE = 'unique_violation';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.media_type_id = v_photo_type_id THEN
        SELECT count(*) INTO v_photo_count
        FROM qr_memorial.media_files mf
        WHERE mf.memorial_id = NEW.memorial_id
          AND mf.media_type_id = v_photo_type_id
          AND mf.deleted_at IS NULL
          AND mf.id IS DISTINCT FROM NEW.id;

        IF v_photo_count >= v_max_photos THEN
            RAISE EXCEPTION 'PHOTO_LIMIT_EXCEEDED: limit=% current=%', v_max_photos, v_photo_count
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;

    IF NEW.media_type_id = v_video_type_id THEN
        SELECT coalesce(sum(mf.duration_seconds), 0) INTO v_video_seconds
        FROM qr_memorial.media_files mf
        WHERE mf.memorial_id = NEW.memorial_id
          AND mf.media_type_id = v_video_type_id
          AND mf.deleted_at IS NULL
          AND mf.id IS DISTINCT FROM NEW.id;

        IF v_video_seconds + coalesce(NEW.duration_seconds, 0) > v_max_video_sec THEN
            RAISE EXCEPTION 'VIDEO_LIMIT_EXCEEDED: limit_sec=% current=% adding=%',
                v_max_video_sec, v_video_seconds, coalesce(NEW.duration_seconds, 0)
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;

    RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION qr_api.fn_check_single_succeeded_payment() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    v_succeeded_id BIGINT;
BEGIN
    SELECT id INTO v_succeeded_id FROM qr_ref.payment_statuses WHERE code = 'succeeded';

    IF NEW.status_id = v_succeeded_id THEN
        IF EXISTS (
            SELECT 1
            FROM qr_commerce.payments p
            WHERE p.order_id = NEW.order_id
              AND p.status_id = v_succeeded_id
              AND p.id IS DISTINCT FROM NEW.id
        ) THEN
            RAISE EXCEPTION 'ORDER_ALREADY_PAID: order_id=%', NEW.order_id
                USING ERRCODE = 'unique_violation';
        END IF;
    END IF;

    RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION qr_api.fn_link_guest_orders_to_user(p_user_id UUID, p_email citext) RETURNS INT LANGUAGE plpgsql AS $$
DECLARE
    v_linked INTEGER;
BEGIN
    UPDATE qr_commerce.orders
    SET user_id = p_user_id
    WHERE buyer_email = p_email
      AND user_id IS NULL;

    GET DIAGNOSTICS v_linked = ROW_COUNT;
    RETURN v_linked;
END;
$$

CREATE OR REPLACE FUNCTION qr_api.fn_on_qr_assign_memorial() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    v_active_status_id BIGINT;
    v_line             qr_commerce.order_lines%ROWTYPE;
BEGIN
    IF NEW.memorial_id IS NOT NULL AND (OLD.memorial_id IS DISTINCT FROM NEW.memorial_id) THEN
        SELECT id INTO v_active_status_id FROM qr_ref.qr_code_statuses WHERE code = 'active';

        SELECT ol.* INTO v_line
        FROM qr_commerce.order_lines ol
        WHERE ol.id = NEW.order_line_id;

        UPDATE qr_memorial.memorials m
        SET package_type_id = v_line.package_type_id,
            max_photos = v_line.snapshot_max_photos,
            max_video_seconds = v_line.snapshot_max_video_sec
        WHERE m.id = NEW.memorial_id;

        NEW.status_id := v_active_status_id;
        NEW.activated_at := coalesce(NEW.activated_at, now());
    END IF;

    RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION qr_api.fn_set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION qr_api.fn_sync_order_total_from_line() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE qr_commerce.orders o
    SET total_amount = NEW.line_total_rub
    WHERE o.id = NEW.order_id;
    RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION qr_api.sp_admin_company_product_delete(p_admin_id UUID, p_product_id UUID, p_reason TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_owner UUID;
    v_title TEXT;
    v_company UUID;
    v_company_name TEXT;
    v_reason TEXT;
BEGIN
    PERFORM qr_api.sp_admin_assert_actor(p_admin_id);
    v_reason := btrim(coalesce(p_reason, ''));
    IF char_length(v_reason) < 3 THEN
        RAISE EXCEPTION 'REASON_REQUIRED';
    END IF;

    SELECT p.title, p.company_id, coalesce(c.short_name, c.legal_name), c.owner_user_id
    INTO v_title, v_company, v_company_name, v_owner
    FROM qr_marketplace.company_products p
    JOIN qr_marketplace.companies c ON c.id = p.company_id
    WHERE p.id = p_product_id AND p.deleted_at IS NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'PRODUCT_NOT_FOUND';
    END IF;

    UPDATE qr_marketplace.company_products
    SET deleted_at = now()
    WHERE id = p_product_id AND deleted_at IS NULL;

    PERFORM qr_api.sp_user_notification_create(
        v_owner,
        'admin_moderation',
        'Товар удалён',
        format(
            'Товар «%s» компании «%s» был удалён с витрины администратором по причине: %s',
            v_title, v_company_name, v_reason
        ),
        'company_product',
        p_product_id,
        format('/companies/%s', v_company)
    );
    RETURN p_product_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_admin_company_review_delete(p_admin_id UUID, p_review_id UUID, p_reason TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_company UUID;
    v_author UUID;
    v_owner UUID;
    v_company_name TEXT;
    v_author_name TEXT;
    v_reason TEXT;
    v_body TEXT;
BEGIN
    PERFORM qr_api.sp_admin_assert_actor(p_admin_id);
    v_reason := btrim(coalesce(p_reason, ''));
    IF char_length(v_reason) < 3 THEN
        RAISE EXCEPTION 'REASON_REQUIRED';
    END IF;

    SELECT r.company_id, r.author_user_id, r.author_name, left(r.body, 120),
           coalesce(c.short_name, c.legal_name), c.owner_user_id
    INTO v_company, v_author, v_author_name, v_body, v_company_name, v_owner
    FROM qr_marketplace.company_reviews r
    JOIN qr_marketplace.companies c ON c.id = r.company_id
    WHERE r.id = p_review_id AND r.deleted_at IS NULL;
    IF v_company IS NULL THEN RAISE EXCEPTION 'REVIEW_NOT_FOUND'; END IF;

    UPDATE qr_marketplace.company_reviews
    SET deleted_at = now(), deleted_by_user_id = p_admin_id
    WHERE id = p_review_id AND deleted_at IS NULL;
    PERFORM qr_api.sp_company_reviews_recalc(v_company);

    PERFORM qr_api.sp_user_notification_create(
        v_author,
        'admin_moderation',
        'Отзыв удалён',
        format(
            'Ваш отзыв о компании «%s» был удалён администратором по причине: %s',
            v_company_name, v_reason
        ),
        'company_review',
        p_review_id,
        format('/companies/%s?view=reviews', v_company)
    );
    IF v_owner IS NOT NULL AND v_owner IS DISTINCT FROM v_author THEN
        PERFORM qr_api.sp_user_notification_create(
            v_owner,
            'admin_moderation',
            'Отзыв удалён',
            format(
                'Отзыв пользователя %s о компании «%s» был удалён администратором по причине: %s',
                v_author_name, v_company_name, v_reason
            ),
            'company_review',
            p_review_id,
            format('/companies/%s?view=reviews', v_company)
        );
    END IF;
    RETURN p_review_id;
END;
$function$

