CREATE OR REPLACE FUNCTION qr_api.sp_admin_create_admin(p_actor_user_id UUID, p_id UUID, p_email citext, p_password_hash VARCHAR, p_full_name VARCHAR, p_must_change_password BOOLEAN DEFAULT FALSE) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_admin_role_id BIGINT;
    v_email CITEXT;
BEGIN
    PERFORM qr_api.sp_admin_assert_actor(p_actor_user_id);

    IF p_email IS NULL OR btrim(p_email::text) = '' THEN
        RAISE EXCEPTION 'EMAIL_REQUIRED' USING ERRCODE = 'check_violation';
    END IF;

    v_email := lower(p_email::text)::citext;

    IF qr_api.sp_user_email_exists(v_email) THEN
        RAISE EXCEPTION 'LOGIN_ALREADY_EXISTS' USING ERRCODE = 'unique_violation';
    END IF;

    SELECT id INTO v_admin_role_id FROM qr_ref.user_roles WHERE code = 'admin';
    IF v_admin_role_id IS NULL THEN
        RAISE EXCEPTION 'ROLE_NOT_FOUND';
    END IF;

    INSERT INTO qr_identity.users (
        id,
        role_id,
        email,
        password_hash,
        full_name,
        email_verified,
        must_change_password,
        is_active,
        created_by_user_id,
        updated_by_user_id
    ) VALUES (
        p_id,
        v_admin_role_id,
        v_email,
        p_password_hash,
        NULLIF(btrim(p_full_name), ''),
        TRUE,
        coalesce(p_must_change_password, FALSE),
        TRUE,
        p_actor_user_id,
        p_actor_user_id
    );

    RETURN p_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_admin_ensure_buyer_user(p_actor_user_id UUID, p_id UUID, p_email citext, p_password_hash VARCHAR, p_full_name VARCHAR DEFAULT CAST(NULL AS VARCHAR), p_phone VARCHAR DEFAULT CAST(NULL AS VARCHAR)) RETURNS TABLE (user_id UUID, created BOOLEAN, email citext, must_change_password BOOLEAN) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_email CITEXT;
    v_existing UUID;
    v_must BOOLEAN;
    v_buyer_role_id BIGINT;
    v_phone VARCHAR;
BEGIN
    PERFORM qr_api.sp_admin_assert_actor(p_actor_user_id);

    IF p_email IS NULL OR btrim(p_email::text) = '' THEN
        RAISE EXCEPTION 'EMAIL_REQUIRED' USING ERRCODE = 'check_violation';
    END IF;

    v_email := lower(p_email::text)::citext;
    v_phone := nullif(btrim(coalesce(p_phone, '')), '');

    SELECT u.id, u.must_change_password
    INTO v_existing, v_must
    FROM qr_identity.users u
    WHERE u.email = v_email AND u.deleted_at IS NULL
    LIMIT 1;

    IF v_existing IS NOT NULL THEN
        user_id := v_existing;
        created := FALSE;
        email := v_email;
        must_change_password := coalesce(v_must, FALSE);
        RETURN NEXT;
        RETURN;
    END IF;

    IF p_password_hash IS NULL OR btrim(p_password_hash) = '' THEN
        RAISE EXCEPTION 'PASSWORD_REQUIRED' USING ERRCODE = 'P0001';
    END IF;

    SELECT id INTO v_buyer_role_id FROM qr_ref.user_roles WHERE code = 'buyer';
    IF v_buyer_role_id IS NULL THEN
        RAISE EXCEPTION 'ROLE_NOT_FOUND';
    END IF;

    INSERT INTO qr_identity.users (
        id, role_id, email, phone, password_hash, full_name,
        email_verified, must_change_password, is_active,
        created_by_user_id, updated_by_user_id
    ) VALUES (
        p_id, v_buyer_role_id, v_email, v_phone, p_password_hash,
        NULLIF(btrim(coalesce(p_full_name, '')), ''),
        TRUE, TRUE, TRUE, p_actor_user_id, p_actor_user_id
    );

    user_id := p_id;
    created := TRUE;
    email := v_email;
    must_change_password := TRUE;
    RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_admin_mark_order_paid(p_actor_user_id UUID, p_order_id UUID, p_payment_id UUID, p_provider_payment_id VARCHAR, p_note TEXT DEFAULT CAST(NULL AS TEXT)) RETURNS TABLE (payment_id UUID, order_id UUID) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_status VARCHAR;
    v_amount NUMERIC(12,2);
    v_user_id UUID;
    v_order_number BIGINT;
    v_package_name VARCHAR;
    v_qr_count BIGINT;
    v_qr_phrase TEXT;
    v_succeeded BIGINT;
    v_paid BIGINT;
    v_audit TEXT;
BEGIN
    PERFORM qr_api.sp_admin_assert_actor(p_actor_user_id);

    SELECT os.code, o.total_amount, o.user_id, o.order_number
    INTO v_status, v_amount, v_user_id, v_order_number
    FROM qr_commerce.orders o
    JOIN qr_ref.order_statuses os ON os.id = o.status_id
    WHERE o.id = p_order_id
    FOR UPDATE OF o;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
    END IF;
    IF v_status <> 'pending_payment' THEN
        RAISE EXCEPTION 'ORDER_NOT_PENDING_PAYMENT' USING ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1 FROM qr_commerce.payments p
        JOIN qr_ref.payment_statuses ps ON ps.id = p.status_id
        WHERE p.order_id = p_order_id AND ps.code = 'succeeded'
    ) THEN
        RAISE EXCEPTION 'ORDER_ALREADY_PAID' USING ERRCODE = 'P0001';
    END IF;

    SELECT id INTO v_succeeded FROM qr_ref.payment_statuses WHERE code = 'succeeded';
    SELECT id INTO v_paid FROM qr_ref.order_statuses WHERE code = 'paid';

    INSERT INTO qr_commerce.payments (
        id, order_id, status_id, provider, provider_payment_id,
        idempotence_key, amount_rub, confirmation_url, paid_at
    ) VALUES (
        p_payment_id, p_order_id, v_succeeded, 'manual', p_provider_payment_id,
        p_payment_id, v_amount, NULL, now()
    );

    v_audit := '[manual paid by admin ' || p_actor_user_id::text || ' at ' || now()::text || ']';
    IF nullif(btrim(coalesce(p_note, '')), '') IS NOT NULL THEN
        v_audit := btrim(p_note) || ' ' || v_audit;
    END IF;

    UPDATE qr_commerce.orders
    SET status_id = v_paid,
        paid_at = now(),
        updated_at = now(),
        updated_by_user_id = p_actor_user_id,
        notes = CASE
            WHEN notes IS NULL OR notes = '' THEN v_audit
            ELSE notes || E'\n' || v_audit
        END
    WHERE id = p_order_id;

    PERFORM qr_api.sp_generate_qr_codes_for_order(p_order_id);
    PERFORM qr_api.sp_referral_accrue_qr_order(p_order_id);

    SELECT ol.snapshot_package_name INTO v_package_name
    FROM qr_commerce.order_lines ol WHERE ol.order_id = p_order_id LIMIT 1;

    SELECT count(*) INTO v_qr_count FROM qr_commerce.qr_codes q WHERE q.order_id = p_order_id;
    v_qr_phrase := v_qr_count || ' ' || qr_api.fn_plural_ru(v_qr_count, 'QR-код', 'QR-кода', 'QR-кодов');

    IF v_user_id IS NOT NULL THEN
        BEGIN
            PERFORM qr_api.sp_user_notification_create(
                v_user_id,
                'order_paid',
                'Заказ оплачен',
                CASE
                    WHEN v_package_name IS NOT NULL THEN
                        'Пакет «' || v_package_name || '» (заказ № ' || v_order_number || '): начислено ' || v_qr_phrase || '. Доступны в личном кабинете.'
                    ELSE
                        'Заказ № ' || v_order_number || ' оплачен: начислено ' || v_qr_phrase || '. Доступны в личном кабинете.'
                END,
                'order',
                p_order_id,
                '/cabinet/purchases'
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'order_paid notification failed for order %: %', p_order_id, SQLERRM;
        END;
    END IF;

    payment_id := p_payment_id;
    order_id := p_order_id;
    RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_admin_mark_payout_paid(p_actor_user_id UUID, p_payout_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_paid BIGINT;
    v_pending BIGINT;
BEGIN
    PERFORM qr_api.sp_admin_assert_actor(p_actor_user_id);
    SELECT qr_api.sp_lookup_payout_status_id('paid') INTO v_paid;
    SELECT qr_api.sp_lookup_payout_status_id('pending') INTO v_pending;
    IF v_paid IS NULL OR v_pending IS NULL THEN
        RAISE EXCEPTION 'PAYOUT_STATUS_LOOKUP_FAILED';
    END IF;

    UPDATE qr_marketplace.executor_payouts
    SET status_id = v_paid, paid_at = now()
    WHERE id = p_payout_id AND status_id = v_pending;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'PAYOUT_NOT_FOUND';
    END IF;

    RETURN p_payout_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_admin_request_plaque_shipment(p_order_id UUID, p_admin_user_id UUID, p_delivery_address TEXT DEFAULT CAST(NULL AS TEXT), p_admin_notes TEXT DEFAULT CAST(NULL AS TEXT)) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order qr_commerce.orders%ROWTYPE;
    v_status_code VARCHAR;
    v_paid_id BIGINT;
    v_fulfilled_id BIGINT;
    v_pending_id BIGINT;
    v_line_qty INTEGER;
    v_address TEXT;
    v_notes TEXT;
    v_delivery RECORD;
    v_has_delivery BOOLEAN := FALSE;
    v_new_delivery_id UUID;
    v_shipment_num INTEGER;
BEGIN
    PERFORM qr_api.sp_admin_assert_actor(p_admin_user_id);

    SELECT * INTO v_order
    FROM qr_commerce.orders
    WHERE id = p_order_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;

    SELECT os.code INTO v_status_code
    FROM qr_ref.order_statuses os
    WHERE os.id = v_order.status_id;

    IF v_status_code NOT IN ('paid', 'fulfilled') AND v_order.paid_at IS NULL THEN
        RAISE EXCEPTION 'ORDER_NOT_PAID';
    END IF;

    SELECT id INTO v_paid_id FROM qr_ref.order_statuses WHERE code = 'paid';
    SELECT id INTO v_fulfilled_id FROM qr_ref.order_statuses WHERE code = 'fulfilled';
    SELECT id INTO v_pending_id FROM qr_ref.fulfillment_statuses WHERE code = 'pending';

    SELECT ol.quantity INTO v_line_qty
    FROM qr_commerce.order_lines ol
    WHERE ol.order_id = p_order_id
    LIMIT 1;

    IF v_line_qty IS NULL THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;

    v_notes := COALESCE(
        NULLIF(btrim(p_admin_notes), ''),
        CASE
            WHEN v_order.plaque_fulfillment_mode = 'self_print' THEN
                'Поддержка: перевод с самостоятельной печати на доставку'
            ELSE
                'Поддержка: повторная отправка QR'
        END
    );

    UPDATE qr_commerce.orders
    SET plaque_fulfillment_mode = 'ship',
        plaque_fulfillment_chosen_at = COALESCE(plaque_fulfillment_chosen_at, now()),
        status_id = CASE
            WHEN status_id = v_fulfilled_id THEN v_paid_id
            ELSE status_id
        END,
        updated_at = now(),
        updated_by_user_id = p_admin_user_id
    WHERE id = p_order_id;

    FOR v_delivery IN
        SELECT od.id, od.fulfillment_status_id, od.delivery_address, fs.code AS fs_code
        FROM qr_commerce.order_deliveries od
        JOIN qr_ref.fulfillment_statuses fs ON fs.id = od.fulfillment_status_id
        WHERE od.order_id = p_order_id
        FOR UPDATE OF od
    LOOP
        v_has_delivery := TRUE;
        v_address := COALESCE(NULLIF(btrim(p_delivery_address), ''), v_delivery.delivery_address);

        IF v_delivery.fs_code IN ('self_print', 'delivered', 'returned', 'failed') THEN
            INSERT INTO qr_commerce.fulfillment_status_history (
                order_delivery_id, from_status_id, to_status_id, notes, changed_by_user_id
            ) VALUES (
                v_delivery.id,
                v_delivery.fulfillment_status_id,
                v_pending_id,
                v_notes,
                p_admin_user_id
            );

            UPDATE qr_commerce.order_deliveries
            SET fulfillment_status_id = v_pending_id,
                delivery_address = v_address,
                carrier_id = NULL,
                tracking_number = NULL,
                shipped_at = NULL,
                delivered_at = NULL,
                returned_at = NULL,
                admin_notes = COALESCE(p_admin_notes, admin_notes),
                updated_at = now(),
                updated_by_user_id = p_admin_user_id
            WHERE id = v_delivery.id;
        ELSIF NULLIF(btrim(p_delivery_address), '') IS NOT NULL THEN
            UPDATE qr_commerce.order_deliveries
            SET delivery_address = btrim(p_delivery_address),
                updated_at = now(),
                updated_by_user_id = p_admin_user_id
            WHERE id = v_delivery.id;
        END IF;
    END LOOP;

    IF NOT v_has_delivery THEN
        v_address := NULLIF(btrim(p_delivery_address), '');
        IF v_address IS NULL THEN
            RAISE EXCEPTION 'DELIVERY_ADDRESS_REQUIRED';
        END IF;

        SELECT COALESCE(MAX(shipment_number), 0) + 1 INTO v_shipment_num
        FROM qr_commerce.order_deliveries
        WHERE order_id = p_order_id;

        v_new_delivery_id := uuidv7();
        INSERT INTO qr_commerce.order_deliveries (
            id, order_id, shipment_number, quantity, fulfillment_status_id, delivery_address,
            admin_notes, created_by_user_id, updated_by_user_id
        ) VALUES (
            v_new_delivery_id, p_order_id, COALESCE(v_shipment_num, 1), v_line_qty, v_pending_id,
            v_address, p_admin_notes, p_admin_user_id, p_admin_user_id
        );

        INSERT INTO qr_commerce.fulfillment_status_history (
            order_delivery_id, from_status_id, to_status_id, notes, changed_by_user_id
        ) VALUES (
            v_new_delivery_id, NULL, v_pending_id, v_notes, p_admin_user_id
        );
    END IF;

    RETURN p_order_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_admin_set_task_finance_mark(p_actor_user_id UUID, p_task_id UUID, p_status_code VARCHAR, p_party_code VARCHAR) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_status TEXT := nullif(btrim(coalesce(p_status_code, '')), '');
    v_party TEXT := nullif(btrim(coalesce(p_party_code, '')), '');
BEGIN
    PERFORM qr_api.sp_admin_assert_actor(p_actor_user_id);
    IF NOT EXISTS (
        SELECT 1 FROM qr_marketplace.service_tasks st WHERE st.id = p_task_id
    ) THEN
        RAISE EXCEPTION 'TASK_NOT_FOUND';
    END IF;
    IF v_status NOT IN ('pending', 'succeeded', 'cancelled', 'refund', 'open') THEN
        RAISE EXCEPTION 'INVALID_STATUS';
    END IF;
    IF v_party NOT IN ('customer', 'executor') THEN
        RAISE EXCEPTION 'INVALID_PARTY';
    END IF;
    INSERT INTO qr_commerce.admin_finance_task_marks (
        task_id, status_code, party_code, updated_by, updated_at
    ) VALUES (
        p_task_id, v_status, v_party, p_actor_user_id, now()
    )
    ON CONFLICT (task_id) DO UPDATE SET
        status_code = EXCLUDED.status_code,
        party_code = EXCLUDED.party_code,
        updated_by = EXCLUDED.updated_by,
        updated_at = now();
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_admin_soft_delete_user(p_actor_user_id UUID, p_user_id UUID) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
BEGIN
    PERFORM qr_api.sp_admin_assert_actor(p_actor_user_id);

    IF p_user_id = p_actor_user_id THEN
        RAISE EXCEPTION 'CANNOT_DELETE_SELF' USING ERRCODE = 'P0001';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM qr_identity.users u WHERE u.id = p_user_id AND u.deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION 'USER_NOT_FOUND' USING ERRCODE = 'P0001';
    END IF;

    UPDATE qr_identity.users
    SET deleted_at = now(),
        is_active = FALSE,
        updated_at = now(),
        updated_by_user_id = p_actor_user_id
    WHERE id = p_user_id AND deleted_at IS NULL;

    UPDATE qr_identity.refresh_tokens
    SET revoked_at = now()
    WHERE user_id = p_user_id AND revoked_at IS NULL;

    RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_admin_split_order_delivery(p_delivery_id UUID, p_admin_user_id UUID, p_split_quantity INT, p_new_address TEXT DEFAULT CAST(NULL AS TEXT)) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order_id UUID;
    v_current_qty INTEGER;
    v_new_shipment INTEGER;
    v_pending_status_id BIGINT;
    v_new_delivery_id UUID;
    v_address TEXT;
BEGIN
    PERFORM qr_api.sp_admin_assert_actor(p_admin_user_id);

    SELECT od.order_id, od.quantity, od.delivery_address
    INTO v_order_id, v_current_qty, v_address
    FROM qr_commerce.order_deliveries od
    WHERE od.id = p_delivery_id
    FOR UPDATE;

    IF v_order_id IS NULL THEN
        RAISE EXCEPTION 'ORDER_DELIVERY_NOT_FOUND';
    END IF;

    IF p_split_quantity IS NULL OR p_split_quantity < 1 OR p_split_quantity >= v_current_qty THEN
        RAISE EXCEPTION 'INVALID_SPLIT_QUANTITY';
    END IF;

    SELECT id INTO v_pending_status_id FROM qr_ref.fulfillment_statuses WHERE code = 'pending';

    UPDATE qr_commerce.order_deliveries
    SET quantity = v_current_qty - p_split_quantity,
        updated_by_user_id = p_admin_user_id
    WHERE id = p_delivery_id;

    SELECT COALESCE(MAX(shipment_number), 0) + 1 INTO v_new_shipment
    FROM qr_commerce.order_deliveries
    WHERE order_id = v_order_id;

    v_new_delivery_id := uuidv7();

    INSERT INTO qr_commerce.order_deliveries (
        id, order_id, shipment_number, quantity, fulfillment_status_id, delivery_address,
        created_by_user_id, updated_by_user_id
    ) VALUES (
        v_new_delivery_id, v_order_id, v_new_shipment, p_split_quantity, v_pending_status_id,
        COALESCE(NULLIF(btrim(p_new_address), ''), v_address),
        p_admin_user_id, p_admin_user_id
    );

    RETURN v_new_delivery_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_admin_update_order_delivery(p_delivery_id UUID, p_admin_user_id UUID, p_fulfillment_status_code VARCHAR, p_carrier_code VARCHAR DEFAULT CAST(NULL AS VARCHAR), p_tracking_number VARCHAR DEFAULT CAST(NULL AS VARCHAR), p_admin_notes TEXT DEFAULT CAST(NULL AS TEXT), p_destination_code VARCHAR DEFAULT CAST(NULL AS VARCHAR)) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order_id UUID;
    v_from_status_id BIGINT;
    v_to_status_id BIGINT;
    v_carrier_id BIGINT;
    v_current_order_status_code VARCHAR;
    v_dest VARCHAR(32);
BEGIN
    PERFORM qr_api.sp_admin_assert_actor(p_admin_user_id);

    SELECT od.order_id, od.fulfillment_status_id, os.code
    INTO v_order_id, v_from_status_id, v_current_order_status_code
    FROM qr_commerce.order_deliveries od
    JOIN qr_commerce.orders o ON o.id = od.order_id
    JOIN qr_ref.order_statuses os ON os.id = o.status_id
    WHERE od.id = p_delivery_id
    FOR UPDATE OF od, o;

    IF v_order_id IS NULL THEN
        RAISE EXCEPTION 'ORDER_DELIVERY_NOT_FOUND';
    END IF;

    IF v_current_order_status_code NOT IN ('paid', 'fulfilled') THEN
        RAISE EXCEPTION 'ORDER_NOT_PAID';
    END IF;

    SELECT id INTO v_to_status_id
    FROM qr_ref.fulfillment_statuses
    WHERE code = p_fulfillment_status_code;

    IF v_to_status_id IS NULL THEN
        RAISE EXCEPTION 'FULFILLMENT_STATUS_NOT_FOUND';
    END IF;

    IF p_carrier_code IS NOT NULL AND btrim(p_carrier_code) <> '' THEN
        SELECT id INTO v_carrier_id
        FROM qr_ref.delivery_carriers
        WHERE code = p_carrier_code;
        IF v_carrier_id IS NULL THEN
            RAISE EXCEPTION 'CARRIER_NOT_FOUND';
        END IF;
    END IF;

    v_dest := NULLIF(lower(btrim(coalesce(p_destination_code, ''))), '');
    IF v_dest IS NOT NULL
       AND v_dest NOT IN ('pickup_point', 'to_door', 'agreed_place') THEN
        RAISE EXCEPTION 'INVALID_DESTINATION_CODE';
    END IF;

    UPDATE qr_commerce.order_deliveries
    SET
        fulfillment_status_id = v_to_status_id,
        carrier_id = COALESCE(v_carrier_id, carrier_id),
        tracking_number = COALESCE(NULLIF(btrim(p_tracking_number), ''), tracking_number),
        destination_code = COALESCE(v_dest, destination_code),
        admin_notes = COALESCE(p_admin_notes, admin_notes),
        shipped_at = CASE
            WHEN p_fulfillment_status_code IN ('shipped', 'in_transit')
                 AND shipped_at IS NULL THEN now()
            ELSE shipped_at
        END,
        delivered_at = CASE
            WHEN p_fulfillment_status_code = 'delivered' THEN now()
            WHEN p_fulfillment_status_code IN ('returned', 'failed') THEN NULL
            ELSE delivered_at
        END,
        returned_at = CASE
            WHEN p_fulfillment_status_code = 'returned' THEN now()
            ELSE returned_at
        END,
        updated_by_user_id = p_admin_user_id
    WHERE id = p_delivery_id;

    INSERT INTO qr_commerce.fulfillment_status_history (
        order_delivery_id, from_status_id, to_status_id,
        carrier_id, tracking_number, notes, changed_by_user_id
    )
    SELECT
        p_delivery_id,
        v_from_status_id,
        v_to_status_id,
        COALESCE(v_carrier_id, od.carrier_id),
        COALESCE(NULLIF(btrim(p_tracking_number), ''), od.tracking_number),
        p_admin_notes,
        p_admin_user_id
    FROM qr_commerce.order_deliveries od
    WHERE od.id = p_delivery_id;

    PERFORM qr_api.sp_try_mark_order_fulfilled(v_order_id);

    RETURN p_delivery_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_apply_payment_succeeded(p_provider_payment_id VARCHAR) RETURNS TABLE (payment_id UUID, order_id UUID) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_payment_id UUID;
    v_order_id UUID;
    v_pay_status_code VARCHAR;
    v_succeeded_status_id BIGINT;
    v_paid_order_status_id BIGINT;
    v_user_id UUID;
    v_order_number BIGINT;
    v_package_name VARCHAR;
    v_qr_count BIGINT;
    v_qr_phrase TEXT;
BEGIN
    SELECT id INTO v_succeeded_status_id FROM qr_ref.payment_statuses WHERE code = 'succeeded';
    SELECT id INTO v_paid_order_status_id FROM qr_ref.order_statuses WHERE code = 'paid';

    IF v_succeeded_status_id IS NULL OR v_paid_order_status_id IS NULL THEN
        RAISE EXCEPTION 'PAYMENT_STATUS_LOOKUP_FAILED'
            USING ERRCODE = 'data_exception';
    END IF;

    SELECT p.id, p.order_id, ps.code
    INTO v_payment_id, v_order_id, v_pay_status_code
    FROM qr_commerce.payments p
    JOIN qr_ref.payment_statuses ps ON ps.id = p.status_id
    WHERE p.provider = 'yookassa' AND p.provider_payment_id = p_provider_payment_id
    LIMIT 1;

    IF v_payment_id IS NULL THEN
        RETURN;
    END IF;

    -- Сериализуем параллельные вебхуки по заказу.
    PERFORM 1 FROM qr_commerce.orders WHERE id = v_order_id FOR UPDATE;

    -- Идемпотентность: платёж уже проведён (повтор webhook / sync) — не дублируем
    -- сайд-эффекты (генерация QR, уведомление), возвращаем результат как есть.
    IF v_pay_status_code = 'succeeded' THEN
        payment_id := v_payment_id;
        order_id := v_order_id;
        RETURN NEXT;
        RETURN;
    END IF;

    UPDATE qr_commerce.payments
    SET status_id = v_succeeded_status_id, paid_at = now()
    WHERE id = v_payment_id;

    UPDATE qr_commerce.orders
    SET status_id = v_paid_order_status_id, paid_at = now()
    WHERE id = v_order_id;

    SELECT o.user_id, o.order_number, ol.snapshot_package_name
    INTO v_user_id, v_order_number, v_package_name
    FROM qr_commerce.orders o
    LEFT JOIN qr_commerce.order_lines ol ON ol.order_id = o.id
    WHERE o.id = v_order_id
    LIMIT 1;

    PERFORM qr_api.sp_generate_qr_codes_for_order(v_order_id);
    PERFORM qr_api.sp_referral_accrue_qr_order(v_order_id);

    -- Важно: order_id без префикса таблицы = OUT-параметр RETURNS TABLE (NULL до присвоения)
    SELECT count(*) INTO v_qr_count FROM qr_commerce.qr_codes q WHERE q.order_id = v_order_id;
    v_qr_phrase := v_qr_count || ' ' || qr_api.fn_plural_ru(v_qr_count, 'QR-код', 'QR-кода', 'QR-кодов');

    IF v_user_id IS NOT NULL THEN
        BEGIN
            PERFORM qr_api.sp_user_notification_create(
                v_user_id,
                'order_paid',
                'Заказ оплачен',
                CASE
                    WHEN v_package_name IS NOT NULL THEN
                        'Пакет «' || v_package_name || '» (заказ № ' || v_order_number || '): начислено ' || v_qr_phrase || '. Доступны в личном кабинете.'
                    ELSE
                        'Заказ № ' || v_order_number || ' оплачен: начислено ' || v_qr_phrase || '. Доступны в личном кабинете.'
                END,
                'order',
                v_order_id,
                '/cabinet/purchases'
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'order_paid notification failed for order %: %', v_order_id, SQLERRM;
        END;
    END IF;

    payment_id := v_payment_id;
    order_id := v_order_id;
    RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_assign_qr_to_memorial(p_qr_code_id UUID, p_memorial_id UUID, p_user_id UUID) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_owner UUID;
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM qr_commerce.qr_codes q
        JOIN qr_commerce.orders o ON o.id = q.order_id
        JOIN qr_ref.order_statuses os ON os.id = o.status_id
        JOIN qr_identity.users u ON u.id = p_user_id
        WHERE q.id = p_qr_code_id
          AND q.memorial_id IS NULL
          AND os.code = 'paid'
          AND (
              o.user_id = p_user_id
              OR (o.user_id IS NULL AND lower(o.buyer_email::text) = lower(u.email::text))
          )
    ) THEN
        RAISE EXCEPTION 'QR_NOT_AVAILABLE'
            USING ERRCODE = 'no_data_found';
    END IF;

    SELECT owner_user_id INTO v_owner
    FROM qr_memorial.memorials
    WHERE id = p_memorial_id AND deleted_at IS NULL;

    IF v_owner IS NULL OR v_owner <> p_user_id THEN
        RAISE EXCEPTION 'MEMORIAL_NOT_FOUND'
            USING ERRCODE = 'no_data_found';
    END IF;

    UPDATE qr_commerce.qr_codes
    SET memorial_id = p_memorial_id
    WHERE id = p_qr_code_id AND memorial_id IS NULL;

    RETURN FOUND;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_change_password(p_user_id UUID, p_new_password_hash VARCHAR) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
BEGIN
    IF p_new_password_hash IS NULL OR btrim(p_new_password_hash) = '' THEN
        RAISE EXCEPTION 'INVALID_PASSWORD' USING ERRCODE = 'P0001';
    END IF;

    UPDATE qr_identity.users
    SET password_hash = p_new_password_hash,
        must_change_password = FALSE,
        suggest_password_change = FALSE,
        password_change_reminded_at = NULL,
        updated_at = now()
    WHERE id = p_user_id AND deleted_at IS NULL;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'USER_NOT_FOUND' USING ERRCODE = 'P0001';
    END IF;

    RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_add_document(p_user_id UUID, p_document_type_code VARCHAR, p_storage_key VARCHAR, p_original_filename VARCHAR, p_document_number VARCHAR, p_note TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_company_id UUID;
    v_status_code VARCHAR;
    v_tier VARCHAR;
    v_doc_type_id BIGINT;
    v_doc_tier VARCHAR;
    v_doc_id UUID;
BEGIN
    SELECT c.id, cvs.code, let.contractor_tier
      INTO v_company_id, v_status_code, v_tier
    FROM qr_marketplace.company_members cm
    JOIN qr_marketplace.companies c ON c.id = cm.company_id AND c.deleted_at IS NULL
    JOIN qr_ref.company_verification_statuses cvs ON cvs.id = c.verification_status_id
    JOIN qr_ref.legal_entity_types let ON let.id = c.legal_entity_type_id
    WHERE cm.user_id = p_user_id
    ORDER BY cm.invited_at
    LIMIT 1;

    IF v_company_id IS NULL THEN
        RAISE EXCEPTION 'COMPANY_NOT_FOUND';
    END IF;

    IF v_status_code NOT IN ('draft', 'rejected') THEN
        RAISE EXCEPTION 'COMPANY_NOT_EDITABLE';
    END IF;

    SELECT id, contractor_tier INTO v_doc_type_id, v_doc_tier
    FROM qr_ref.company_document_types
    WHERE code = p_document_type_code;
    IF v_doc_type_id IS NULL THEN
        RAISE EXCEPTION 'DOCUMENT_TYPE_NOT_FOUND';
    END IF;
    IF v_doc_tier IS DISTINCT FROM v_tier THEN
        RAISE EXCEPTION 'DOCUMENT_TYPE_WRONG_TIER';
    END IF;

    UPDATE qr_marketplace.company_verification_documents SET
        storage_key = COALESCE(p_storage_key, storage_key),
        original_filename = COALESCE(p_original_filename, original_filename),
        document_number = COALESCE(p_document_number, document_number),
        note = COALESCE(p_note, note),
        uploaded_by_user_id = p_user_id
    WHERE company_id = v_company_id AND document_type_id = v_doc_type_id
    RETURNING id INTO v_doc_id;

    IF v_doc_id IS NULL THEN
        INSERT INTO qr_marketplace.company_verification_documents (
            company_id, document_type_id, storage_key, original_filename,
            document_number, note, uploaded_by_user_id
        ) VALUES (
            v_company_id, v_doc_type_id, p_storage_key, p_original_filename,
            p_document_number, p_note, p_user_id
        )
        RETURNING id INTO v_doc_id;
    END IF;

    RETURN v_doc_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_assert_can_sell_products(p_company_id UUID) RETURNS void LANGUAGE plpgsql STABLE AS $$
BEGIN
    IF p_company_id IS NULL OR NOT COALESCE(qr_api.sp_company_can_sell_products(p_company_id), FALSE) THEN
        RAISE EXCEPTION 'COMPANY_CANNOT_SELL_PRODUCTS';
    END IF;
END;
$$

CREATE OR REPLACE FUNCTION qr_api.sp_company_delete_document(p_user_id UUID, p_document_id UUID) RETURNS VARCHAR LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_company_id UUID;
    v_status_code VARCHAR;
    v_storage_key VARCHAR;
BEGIN
    SELECT c.id, cvs.code INTO v_company_id, v_status_code
    FROM qr_marketplace.company_members cm
    JOIN qr_marketplace.companies c ON c.id = cm.company_id AND c.deleted_at IS NULL
    JOIN qr_ref.company_verification_statuses cvs ON cvs.id = c.verification_status_id
    WHERE cm.user_id = p_user_id
    ORDER BY cm.invited_at
    LIMIT 1;

    IF v_company_id IS NULL THEN
        RAISE EXCEPTION 'COMPANY_NOT_FOUND';
    END IF;
    IF v_status_code NOT IN ('draft', 'rejected') THEN
        RAISE EXCEPTION 'COMPANY_NOT_EDITABLE';
    END IF;

    DELETE FROM qr_marketplace.company_verification_documents
    WHERE id = p_document_id AND company_id = v_company_id
    RETURNING storage_key INTO v_storage_key;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'DOCUMENT_NOT_FOUND';
    END IF;

    RETURN v_storage_key;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_ensure_referral_code(p_company_id UUID) RETURNS VARCHAR LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_code VARCHAR(16);
BEGIN
    SELECT referral_code INTO v_code
    FROM qr_marketplace.companies
    WHERE id = p_company_id AND deleted_at IS NULL
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'COMPANY_NOT_FOUND';
    END IF;
    IF v_code IS NULL OR btrim(v_code) = '' THEN
        v_code := qr_api.sp_company_generate_referral_code();
        UPDATE qr_marketplace.companies
        SET referral_code = v_code, updated_at = now()
        WHERE id = p_company_id;
    END IF;
    RETURN v_code;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_generate_referral_code() RETURNS VARCHAR LANGUAGE plpgsql AS $$
DECLARE
    v_code VARCHAR(16);
    v_alphabet TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    i INT;
BEGIN
    LOOP
        v_code := '';
        FOR i IN 1..8 LOOP
            v_code := v_code || substr(v_alphabet, 1 + floor(random() * length(v_alphabet))::INT, 1);
        END LOOP;
        EXIT WHEN NOT EXISTS (
            SELECT 1 FROM qr_marketplace.companies c WHERE c.referral_code = v_code AND c.deleted_at IS NULL
        ) AND NOT EXISTS (
            SELECT 1 FROM qr_identity.users u WHERE u.referral_code = v_code AND u.deleted_at IS NULL
        );
    END LOOP;
    RETURN v_code;
END;
$$

CREATE OR REPLACE FUNCTION qr_api.sp_company_product_add(p_user_id UUID, p_kind VARCHAR, p_title VARCHAR, p_description TEXT, p_image_url TEXT, p_price_rub DECIMAL, p_warranty_years INT, p_manufacturer VARCHAR) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_company_id UUID;
    v_id UUID;
    v_title VARCHAR;
    v_manufacturer VARCHAR;
BEGIN
    v_company_id := qr_api.sp_company_id_for_user(p_user_id);
    IF v_company_id IS NULL THEN RAISE EXCEPTION 'COMPANY_NOT_FOUND'; END IF;
    PERFORM qr_api.sp_company_assert_can_sell_products(v_company_id);
    IF p_kind NOT IN ('wreath', 'monument') THEN RAISE EXCEPTION 'INVALID_KIND'; END IF;
    v_title := btrim(coalesce(p_title, ''));
    IF v_title = '' THEN RAISE EXCEPTION 'EMPTY_TITLE'; END IF;
    IF p_warranty_years IS NULL OR p_warranty_years < 1 OR p_warranty_years > 50 THEN
        RAISE EXCEPTION 'INVALID_WARRANTY';
    END IF;
    v_manufacturer := left(btrim(coalesce(p_manufacturer, '')), 50);
    IF v_manufacturer = '' THEN RAISE EXCEPTION 'EMPTY_MANUFACTURER'; END IF;

    v_id := uuidv7();
    INSERT INTO qr_marketplace.company_products (
        id, company_id, kind, title, description, image_url, price_rub, warranty_years, manufacturer
    )
    VALUES (
        v_id, v_company_id, p_kind, left(v_title, 256),
        NULLIF(btrim(coalesce(p_description, '')), ''),
        NULLIF(btrim(coalesce(p_image_url, '')), ''),
        p_price_rub,
        p_warranty_years,
        v_manufacturer
    );
    RETURN v_id;
END;
$function$

