CREATE OR REPLACE FUNCTION qr_api.sp_company_product_listing_from_wallet(p_user_id UUID, p_product_count INT, p_items_json JSONB) RETURNS INT LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_company_id UUID;
    v_fee INTEGER;
    v_item JSONB;
    v_title VARCHAR;
    v_kind VARCHAR;
    v_warranty INTEGER;
    v_manufacturer VARCHAR;
    v_payment_id UUID;
BEGIN
    v_company_id := qr_api.sp_company_id_for_user(p_user_id);
    IF v_company_id IS NULL THEN RAISE EXCEPTION 'COMPANY_NOT_FOUND'; END IF;
    PERFORM qr_api.sp_company_assert_can_sell_products(v_company_id);
    IF p_product_count IS NULL OR p_product_count < 1 OR p_product_count > 50 THEN
        RAISE EXCEPTION 'INVALID_PRODUCT_COUNT';
    END IF;
    IF jsonb_typeof(p_items_json) <> 'array' OR jsonb_array_length(p_items_json) <> p_product_count THEN
        RAISE EXCEPTION 'INVALID_ITEMS';
    END IF;

    v_fee := p_product_count * 50;
    v_payment_id := uuidv7();
    PERFORM qr_api.sp_wallet_debit(
        p_user_id,
        v_fee,
        'listing_fee',
        'listing',
        v_payment_id,
        format('Размещение %s товар(ов) на витрине', p_product_count),
        v_payment_id
    );

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items_json)
    LOOP
        v_kind := v_item->>'kind';
        IF v_kind NOT IN ('wreath', 'monument') THEN
            RAISE EXCEPTION 'INVALID_KIND';
        END IF;
        v_title := btrim(coalesce(v_item->>'title', ''));
        IF v_title = '' THEN RAISE EXCEPTION 'EMPTY_TITLE'; END IF;
        BEGIN
            v_warranty := (v_item->>'warranty_years')::INTEGER;
        EXCEPTION WHEN OTHERS THEN
            RAISE EXCEPTION 'INVALID_WARRANTY';
        END;
        IF v_warranty IS NULL OR v_warranty < 1 OR v_warranty > 50 THEN
            RAISE EXCEPTION 'INVALID_WARRANTY';
        END IF;
        v_manufacturer := left(btrim(coalesce(v_item->>'manufacturer', '')), 50);
        IF v_manufacturer = '' THEN RAISE EXCEPTION 'EMPTY_MANUFACTURER'; END IF;

        INSERT INTO qr_marketplace.company_products (
            company_id, kind, title, description, image_url, price_rub,
            warranty_years, manufacturer, is_active
        ) VALUES (
            v_company_id,
            v_kind,
            left(v_title, 256),
            NULLIF(btrim(coalesce(v_item->>'description', '')), ''),
            NULLIF(btrim(coalesce(v_item->>'image_url', '')), ''),
            NULLIF(v_item->>'price_rub', '')::NUMERIC,
            v_warranty,
            v_manufacturer,
            TRUE
        );
    END LOOP;

    RETURN p_product_count;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_product_listing_payment_apply(p_provider_payment_id VARCHAR) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_pay RECORD;
    v_succeeded BIGINT;
    v_waiting BIGINT;
    v_item JSONB;
    v_title VARCHAR;
    v_kind VARCHAR;
    v_warranty INTEGER;
    v_manufacturer VARCHAR;
BEGIN
    SELECT id INTO v_succeeded FROM qr_ref.payment_statuses WHERE code = 'succeeded';
    SELECT id INTO v_waiting FROM qr_ref.payment_statuses WHERE code = 'waiting';
    IF v_succeeded IS NULL OR v_waiting IS NULL THEN RAISE EXCEPTION 'PAYMENT_STATUS_MISSING'; END IF;

    SELECT * INTO v_pay
    FROM qr_marketplace.company_product_listing_payments
    WHERE provider_payment_id = p_provider_payment_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    IF v_pay.status_id = v_succeeded THEN
        RETURN v_pay.id; -- idempotent
    END IF;
    IF v_pay.status_id <> v_waiting THEN
        RAISE EXCEPTION 'INVALID_PAYMENT_STATUS';
    END IF;

    FOR v_item IN SELECT * FROM jsonb_array_elements(v_pay.items_json)
    LOOP
        v_kind := v_item->>'kind';
        IF v_kind NOT IN ('wreath', 'monument') THEN
            RAISE EXCEPTION 'INVALID_KIND';
        END IF;
        v_title := btrim(coalesce(v_item->>'title', ''));
        IF v_title = '' THEN RAISE EXCEPTION 'EMPTY_TITLE'; END IF;
        BEGIN
            v_warranty := (v_item->>'warranty_years')::INTEGER;
        EXCEPTION WHEN OTHERS THEN
            RAISE EXCEPTION 'INVALID_WARRANTY';
        END;
        IF v_warranty IS NULL OR v_warranty < 1 OR v_warranty > 50 THEN
            RAISE EXCEPTION 'INVALID_WARRANTY';
        END IF;
        v_manufacturer := left(btrim(coalesce(v_item->>'manufacturer', '')), 50);
        IF v_manufacturer = '' THEN RAISE EXCEPTION 'EMPTY_MANUFACTURER'; END IF;

        INSERT INTO qr_marketplace.company_products (
            company_id, kind, title, description, image_url, price_rub,
            warranty_years, manufacturer, is_active
        ) VALUES (
            v_pay.company_id,
            v_kind,
            left(v_title, 256),
            NULLIF(btrim(coalesce(v_item->>'description', '')), ''),
            NULLIF(btrim(coalesce(v_item->>'image_url', '')), ''),
            NULLIF(v_item->>'price_rub', '')::NUMERIC,
            v_warranty,
            v_manufacturer,
            TRUE
        );
    END LOOP;

    UPDATE qr_marketplace.company_product_listing_payments
    SET status_id = v_succeeded,
        paid_at = now(),
        updated_at = now()
    WHERE id = v_pay.id;

    RETURN v_pay.id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_product_listing_payment_create(p_user_id UUID, p_payment_id UUID, p_idempotence_key UUID, p_product_count INT, p_unit_price_rub DECIMAL, p_amount_rub DECIMAL, p_items_json JSONB, p_provider_payment_id VARCHAR, p_confirmation_url TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_company_id UUID;
    v_waiting BIGINT;
BEGIN
    v_company_id := qr_api.sp_company_id_for_user(p_user_id);
    IF v_company_id IS NULL THEN RAISE EXCEPTION 'COMPANY_NOT_FOUND'; END IF;
    PERFORM qr_api.sp_company_assert_can_sell_products(v_company_id);
    IF p_product_count IS NULL OR p_product_count < 1 OR p_product_count > 50 THEN
        RAISE EXCEPTION 'INVALID_PRODUCT_COUNT';
    END IF;
    IF jsonb_typeof(p_items_json) <> 'array' OR jsonb_array_length(p_items_json) <> p_product_count THEN
        RAISE EXCEPTION 'INVALID_ITEMS';
    END IF;
    IF p_amount_rub IS DISTINCT FROM (p_unit_price_rub * p_product_count) THEN
        RAISE EXCEPTION 'AMOUNT_MISMATCH';
    END IF;

    SELECT id INTO v_waiting FROM qr_ref.payment_statuses WHERE code = 'waiting';
    IF v_waiting IS NULL THEN RAISE EXCEPTION 'PAYMENT_STATUS_MISSING'; END IF;

    INSERT INTO qr_marketplace.company_product_listing_payments (
        id, company_id, paid_by_user_id, status_id,
        product_count, unit_price_rub, amount_rub, items_json,
        provider, provider_payment_id, idempotence_key, confirmation_url
    ) VALUES (
        p_payment_id, v_company_id, p_user_id, v_waiting,
        p_product_count, p_unit_price_rub, p_amount_rub, p_items_json,
        'yookassa', p_provider_payment_id, p_idempotence_key, p_confirmation_url
    );
    RETURN p_payment_id;
END;
$function$

