CREATE OR REPLACE FUNCTION qr_api.sp_company_regenerate_referral_code(p_user_id UUID) RETURNS VARCHAR LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_company_id UUID;
    v_code VARCHAR;
BEGIN
    SELECT cm.company_id INTO v_company_id
    FROM qr_marketplace.company_members cm
    JOIN qr_marketplace.companies c ON c.id = cm.company_id
    WHERE cm.user_id = p_user_id AND c.deleted_at IS NULL
    LIMIT 1;
    IF v_company_id IS NULL THEN
        RAISE EXCEPTION 'COMPANY_NOT_FOUND';
    END IF;
    v_code := qr_api.sp_company_generate_referral_code();
    UPDATE qr_marketplace.companies
    SET referral_code = v_code, updated_at = now()
    WHERE id = v_company_id;
    RETURN v_code;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_register(p_user_id UUID, p_legal_entity_type_code VARCHAR, p_inn VARCHAR, p_kpp VARCHAR, p_ogrn VARCHAR, p_legal_name VARCHAR, p_short_name VARCHAR, p_legal_address TEXT, p_actual_address TEXT, p_public_email citext, p_public_phone VARCHAR, p_website VARCHAR, p_description TEXT, p_contact_person_name VARCHAR, p_contact_person_position VARCHAR, p_vat_payer BOOLEAN, p_vat_rate DECIMAL, p_bank_name VARCHAR, p_bik VARCHAR, p_correspondent_account VARCHAR, p_settlement_account VARCHAR) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_company_id UUID;
    v_draft_status_id BIGINT;
    v_entity_type_id BIGINT;
    v_tier VARCHAR;
BEGIN
    IF EXISTS (
        SELECT 1 FROM qr_marketplace.company_members cm
        JOIN qr_marketplace.companies c ON c.id = cm.company_id
        WHERE cm.user_id = p_user_id AND c.deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION 'COMPANY_ALREADY_EXISTS_FOR_USER'
            USING ERRCODE = 'unique_violation';
    END IF;

    IF p_inn IS NOT NULL AND EXISTS (
        SELECT 1 FROM qr_marketplace.companies c
        WHERE c.inn = p_inn AND c.deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION 'INN_ALREADY_REGISTERED'
            USING ERRCODE = 'unique_violation';
    END IF;

    SELECT qr_api.sp_lookup_company_verification_status_id('draft') INTO v_draft_status_id;
    SELECT qr_api.sp_lookup_legal_entity_type_id(p_legal_entity_type_code) INTO v_entity_type_id;

    IF v_draft_status_id IS NULL OR v_entity_type_id IS NULL THEN
        RAISE EXCEPTION 'LOOKUP_NOT_FOUND';
    END IF;

    SELECT contractor_tier INTO v_tier
    FROM qr_ref.legal_entity_types WHERE id = v_entity_type_id;

    IF v_tier = 'big' THEN
        IF p_inn IS NULL OR p_ogrn IS NULL OR btrim(coalesce(p_legal_name, '')) = ''
           OR btrim(coalesce(p_legal_address, '')) = '' THEN
            RAISE EXCEPTION 'BIG_COMPANY_REQUISITES_REQUIRED';
        END IF;
        IF p_bank_name IS NULL OR p_bik IS NULL
           OR p_correspondent_account IS NULL OR p_settlement_account IS NULL THEN
            RAISE EXCEPTION 'BANK_REQUIRED';
        END IF;
    ELSIF v_tier = 'small' THEN
        IF btrim(coalesce(p_legal_name, '')) = '' THEN
            RAISE EXCEPTION 'FULL_NAME_REQUIRED';
        END IF;
        IF p_bank_name IS NULL OR p_bik IS NULL
           OR p_correspondent_account IS NULL OR p_settlement_account IS NULL THEN
            RAISE EXCEPTION 'BANK_REQUIRED';
        END IF;
    ELSE
        RAISE EXCEPTION 'LOOKUP_NOT_FOUND';
    END IF;

    INSERT INTO qr_marketplace.companies (
        verification_status_id, legal_entity_type_id,
        inn, kpp, ogrn, legal_name, short_name,
        legal_address, actual_address,
        public_email, public_phone, website, description,
        contact_person_name, contact_person_position,
        vat_payer, vat_rate, is_active, owner_user_id
    ) VALUES (
        v_draft_status_id, v_entity_type_id,
        p_inn, p_kpp, p_ogrn, p_legal_name, p_short_name,
        p_legal_address, p_actual_address,
        p_public_email, p_public_phone, p_website, p_description,
        p_contact_person_name, p_contact_person_position,
        coalesce(p_vat_payer, FALSE), p_vat_rate, FALSE, p_user_id
    )
    RETURNING id INTO v_company_id;

    INSERT INTO qr_marketplace.company_members (company_id, user_id, job_title, is_primary_contact, accepted_at)
    VALUES (v_company_id, p_user_id, p_contact_person_position, TRUE, now());

    IF p_bank_name IS NOT NULL AND p_bik IS NOT NULL THEN
        INSERT INTO qr_marketplace.company_bank_details (
            company_id, bank_name, bik, correspondent_account, settlement_account
        ) VALUES (
            v_company_id, p_bank_name, p_bik, p_correspondent_account, p_settlement_account
        );
    END IF;

    PERFORM qr_api.sp_company_ensure_referral_code(v_company_id);

    RETURN v_company_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_reject(p_company_id UUID, p_admin_user_id UUID, p_reason TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE v_rejected BIGINT;
BEGIN
    PERFORM qr_api.sp_admin_assert_actor(p_admin_user_id);
    SELECT qr_api.sp_lookup_company_verification_status_id('rejected') INTO v_rejected;
    UPDATE qr_marketplace.companies SET verification_status_id = v_rejected, rejection_reason = p_reason,
        verified_by_user_id = p_admin_user_id
    WHERE id = p_company_id AND deleted_at IS NULL;
    RETURN p_company_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_review_create(p_user_id UUID, p_kind VARCHAR, p_entity_id UUID, p_rating INT, p_body TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_kind VARCHAR;
    v_body TEXT;
    v_name VARCHAR;
    v_company UUID;
    v_id UUID;
    v_task RECORD;
    v_order RECORD;
    v_member RECORD;
BEGIN
    v_kind := lower(btrim(coalesce(p_kind, '')));
    IF v_kind NOT IN ('task', 'product') THEN
        RAISE EXCEPTION 'INVALID_KIND';
    END IF;
    IF p_rating IS NULL OR p_rating < 1 OR p_rating > 5 THEN
        RAISE EXCEPTION 'INVALID_RATING';
    END IF;
    v_body := btrim(coalesce(p_body, ''));
    IF char_length(v_body) < 10 THEN
        RAISE EXCEPTION 'REVIEW_TEXT_TOO_SHORT';
    END IF;
    IF char_length(v_body) > 500 THEN
        RAISE EXCEPTION 'REVIEW_TEXT_TOO_LONG';
    END IF;

    SELECT left(btrim(coalesce(full_name, '')), 80) INTO v_name
    FROM qr_identity.users WHERE id = p_user_id AND deleted_at IS NULL;
    IF v_name IS NULL OR v_name = '' THEN
        RAISE EXCEPTION 'REVIEW_NAME_REQUIRED';
    END IF;

    IF v_kind = 'task' THEN
        SELECT st.id, st.customer_user_id, st.assigned_company_id, sts.code AS status_code
        INTO v_task
        FROM qr_marketplace.service_tasks st
        JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
        WHERE st.id = p_entity_id;
        IF NOT FOUND THEN RAISE EXCEPTION 'TASK_NOT_FOUND'; END IF;
        IF v_task.customer_user_id <> p_user_id THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
        IF v_task.status_code <> 'completed' THEN RAISE EXCEPTION 'REVIEW_NOT_ELIGIBLE'; END IF;
        IF v_task.assigned_company_id IS NULL THEN RAISE EXCEPTION 'REVIEW_NOT_ELIGIBLE'; END IF;
        IF EXISTS (
            SELECT 1 FROM qr_marketplace.company_reviews r
            WHERE r.service_task_id = p_entity_id AND r.deleted_at IS NULL
        ) THEN
            RAISE EXCEPTION 'REVIEW_ALREADY_EXISTS';
        END IF;
        v_company := v_task.assigned_company_id;
        v_id := uuidv7();
        INSERT INTO qr_marketplace.company_reviews (
            id, company_id, author_user_id, kind, rating, body, author_name, service_task_id
        ) VALUES (
            v_id, v_company, p_user_id, 'task', p_rating, v_body, v_name, p_entity_id
        );
    ELSE
        SELECT o.id, o.buyer_user_id, o.company_id, os.code AS status_code, fs.code AS ful_code
        INTO v_order
        FROM qr_marketplace.company_shop_orders o
        JOIN qr_ref.order_statuses os ON os.id = o.status_id
        JOIN qr_ref.fulfillment_statuses fs ON fs.id = o.fulfillment_status_id
        WHERE o.id = p_entity_id;
        IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_NOT_FOUND'; END IF;
        IF v_order.buyer_user_id <> p_user_id THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
        IF v_order.status_code <> 'fulfilled' OR v_order.ful_code <> 'completed' THEN
            RAISE EXCEPTION 'REVIEW_NOT_ELIGIBLE';
        END IF;
        IF EXISTS (
            SELECT 1 FROM qr_marketplace.company_reviews r
            WHERE r.shop_order_id = p_entity_id AND r.deleted_at IS NULL
        ) THEN
            RAISE EXCEPTION 'REVIEW_ALREADY_EXISTS';
        END IF;
        v_company := v_order.company_id;
        v_id := uuidv7();
        INSERT INTO qr_marketplace.company_reviews (
            id, company_id, author_user_id, kind, rating, body, author_name, shop_order_id
        ) VALUES (
            v_id, v_company, p_user_id, 'product', p_rating, v_body, v_name, p_entity_id
        );
    END IF;

    PERFORM qr_api.sp_company_reviews_recalc(v_company);

    FOR v_member IN
        SELECT cm.user_id FROM qr_marketplace.company_members cm WHERE cm.company_id = v_company
    LOOP
        BEGIN
            PERFORM qr_api.sp_user_notification_create(
                v_member.user_id,
                'company_review_received',
                'Новый отзыв о компании',
                left(v_body, 200),
                'company_review',
                v_id,
                '/cabinet/executor?tab=reviews'
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'company review notification failed: %', SQLERRM;
        END;
    END LOOP;

    RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_review_invite_shop_order(p_order_id UUID) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_buyer UUID;
    v_title TEXT;
    v_number BIGINT;
    v_count INTEGER;
    v_label TEXT;
BEGIN
    SELECT o.buyer_user_id, o.order_number
    INTO v_buyer, v_number
    FROM qr_marketplace.company_shop_orders o
    WHERE o.id = p_order_id;
    IF v_buyer IS NULL THEN
        RETURN;
    END IF;
    SELECT l.title, count(*) OVER ()
    INTO v_title, v_count
    FROM qr_marketplace.company_shop_order_lines l
    WHERE l.order_id = p_order_id
    ORDER BY l.created_at
    LIMIT 1;
    v_label := coalesce(nullif(btrim(v_title), ''), '№' || v_number::TEXT);
    IF coalesce(v_count, 0) > 1 THEN
        v_label := v_label || ' и ещё ' || (v_count - 1)::TEXT;
    END IF;
    BEGIN
        PERFORM qr_api.sp_user_notification_create(
            v_buyer,
            'review_invite',
            'Оставьте отзыв о продавце',
            format('Вы получили товар «%s». Можете оставить отзыв о продавце', left(v_label, 200)),
            'company_shop_order',
            p_order_id,
            '/cabinet/purchases?tab=shop&order=' || p_order_id::TEXT || '#review'
        );
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'review invite shop order failed: %', SQLERRM;
    END;
END;
$function$

