CREATE OR REPLACE FUNCTION qr_api.sp_company_review_support_open(p_user_id UUID, p_review_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_company UUID;
    v_rev RECORD;
    v_conv UUID;
    v_msg UUID;
    v_body TEXT;
BEGIN
    v_company := qr_api.sp_company_id_for_user(p_user_id);
    IF v_company IS NULL THEN RAISE EXCEPTION 'COMPANY_NOT_FOUND'; END IF;

    SELECT r.* INTO v_rev
    FROM qr_marketplace.company_reviews r
    WHERE r.id = p_review_id AND r.company_id = v_company AND r.deleted_at IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'REVIEW_NOT_FOUND'; END IF;

    SELECT c.id INTO v_conv
    FROM qr_platform.support_conversations c
    WHERE c.company_review_id = p_review_id
      AND c.user_id = p_user_id
      AND c.status_code <> 'archived'
    ORDER BY c.created_at DESC
    LIMIT 1;

    v_body := format(
        E'Просьба рассмотреть отзыв о компании.\nВид: %s\nОценка: %s\nАвтор: %s\nДата: %s\nТекст:\n%s',
        CASE WHEN v_rev.kind = 'task' THEN 'услуги' ELSE 'товары' END,
        v_rev.rating,
        v_rev.author_name,
        to_char(v_rev.created_at AT TIME ZONE 'Europe/Moscow', 'DD.MM.YYYY HH24:MI'),
        v_rev.body
    );

    IF v_conv IS NULL THEN
        v_conv := uuidv7();
        INSERT INTO qr_platform.support_conversations (
            id, user_id, status_code, category_code, company_review_id
        ) VALUES (
            v_conv, p_user_id, 'unread', 'review', p_review_id
        );
    ELSE
        UPDATE qr_platform.support_conversations
        SET status_code = 'unread', last_message_at = now()
        WHERE id = v_conv;
    END IF;

    v_msg := uuidv7();
    INSERT INTO qr_platform.support_messages (id, conversation_id, sender_user_id, is_admin, body)
    VALUES (v_msg, v_conv, p_user_id, FALSE, left(v_body, 4000));

    UPDATE qr_platform.support_conversations SET last_message_at = now() WHERE id = v_conv;
    RETURN v_conv;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_reviews_mine(p_user_id UUID, p_kind VARCHAR, p_limit INT, p_offset INT) RETURNS TABLE (id UUID, kind VARCHAR, rating SMALLINT, body TEXT, author_name VARCHAR, created_at TIMESTAMPTZ, total_count BIGINT) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_company UUID;
    v_kind VARCHAR;
BEGIN
    v_company := qr_api.sp_company_id_for_user(p_user_id);
    IF v_company IS NULL THEN RAISE EXCEPTION 'COMPANY_NOT_FOUND'; END IF;
    v_kind := lower(btrim(coalesce(p_kind, 'task')));
    IF v_kind NOT IN ('task', 'product') THEN
        RAISE EXCEPTION 'INVALID_KIND';
    END IF;
    RETURN QUERY
    SELECT r.id, r.kind, r.rating, r.body, r.author_name, r.created_at,
           count(*) OVER () AS total_count
    FROM qr_marketplace.company_reviews r
    WHERE r.company_id = v_company
      AND r.deleted_at IS NULL
      AND r.kind = v_kind
    ORDER BY r.created_at DESC
    LIMIT GREATEST(1, LEAST(coalesce(p_limit, 20), 20))
    OFFSET GREATEST(0, coalesce(p_offset, 0));
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_set_payout_bank(p_user_id UUID, p_bank_name VARCHAR, p_bik VARCHAR, p_correspondent_account VARCHAR, p_settlement_account VARCHAR) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_company_id UUID;
    v_status_code VARCHAR;
BEGIN
    SELECT c.id, cvs.code
      INTO v_company_id, v_status_code
    FROM qr_marketplace.company_members cm
    JOIN qr_marketplace.companies c ON c.id = cm.company_id AND c.deleted_at IS NULL
    JOIN qr_ref.company_verification_statuses cvs ON cvs.id = c.verification_status_id
    WHERE cm.user_id = p_user_id
    ORDER BY cm.invited_at
    LIMIT 1;

    IF v_company_id IS NULL THEN
        RAISE EXCEPTION 'COMPANY_NOT_FOUND';
    END IF;

    IF v_status_code NOT IN ('draft', 'rejected', 'pending_review', 'verified') THEN
        RAISE EXCEPTION 'COMPANY_NOT_EDITABLE: status=%', v_status_code;
    END IF;

    IF p_bank_name IS NULL OR p_bik IS NULL
       OR p_correspondent_account IS NULL OR p_settlement_account IS NULL THEN
        RAISE EXCEPTION 'BANK_REQUIRED';
    END IF;

    UPDATE qr_marketplace.company_bank_details SET
        bank_name = p_bank_name,
        bik = p_bik,
        correspondent_account = p_correspondent_account,
        settlement_account = p_settlement_account
    WHERE company_id = v_company_id AND is_primary = TRUE;

    IF NOT FOUND THEN
        INSERT INTO qr_marketplace.company_bank_details (
            company_id, bank_name, bik, correspondent_account, settlement_account
        ) VALUES (
            v_company_id, p_bank_name, p_bik, p_correspondent_account, p_settlement_account
        );
    END IF;

    RETURN v_company_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_set_service_cities(p_user_id UUID, p_city_ids BIGINT[]) RETURNS INT LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_company_id UUID;
    v_count INTEGER := 0;
    v_city_id BIGINT;
BEGIN
    v_company_id := qr_api.sp_company_id_for_user(p_user_id);
    IF v_company_id IS NULL THEN RAISE EXCEPTION 'COMPANY_NOT_FOUND'; END IF;

    DELETE FROM qr_marketplace.company_service_areas
    WHERE company_id = v_company_id AND city_id IS NOT NULL;

    IF p_city_ids IS NOT NULL THEN
        FOREACH v_city_id IN ARRAY p_city_ids LOOP
            IF EXISTS (SELECT 1 FROM qr_ref.cities WHERE id = v_city_id) THEN
                INSERT INTO qr_marketplace.company_service_areas (company_id, city_id, is_active)
                VALUES (v_company_id, v_city_id, TRUE);
                v_count := v_count + 1;
            END IF;
        END LOOP;
    END IF;
    RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_admin_resolve(p_admin_user_id UUID, p_order_id UUID, p_resolution VARCHAR, p_notes TEXT DEFAULT CAST(NULL AS TEXT)) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_ful_admin BIGINT;
    v_ful_completed BIGINT;
    v_ful_returned BIGINT;
    v_fulfilled BIGINT;
    v_refunded BIGINT;
    v_res VARCHAR;
    v_to_ful BIGINT;
    v_notes TEXT;
    v_member RECORD;
BEGIN
    v_res := lower(btrim(coalesce(p_resolution, '')));
    IF v_res NOT IN ('release_to_seller', 'refund_to_buyer') THEN
        RAISE EXCEPTION 'INVALID_RESOLUTION';
    END IF;

    SELECT id INTO v_ful_admin FROM qr_ref.fulfillment_statuses WHERE code = 'under_administration';
    SELECT id INTO v_ful_completed FROM qr_ref.fulfillment_statuses WHERE code = 'completed';
    SELECT id INTO v_ful_returned FROM qr_ref.fulfillment_statuses WHERE code = 'returned';
    SELECT id INTO v_fulfilled FROM qr_ref.order_statuses WHERE code = 'fulfilled';
    SELECT id INTO v_refunded FROM qr_ref.order_statuses WHERE code = 'refunded';

    SELECT o.*, fs.code AS ful_code, os.code AS ord_status_code
    INTO v_order
    FROM qr_marketplace.company_shop_orders o
    JOIN qr_ref.fulfillment_statuses fs ON fs.id = o.fulfillment_status_id
    JOIN qr_ref.order_statuses os ON os.id = o.status_id
    WHERE o.id = p_order_id
    FOR UPDATE OF o;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;
    IF v_order.ful_code <> 'under_administration' THEN
        RAISE EXCEPTION 'ORDER_NOT_UNDER_ADMINISTRATION';
    END IF;
    IF v_order.ord_status_code <> 'paid' THEN
        RAISE EXCEPTION 'ORDER_NOT_RESOLVABLE';
    END IF;

    v_notes := NULLIF(btrim(coalesce(p_notes, '')), '');

    IF v_res = 'release_to_seller' THEN
        v_to_ful := v_ful_completed;
        UPDATE qr_marketplace.company_shop_orders
        SET fulfillment_status_id = v_ful_completed,
            status_id = v_fulfilled,
            admin_resolution = v_res,
            admin_resolved_at = now(),
            admin_resolved_by = p_admin_user_id,
            buyer_confirmed_at = coalesce(buyer_confirmed_at, now()),
            buyer_confirmation_deadline_at = NULL,
            updated_at = now()
        WHERE id = p_order_id;
    ELSE
        v_to_ful := v_ful_returned;
        UPDATE qr_marketplace.company_shop_orders
        SET fulfillment_status_id = v_ful_returned,
            status_id = v_refunded,
            admin_resolution = v_res,
            admin_resolved_at = now(),
            admin_resolved_by = p_admin_user_id,
            buyer_confirmation_deadline_at = NULL,
            updated_at = now()
        WHERE id = p_order_id;
        IF v_order.buyer_user_id IS NOT NULL
           AND round(coalesce(v_order.total_rub, 0))::INTEGER > 0 THEN
            PERFORM qr_api.sp_wallet_credit(
                v_order.buyer_user_id,
                round(v_order.total_rub)::INTEGER,
                'shop_refund',
                'company_shop_order',
                p_order_id,
                'Возврат по заказу витрины на баланс сайта',
                md5('shop_return:' || p_order_id::text)::uuid
            );
        END IF;
    END IF;

    INSERT INTO qr_marketplace.company_shop_fulfillment_history (
        order_id, from_status_id, to_status_id, actor_user_id, notes
    ) VALUES (
        p_order_id,
        v_order.fulfillment_status_id,
        v_to_ful,
        p_admin_user_id,
        coalesce(
            v_notes,
            CASE v_res
                WHEN 'release_to_seller' THEN 'Поддержка: средства продавцу'
                ELSE 'Поддержка: возврат покупателю'
            END
        )
    );

    UPDATE qr_marketplace.company_shop_dispute_chats
    SET status_code = 'closed',
        closed_at = now(),
        closed_by_user_id = p_admin_user_id
    WHERE shop_order_id = p_order_id
      AND status_code = 'open';

    IF v_order.buyer_user_id IS NOT NULL THEN
        BEGIN
            PERFORM qr_api.sp_user_notification_create(
                v_order.buyer_user_id,
                'company_shop_fulfillment',
                CASE v_res
                    WHEN 'release_to_seller' THEN 'Заказ завершён'
                    ELSE 'Возврат по заказу'
                END,
                CASE v_res
                    WHEN 'release_to_seller' THEN 'Поддержка завершила сделку в пользу продавца.'
                    ELSE 'Поддержка вернула сумму заказа на баланс сайта.'
                END,
                'company_shop_order',
                p_order_id,
                '/cabinet/purchases?tab=shop'
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'shop admin resolve buyer notification failed: %', SQLERRM;
        END;
    END IF;

    FOR v_member IN
        SELECT cm.user_id
        FROM qr_marketplace.company_members cm
        WHERE cm.company_id = v_order.company_id
          AND (v_order.buyer_user_id IS NULL OR cm.user_id IS DISTINCT FROM v_order.buyer_user_id)
    LOOP
        BEGIN
            PERFORM qr_api.sp_user_notification_create(
                v_member.user_id,
                'company_shop_fulfillment',
                CASE v_res
                    WHEN 'release_to_seller' THEN 'Сделка завершена'
                    ELSE 'Возврат покупателю'
                END,
                CASE v_res
                    WHEN 'release_to_seller' THEN 'Поддержка завершила заказ в пользу продавца.'
                    ELSE 'Поддержка оформила возврат покупателю.'
                END,
                'company_shop_order',
                p_order_id,
                '/cabinet/executor?tab=orders'
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'shop admin resolve seller notification failed: %', SQLERRM;
        END;
    END LOOP;

    RETURN p_order_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_awaiting_seller_count(p_user_id UUID) RETURNS BIGINT LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_company_id UUID;
    v_count BIGINT;
BEGIN
    v_company_id := qr_api.sp_company_id_for_user(p_user_id);
    IF v_company_id IS NULL THEN
        RETURN 0;
    END IF;
    SELECT count(*)::BIGINT INTO v_count
    FROM qr_marketplace.company_shop_orders o
    JOIN qr_ref.order_statuses os ON os.id = o.status_id
    WHERE o.company_id = v_company_id
      AND os.code = 'awaiting_seller';
    RETURN coalesce(v_count, 0);
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_buyer_confirm(p_buyer_user_id UUID, p_order_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_ful_code VARCHAR;
    v_fulfilled BIGINT;
    v_ful_completed BIGINT;
BEGIN
    SELECT o.*, fs.code AS ful_code
    INTO v_order
    FROM qr_marketplace.company_shop_orders o
    JOIN qr_ref.fulfillment_statuses fs ON fs.id = o.fulfillment_status_id
    WHERE o.id = p_order_id
    FOR UPDATE OF o;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;
    IF v_order.buyer_user_id <> p_buyer_user_id THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;

    IF v_order.fulfillment_mode = 'pickup' THEN
        RAISE EXCEPTION 'USE_PICKUP_CODE';
    END IF;

    v_ful_code := v_order.ful_code;
    IF v_ful_code = 'under_administration' THEN
        RAISE EXCEPTION 'ORDER_UNDER_ADMINISTRATION';
    END IF;
    IF v_ful_code = 'return_requested' THEN
        RAISE EXCEPTION 'ORDER_RETURN_PENDING';
    END IF;
    IF v_ful_code <> 'delivered' THEN
        RAISE EXCEPTION 'ORDER_NOT_DELIVERED';
    END IF;
    IF v_order.buyer_confirmation_deadline_at IS NOT NULL
       AND v_order.buyer_confirmation_deadline_at <= now() THEN
        RAISE EXCEPTION 'BUYER_CONFIRMATION_EXPIRED';
    END IF;
    IF v_order.seller_proof_storage_key IS NULL OR btrim(v_order.seller_proof_storage_key) = '' THEN
        RAISE EXCEPTION 'SELLER_PROOF_REQUIRED';
    END IF;
    IF v_order.buyer_proof_storage_key IS NULL OR btrim(v_order.buyer_proof_storage_key) = '' THEN
        RAISE EXCEPTION 'BUYER_PROOF_REQUIRED';
    END IF;

    SELECT id INTO v_fulfilled FROM qr_ref.order_statuses WHERE code = 'fulfilled';
    SELECT id INTO v_ful_completed FROM qr_ref.fulfillment_statuses WHERE code = 'completed';

    UPDATE qr_marketplace.company_shop_orders
    SET fulfillment_status_id = v_ful_completed,
        status_id = v_fulfilled,
        buyer_confirmed_at = now(),
        buyer_confirmation_deadline_at = NULL,
        updated_at = now()
    WHERE id = p_order_id;

    INSERT INTO qr_marketplace.company_shop_fulfillment_history (
        order_id, from_status_id, to_status_id, actor_user_id, notes
    ) VALUES (
        p_order_id,
        v_order.fulfillment_status_id,
        v_ful_completed,
        p_buyer_user_id,
        'Покупатель подтвердил получение'
    );

    PERFORM qr_api.sp_company_review_invite_shop_order(p_order_id);
    RETURN p_order_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_buyer_request_return(p_buyer_user_id UUID, p_order_id UUID, p_storage_key TEXT, p_reason TEXT DEFAULT CAST(NULL AS TEXT)) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_key TEXT;
    v_ful_return BIGINT;
    v_chat_id UUID;
    v_order_number BIGINT;
    v_member RECORD;
    v_reason TEXT;
BEGIN
    v_key := NULLIF(btrim(coalesce(p_storage_key, '')), '');
    IF v_key IS NULL THEN
        RAISE EXCEPTION 'RETURN_PROOF_REQUIRED';
    END IF;
    v_reason := NULLIF(btrim(coalesce(p_reason, '')), '');
    IF v_reason IS NULL OR char_length(v_reason) < 10 THEN
        RAISE EXCEPTION 'RETURN_REASON_REQUIRED';
    END IF;
    v_reason := left(v_reason, 2000);

    SELECT o.*, fs.code AS ful_code, os.code AS ord_status_code
    INTO v_order
    FROM qr_marketplace.company_shop_orders o
    JOIN qr_ref.fulfillment_statuses fs ON fs.id = o.fulfillment_status_id
    JOIN qr_ref.order_statuses os ON os.id = o.status_id
    WHERE o.id = p_order_id
    FOR UPDATE OF o;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;
    IF v_order.buyer_user_id <> p_buyer_user_id THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;
    IF v_order.fulfillment_mode <> 'delivery' THEN
        RAISE EXCEPTION 'NOT_DELIVERY_ORDER';
    END IF;
    IF v_order.ord_status_code <> 'paid' THEN
        RAISE EXCEPTION 'ORDER_NOT_PAID';
    END IF;
    IF v_order.ful_code = 'under_administration' THEN
        RAISE EXCEPTION 'ORDER_UNDER_ADMINISTRATION';
    END IF;
    IF v_order.ful_code = 'return_requested' OR v_order.return_requested_at IS NOT NULL THEN
        RAISE EXCEPTION 'RETURN_ALREADY_REQUESTED';
    END IF;
    IF v_order.ful_code NOT IN ('shipped', 'in_transit', 'delivered') THEN
        RAISE EXCEPTION 'RETURN_NOT_ALLOWED';
    END IF;

    SELECT id INTO v_ful_return FROM qr_ref.fulfillment_statuses WHERE code = 'return_requested';
    IF v_ful_return IS NULL THEN
        RAISE EXCEPTION 'STATUS_LOOKUP_MISSING';
    END IF;

    UPDATE qr_marketplace.company_shop_orders
    SET fulfillment_status_id = v_ful_return,
        return_proof_storage_key = v_key,
        return_proof_uploaded_at = now(),
        return_requested_at = now(),
        buyer_confirmation_deadline_at = NULL,
        updated_at = now()
    WHERE id = p_order_id;

    INSERT INTO qr_marketplace.company_shop_fulfillment_history (
        order_id, from_status_id, to_status_id, actor_user_id, notes
    ) VALUES (
        p_order_id,
        v_order.fulfillment_status_id,
        v_ful_return,
        p_buyer_user_id,
        v_reason
    );

    SELECT id INTO v_chat_id
    FROM qr_marketplace.company_shop_dispute_chats
    WHERE shop_order_id = p_order_id;
    IF v_chat_id IS NULL THEN
        v_chat_id := uuidv7();
        INSERT INTO qr_marketplace.company_shop_dispute_chats (id, shop_order_id, status_code)
        VALUES (v_chat_id, p_order_id, 'open');
    ELSE
        UPDATE qr_marketplace.company_shop_dispute_chats
        SET status_code = 'open',
            closed_at = NULL,
            closed_by_user_id = NULL
        WHERE id = v_chat_id;
    END IF;

    v_order_number := v_order.order_number;

    FOR v_member IN
        SELECT cm.user_id
        FROM qr_marketplace.company_members cm
        WHERE cm.company_id = v_order.company_id
          AND cm.user_id IS DISTINCT FROM p_buyer_user_id
    LOOP
        BEGIN
            PERFORM qr_api.sp_user_notification_create(
                v_member.user_id,
                'company_shop_return_requested',
                'Запрос возврата',
                format('Покупатель запросил возврат по заказу №%s. Примите решение.', v_order_number),
                'company_shop_order',
                p_order_id,
                '/cabinet/executor?tab=orders'
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'shop return seller notification failed: %', SQLERRM;
        END;
    END LOOP;

    RETURN p_order_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_dispute_chat_get_or_create(p_actor_user_id UUID, p_order_id UUID) RETURNS TABLE (chat_id UUID, shop_order_id UUID, status_code VARCHAR, created_at TIMESTAMPTZ, closed_at TIMESTAMPTZ) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_company_id UUID;
    v_is_admin BOOLEAN;
    v_chat_id UUID;
BEGIN
    SELECT o.*, fs.code AS ful_code
    INTO v_order
    FROM qr_marketplace.company_shop_orders o
    JOIN qr_ref.fulfillment_statuses fs ON fs.id = o.fulfillment_status_id
    WHERE o.id = p_order_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM qr_identity.users u
        JOIN qr_ref.user_roles ur ON ur.id = u.role_id
        WHERE u.id = p_actor_user_id AND u.deleted_at IS NULL AND ur.code = 'admin'
    ) INTO v_is_admin;

    v_company_id := qr_api.sp_company_id_for_user(p_actor_user_id);
    IF NOT coalesce(v_is_admin, FALSE)
       AND v_order.buyer_user_id IS DISTINCT FROM p_actor_user_id
       AND (v_company_id IS NULL OR v_company_id <> v_order.company_id) THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;

    SELECT c.id INTO v_chat_id
    FROM qr_marketplace.company_shop_dispute_chats c
    WHERE c.shop_order_id = p_order_id;

    IF v_chat_id IS NULL THEN
        IF v_order.ful_code NOT IN ('under_administration', 'return_requested') AND NOT coalesce(v_is_admin, FALSE) THEN
            RAISE EXCEPTION 'DISPUTE_CHAT_NOT_AVAILABLE';
        END IF;
        v_chat_id := uuidv7();
        INSERT INTO qr_marketplace.company_shop_dispute_chats (id, shop_order_id, status_code)
        VALUES (v_chat_id, p_order_id, 'open');
    END IF;

    RETURN QUERY
    SELECT c.id, c.shop_order_id, c.status_code, c.created_at, c.closed_at
    FROM qr_marketplace.company_shop_dispute_chats c
    WHERE c.id = v_chat_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_dispute_message_send(p_actor_user_id UUID, p_order_id UUID, p_body TEXT, p_storage_keys TEXT[] DEFAULT CAST(NULL AS TEXT[]), p_mime_types TEXT[] DEFAULT CAST(NULL AS TEXT[]), p_sizes BIGINT[] DEFAULT CAST(NULL AS BIGINT[]), p_filenames TEXT[] DEFAULT CAST(NULL AS TEXT[])) RETURNS TABLE (message_id UUID, chat_id UUID, created_at TIMESTAMPTZ, sender_role VARCHAR) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
#variable_conflict use_column
DECLARE
    v_order RECORD;
    v_company_id UUID;
    v_is_admin BOOLEAN;
    v_role VARCHAR(16);
    v_chat RECORD;
    v_body TEXT := btrim(coalesce(p_body, ''));
    v_keys TEXT[] := coalesce(p_storage_keys, ARRAY[]::TEXT[]);
    v_n INT;
    i INT;
    v_key TEXT;
    v_msg_id UUID;
    v_created TIMESTAMPTZ;
    v_member RECORD;
BEGIN
    IF length(v_body) < 1 THEN
        RAISE EXCEPTION 'EMPTY_MESSAGE';
    END IF;
    IF length(v_body) > 4000 THEN
        v_body := left(v_body, 4000);
    END IF;

    v_n := coalesce(array_length(v_keys, 1), 0);
    IF v_n > 3 THEN
        RAISE EXCEPTION 'TOO_MANY_ATTACHMENTS';
    END IF;

    SELECT o.* INTO v_order
    FROM qr_marketplace.company_shop_orders o
    WHERE o.id = p_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM qr_identity.users u
        JOIN qr_ref.user_roles ur ON ur.id = u.role_id
        WHERE u.id = p_actor_user_id AND u.deleted_at IS NULL AND ur.code = 'admin'
    ) INTO v_is_admin;

    v_company_id := qr_api.sp_company_id_for_user(p_actor_user_id);
    IF coalesce(v_is_admin, FALSE) THEN
        v_role := 'admin';
    ELSIF v_order.buyer_user_id = p_actor_user_id THEN
        v_role := 'buyer';
    ELSIF v_company_id IS NOT NULL AND v_company_id = v_order.company_id THEN
        v_role := 'seller';
    ELSE
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;

    SELECT c.* INTO v_chat
    FROM qr_marketplace.company_shop_dispute_chats c
    WHERE c.shop_order_id = p_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'DISPUTE_CHAT_NOT_FOUND';
    END IF;
    IF v_chat.status_code <> 'open' THEN
        RAISE EXCEPTION 'DISPUTE_CHAT_CLOSED';
    END IF;

    FOR i IN 1..v_n LOOP
        v_key := btrim(v_keys[i]);
        IF v_key IS NULL OR v_key = '' THEN
            RAISE EXCEPTION 'INVALID_STORAGE_KEY';
        END IF;
        IF NOT (
            v_key LIKE ('chat/shop_dispute/' || p_order_id::TEXT || '/%')
            OR v_key LIKE ('chats/shop_dispute/' || p_order_id::TEXT || '/%')
            OR v_key LIKE (
                'company/' || v_order.company_id::TEXT
                || '/shop_order/' || p_order_id::TEXT || '/dispute/%'
            )
            OR v_key LIKE (
                'companies/' || v_order.company_id::TEXT
                || '/shop_orders/' || p_order_id::TEXT || '/dispute/%'
            )
        ) THEN
            RAISE EXCEPTION 'INVALID_STORAGE_KEY';
        END IF;
    END LOOP;

    v_msg_id := uuidv7();
    INSERT INTO qr_marketplace.company_shop_dispute_messages (
        id, chat_id, sender_user_id, sender_role, body
    ) VALUES (
        v_msg_id, v_chat.id, p_actor_user_id, v_role, v_body
    )
    RETURNING created_at INTO v_created;

    FOR i IN 1..v_n LOOP
        INSERT INTO qr_marketplace.company_shop_dispute_message_attachments (
            message_id, storage_key, mime_type, size_bytes, original_filename
        ) VALUES (
            v_msg_id,
            btrim(v_keys[i]),
            coalesce(nullif(btrim(coalesce(p_mime_types[i], '')), ''), 'image/jpeg'),
            coalesce(p_sizes[i], 0),
            nullif(btrim(coalesce(p_filenames[i], '')), '')
        );
    END LOOP;

    -- Уведомить остальных участников
    IF v_order.buyer_user_id IS DISTINCT FROM p_actor_user_id THEN
        BEGIN
            PERFORM qr_api.sp_user_notification_create(
                v_order.buyer_user_id,
                'company_shop_dispute_message',
                'Сообщение по спору',
                left(v_body, 200),
                'company_shop_order',
                p_order_id,
                '/cabinet/purchases?tab=shop'
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'dispute msg buyer notify failed: %', SQLERRM;
        END;
    END IF;

    FOR v_member IN
        SELECT cm.user_id
        FROM qr_marketplace.company_members cm
        WHERE cm.company_id = v_order.company_id
          AND cm.user_id IS DISTINCT FROM p_actor_user_id
          AND cm.user_id IS DISTINCT FROM v_order.buyer_user_id
    LOOP
        BEGIN
            PERFORM qr_api.sp_user_notification_create(
                v_member.user_id,
                'company_shop_dispute_message',
                'Сообщение по спору',
                left(v_body, 200),
                'company_shop_order',
                p_order_id,
                '/cabinet/executor?tab=orders'
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'dispute msg seller notify failed: %', SQLERRM;
        END;
    END LOOP;

    message_id := v_msg_id;
    chat_id := v_chat.id;
    created_at := v_created;
    sender_role := v_role;
    RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_dispute_messages_list(p_actor_user_id UUID, p_order_id UUID, p_after TIMESTAMPTZ DEFAULT CAST(NULL AS TIMESTAMPTZ)) RETURNS TABLE (id UUID, chat_id UUID, sender_user_id UUID, sender_name VARCHAR, sender_role VARCHAR, body TEXT, created_at TIMESTAMPTZ, attachments JSONB) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_company_id UUID;
    v_is_admin BOOLEAN;
    v_chat_id UUID;
BEGIN
    SELECT o.* INTO v_order
    FROM qr_marketplace.company_shop_orders o
    WHERE o.id = p_order_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM qr_identity.users u
        JOIN qr_ref.user_roles ur ON ur.id = u.role_id
        WHERE u.id = p_actor_user_id AND u.deleted_at IS NULL AND ur.code = 'admin'
    ) INTO v_is_admin;

    v_company_id := qr_api.sp_company_id_for_user(p_actor_user_id);
    IF NOT coalesce(v_is_admin, FALSE)
       AND v_order.buyer_user_id IS DISTINCT FROM p_actor_user_id
       AND (v_company_id IS NULL OR v_company_id <> v_order.company_id) THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;

    SELECT c.id INTO v_chat_id
    FROM qr_marketplace.company_shop_dispute_chats c
    WHERE c.shop_order_id = p_order_id;
    IF v_chat_id IS NULL THEN
        RETURN;
    END IF;

    RETURN QUERY
    SELECT
        m.id,
        m.chat_id,
        m.sender_user_id,
        coalesce(u.full_name, u.email::VARCHAR, 'Участник')::VARCHAR AS sender_name,
        m.sender_role,
        m.body,
        m.created_at,
        coalesce((
            SELECT jsonb_agg(jsonb_build_object(
                'id', a.id,
                'storage_key', a.storage_key,
                'mime_type', a.mime_type,
                'size_bytes', a.size_bytes,
                'original_filename', a.original_filename
            ) ORDER BY a.created_at)
            FROM qr_marketplace.company_shop_dispute_message_attachments a
            WHERE a.message_id = m.id
        ), '[]'::jsonb) AS attachments
    FROM qr_marketplace.company_shop_dispute_messages m
    JOIN qr_identity.users u ON u.id = m.sender_user_id
    WHERE m.chat_id = v_chat_id
      AND (p_after IS NULL OR m.created_at > p_after)
    ORDER BY m.created_at;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_fulfillment_update(p_actor_user_id UUID, p_order_id UUID, p_status_code VARCHAR, p_notes TEXT, p_is_admin BOOLEAN DEFAULT FALSE) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_order_status_code VARCHAR;
    v_from_code VARCHAR;
    v_to_id BIGINT;
    v_to_code VARCHAR;
    v_company_id UUID;
    v_allowed BOOLEAN := FALSE;
BEGIN
    SELECT o.*, fs.code AS ful_code, os.code AS ord_status_code
    INTO v_order
    FROM qr_marketplace.company_shop_orders o
    JOIN qr_ref.fulfillment_statuses fs ON fs.id = o.fulfillment_status_id
    JOIN qr_ref.order_statuses os ON os.id = o.status_id
    WHERE o.id = p_order_id
    FOR UPDATE OF o;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;

    IF NOT coalesce(p_is_admin, FALSE) THEN
        v_company_id := qr_api.sp_company_id_for_user(p_actor_user_id);
        IF v_company_id IS NULL OR v_company_id <> v_order.company_id THEN
            RAISE EXCEPTION 'FORBIDDEN';
        END IF;
        IF v_order.ord_status_code NOT IN ('paid', 'fulfilled') THEN
            RAISE EXCEPTION 'ORDER_NOT_PAID';
        END IF;
    END IF;

    v_from_code := v_order.ful_code;
    v_to_code := lower(btrim(coalesce(p_status_code, '')));

    IF NOT coalesce(p_is_admin, FALSE) AND v_from_code = 'return_requested' THEN
        RAISE EXCEPTION 'ORDER_RETURN_PENDING';
    END IF;
    IF NOT coalesce(p_is_admin, FALSE) AND v_from_code = 'under_administration' THEN
        RAISE EXCEPTION 'ORDER_UNDER_ADMINISTRATION';
    END IF;

    SELECT id INTO v_to_id FROM qr_ref.fulfillment_statuses WHERE code = v_to_code;
    IF v_to_id IS NULL THEN
        RAISE EXCEPTION 'INVALID_FULFILLMENT_STATUS';
    END IF;

    IF v_to_code = v_from_code THEN
        RETURN p_order_id;
    END IF;

    IF v_order.fulfillment_mode = 'pickup' THEN
        v_allowed := (v_from_code, v_to_code) IN (
            ('accepted', 'processing'),
            ('accepted', 'ready_for_pickup'),
            ('accepted', 'failed'),
            ('processing', 'ready_for_pickup'),
            ('processing', 'failed'),
            ('ready_for_pickup', 'failed'),
            ('pending', 'processing'),
            ('pending', 'ready_for_pickup'),
            ('pending', 'failed')
        );
    ELSE
        v_allowed := (v_from_code, v_to_code) IN (
            ('accepted', 'shipped'),
            ('accepted', 'failed'),
            ('shipped', 'delivered'),
            ('shipped', 'failed'),
            -- legacy: заказы, уже в in_transit до объединения этапов
            ('in_transit', 'delivered'),
            ('in_transit', 'failed'),
            ('pending', 'processing'),
            ('pending', 'shipped'),
            ('pending', 'failed'),
            ('processing', 'shipped'),
            ('processing', 'failed')
        );
    END IF;

    IF NOT coalesce(p_is_admin, FALSE) AND NOT v_allowed THEN
        RAISE EXCEPTION 'INVALID_STATUS_TRANSITION';
    END IF;

    IF v_to_code IN ('shipped', 'delivered')
       AND NOT coalesce(p_is_admin, FALSE)
       AND (
           v_order.seller_proof_storage_key IS NULL
           OR btrim(v_order.seller_proof_storage_key) = ''
       ) THEN
        RAISE EXCEPTION 'SELLER_PROOF_REQUIRED';
    END IF;

    UPDATE qr_marketplace.company_shop_orders
    SET fulfillment_status_id = v_to_id,
        buyer_confirmation_deadline_at = CASE
            WHEN v_to_code = 'delivered' AND v_order.fulfillment_mode = 'delivery'
            THEN now() + interval '3 days'
            ELSE buyer_confirmation_deadline_at
        END,
        updated_at = now()
    WHERE id = p_order_id;

    INSERT INTO qr_marketplace.company_shop_fulfillment_history (
        order_id, from_status_id, to_status_id, actor_user_id, notes
    ) VALUES (
        p_order_id,
        v_order.fulfillment_status_id,
        v_to_id,
        p_actor_user_id,
        NULLIF(btrim(coalesce(p_notes, '')), '')
    );

    IF v_order.buyer_user_id IS NOT NULL THEN
        BEGIN
            IF v_to_code = 'processing' THEN
                PERFORM qr_api.sp_user_notification_create(
                    v_order.buyer_user_id,
                    'company_shop_fulfillment',
                    CASE WHEN v_order.fulfillment_mode = 'pickup' THEN 'Заказ готовится' ELSE 'Заказ в обработке' END,
                    format(
                        'Компания «%s» обновила статус заказа: %s.',
                        coalesce(
                            (SELECT coalesce(c.short_name, c.legal_name) FROM qr_marketplace.companies c WHERE c.id = v_order.company_id),
                            'продавец'
                        ),
                        CASE
                            WHEN v_order.fulfillment_mode = 'pickup' THEN 'готовится'
                            ELSE 'в обработке'
                        END
                    ),
                    'company_shop_order',
                    p_order_id,
                    '/cabinet/purchases?tab=shop'
                );
            ELSIF v_to_code = 'shipped' THEN
                PERFORM qr_api.sp_user_notification_create(
                    v_order.buyer_user_id,
                    'company_shop_fulfillment',
                    'Заказ в доставке',
                    'Ваш заказ передан в доставку. Отслеживайте статус в личном кабинете.',
                    'company_shop_order',
                    p_order_id,
                    '/cabinet/purchases?tab=shop'
                );
            ELSIF v_to_code = 'in_transit' THEN
                -- legacy: уведомление как у shipped (этап объединён)
                PERFORM qr_api.sp_user_notification_create(
                    v_order.buyer_user_id,
                    'company_shop_fulfillment',
                    'Заказ в доставке',
                    'Ваш заказ передан в доставку. Отслеживайте статус в личном кабинете.',
                    'company_shop_order',
                    p_order_id,
                    '/cabinet/purchases?tab=shop'
                );
            ELSIF v_to_code = 'delivered' THEN
                PERFORM qr_api.sp_user_notification_create(
                    v_order.buyer_user_id,
                    'company_shop_fulfillment',
                    'Заказ доставлен',
                    'Заказ отмечен как доставленный. Загрузите фото получения и подтвердите в личном кабинете.',
                    'company_shop_order',
                    p_order_id,
                    '/cabinet/purchases?tab=shop'
                );
            ELSIF v_to_code = 'ready_for_pickup' THEN
                PERFORM qr_api.sp_user_notification_create(
                    v_order.buyer_user_id,
                    'company_shop_fulfillment',
                    'Заказ готов к выдаче',
                    'Можно забрать заказ самовывозом — назовите код выдачи из личного кабинета.',
                    'company_shop_order',
                    p_order_id,
                    '/cabinet/purchases?tab=shop'
                );
            END IF;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'company_shop_fulfillment notification failed for order %: %', p_order_id, SQLERRM;
        END;
    END IF;

    RETURN p_order_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_order_create(p_buyer_user_id UUID, p_order_id UUID, p_company_id UUID, p_items_json JSONB, p_fulfillment_mode VARCHAR, p_delivery_address TEXT, p_postal_code VARCHAR, p_city VARCHAR, p_contact_phone VARCHAR, p_contact_name VARCHAR, p_buyer_comment TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_awaiting_seller BIGINT;
    v_ful_awaiting BIGINT;
    v_item JSONB;
    v_product RECORD;
    v_qty INTEGER;
    v_unit NUMERIC(12, 2);
    v_seller_unit NUMERIC(12, 2);
    v_line NUMERIC(12, 2);
    v_goods_total NUMERIC(12, 2) := 0;
    v_seller_goods_total NUMERIC(12, 2) := 0;
    v_mode VARCHAR;
    v_addr TEXT;
    v_order_number BIGINT;
    v_member RECORD;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM qr_marketplace.companies c
        WHERE c.id = p_company_id AND c.deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION 'COMPANY_NOT_FOUND';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM qr_identity.users u WHERE u.id = p_buyer_user_id AND u.deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION 'USER_NOT_FOUND';
    END IF;

    v_mode := lower(btrim(coalesce(p_fulfillment_mode, '')));
    IF v_mode NOT IN ('delivery', 'pickup') THEN
        RAISE EXCEPTION 'INVALID_FULFILLMENT_MODE';
    END IF;

    v_addr := NULLIF(btrim(coalesce(p_delivery_address, '')), '');
    IF v_mode = 'delivery' AND v_addr IS NULL THEN
        RAISE EXCEPTION 'DELIVERY_ADDRESS_REQUIRED';
    END IF;
    IF v_mode = 'pickup' THEN
        v_addr := NULL;
    END IF;

    IF jsonb_typeof(p_items_json) <> 'array' OR jsonb_array_length(p_items_json) < 1 THEN
        RAISE EXCEPTION 'EMPTY_CART';
    END IF;
    IF jsonb_array_length(p_items_json) > 50 THEN
        RAISE EXCEPTION 'CART_TOO_LARGE';
    END IF;

    SELECT id INTO v_awaiting_seller FROM qr_ref.order_statuses WHERE code = 'awaiting_seller';
    SELECT id INTO v_ful_awaiting FROM qr_ref.fulfillment_statuses WHERE code = 'awaiting_seller';
    IF v_awaiting_seller IS NULL OR v_ful_awaiting IS NULL THEN
        RAISE EXCEPTION 'STATUS_LOOKUP_MISSING';
    END IF;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items_json)
    LOOP
        v_qty := COALESCE((v_item->>'quantity')::INTEGER, 0);
        IF v_qty < 1 OR v_qty > 999 THEN
            RAISE EXCEPTION 'INVALID_QUANTITY';
        END IF;
        SELECT p.id, p.kind, p.title, p.price_rub, p.is_active, p.deleted_at
        INTO v_product
        FROM qr_marketplace.company_products p
        WHERE p.id = (v_item->>'product_id')::UUID
          AND p.company_id = p_company_id;
        IF NOT FOUND OR v_product.deleted_at IS NOT NULL OR NOT v_product.is_active THEN
            RAISE EXCEPTION 'PRODUCT_NOT_FOUND';
        END IF;
        IF v_product.kind NOT IN ('wreath', 'monument') THEN
            RAISE EXCEPTION 'PRODUCT_NOT_FOUND';
        END IF;
        IF v_product.price_rub IS NULL OR v_product.price_rub <= 0 THEN
            RAISE EXCEPTION 'PRODUCT_PRICE_MISSING';
        END IF;
        v_seller_unit := v_product.price_rub;
        v_unit := round(v_seller_unit * 1.10, 0);
        v_goods_total := v_goods_total + (v_unit * v_qty);
        v_seller_goods_total := v_seller_goods_total + (v_seller_unit * v_qty);
    END LOOP;

    INSERT INTO qr_marketplace.company_shop_orders (
        id, buyer_user_id, company_id, status_id, fulfillment_mode, fulfillment_status_id,
        delivery_address, postal_code, city, contact_phone, contact_name,
        goods_total_rub, seller_goods_total_rub, total_rub, buyer_comment
    ) VALUES (
        p_order_id, p_buyer_user_id, p_company_id, v_awaiting_seller, v_mode, v_ful_awaiting,
        v_addr,
        NULLIF(btrim(coalesce(p_postal_code, '')), ''),
        NULLIF(btrim(coalesce(p_city, '')), ''),
        NULLIF(btrim(coalesce(p_contact_phone, '')), ''),
        NULLIF(btrim(coalesce(p_contact_name, '')), ''),
        v_goods_total,
        v_seller_goods_total,
        v_goods_total,
        NULLIF(btrim(coalesce(p_buyer_comment, '')), '')
    );

    SELECT order_number INTO v_order_number
    FROM qr_marketplace.company_shop_orders WHERE id = p_order_id;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items_json)
    LOOP
        v_qty := (v_item->>'quantity')::INTEGER;
        SELECT p.id, p.kind, p.title, p.price_rub
        INTO v_product
        FROM qr_marketplace.company_products p
        WHERE p.id = (v_item->>'product_id')::UUID
          AND p.company_id = p_company_id
          AND p.deleted_at IS NULL
          AND p.is_active;
        v_unit := v_product.price_rub;
        v_seller_unit := v_product.price_rub;
        v_unit := round(v_seller_unit * 1.10, 0);
        v_line := v_unit * v_qty;
        INSERT INTO qr_marketplace.company_shop_order_lines (
            order_id, product_id, kind, title, unit_price_rub, seller_unit_price_rub, quantity, line_total_rub
        ) VALUES (
            p_order_id, v_product.id, v_product.kind, v_product.title, v_unit, v_seller_unit, v_qty, v_line
        );
    END LOOP;

    FOR v_member IN
        SELECT cm.user_id
        FROM qr_marketplace.company_members cm
        WHERE cm.company_id = p_company_id
    LOOP
        BEGIN
            PERFORM qr_api.sp_user_notification_create(
                v_member.user_id,
                'company_shop_order_request',
                'Новая заявка на заказ',
                format('Получена заявка на заказ №%s — подтвердите или отклоните.', v_order_number),
                'company_shop_order',
                p_order_id,
                '/cabinet/executor?tab=orders'
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'company_shop_order_request notification failed: %', SQLERRM;
        END;
    END LOOP;

    RETURN p_order_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_pay_from_wallet(p_buyer_user_id UUID, p_order_id UUID) RETURNS DECIMAL LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_payment_id UUID;
    v_provider_id VARCHAR;
    v_amount NUMERIC;
    v_rub INTEGER;
BEGIN
    v_payment_id := uuidv7();
    v_provider_id := 'wallet-' || replace(v_payment_id::text, '-', '');
    v_amount := qr_api.sp_company_shop_payment_create(
        p_buyer_user_id,
        p_order_id,
        v_payment_id,
        v_payment_id,
        v_provider_id,
        NULL
    );
    v_rub := round(v_amount)::INTEGER;
    IF v_amount <> v_rub THEN
        RAISE EXCEPTION 'AMOUNT_NOT_WHOLE_RUB';
    END IF;
    UPDATE qr_marketplace.company_shop_order_payments
    SET provider = 'wallet'
    WHERE id = v_payment_id;
    PERFORM qr_api.sp_wallet_debit(
        p_buyer_user_id,
        v_rub,
        'shop_payment',
        'company_shop_order',
        p_order_id,
        'Оплата заказа витрины с баланса',
        v_payment_id
    );
    PERFORM qr_api.sp_company_shop_payment_apply(v_provider_id);
    RETURN v_amount;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_payment_apply(p_provider_payment_id VARCHAR) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_pay RECORD;
    v_succeeded BIGINT;
    v_waiting BIGINT;
    v_paid BIGINT;
    v_ful_accepted BIGINT;
    v_buyer_id UUID;
    v_company_id UUID;
    v_company_name TEXT;
    v_total NUMERIC;
    v_order_number BIGINT;
    v_member RECORD;
    v_mode VARCHAR(20);
    v_pickup_code VARCHAR(4);
    v_try INT;
    v_cancelled BIGINT;
    v_refunded BIGINT;
    v_fulfilled BIGINT;
BEGIN
    SELECT id INTO v_succeeded FROM qr_ref.payment_statuses WHERE code = 'succeeded';
    SELECT id INTO v_waiting FROM qr_ref.payment_statuses WHERE code = 'waiting';
    SELECT id INTO v_paid FROM qr_ref.order_statuses WHERE code = 'paid';
    SELECT id INTO v_ful_accepted FROM qr_ref.fulfillment_statuses WHERE code = 'accepted';
    SELECT id INTO v_cancelled FROM qr_ref.order_statuses WHERE code = 'cancelled';
    SELECT id INTO v_refunded FROM qr_ref.order_statuses WHERE code = 'refunded';
    SELECT id INTO v_fulfilled FROM qr_ref.order_statuses WHERE code = 'fulfilled';
    IF v_succeeded IS NULL OR v_waiting IS NULL OR v_paid IS NULL OR v_ful_accepted IS NULL THEN
        RAISE EXCEPTION 'STATUS_LOOKUP_MISSING';
    END IF;

    SELECT * INTO v_pay
    FROM qr_marketplace.company_shop_order_payments
    WHERE provider_payment_id = p_provider_payment_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    IF v_pay.status_id = v_succeeded THEN
        RETURN v_pay.order_id;
    END IF;
    IF v_pay.status_id <> v_waiting THEN
        RAISE EXCEPTION 'INVALID_PAYMENT_STATUS';
    END IF;

    UPDATE qr_marketplace.company_shop_order_payments
    SET status_id = v_succeeded,
        paid_at = now(),
        updated_at = now()
    WHERE id = v_pay.id;

    SELECT o.fulfillment_mode, o.company_id
    INTO v_mode, v_company_id
    FROM qr_marketplace.company_shop_orders o
    WHERE o.id = v_pay.order_id
    FOR UPDATE;

    v_pickup_code := NULL;
    IF v_mode = 'pickup' THEN
        FOR v_try IN 1..40 LOOP
            v_pickup_code := lpad((floor(random() * 10000))::INT::TEXT, 4, '0');
            EXIT WHEN NOT EXISTS (
                SELECT 1
                FROM qr_marketplace.company_shop_orders o2
                WHERE o2.company_id = v_company_id
                  AND o2.fulfillment_mode = 'pickup'
                  AND o2.pickup_code = v_pickup_code
                  AND o2.id <> v_pay.order_id
                  AND o2.status_id IS DISTINCT FROM v_cancelled
                  AND o2.status_id IS DISTINCT FROM v_refunded
                  AND o2.status_id IS DISTINCT FROM v_fulfilled
            );
            v_pickup_code := NULL;
        END LOOP;
        IF v_pickup_code IS NULL THEN
            RAISE EXCEPTION 'PICKUP_CODE_UNAVAILABLE';
        END IF;
    END IF;

    UPDATE qr_marketplace.company_shop_orders
    SET status_id = v_paid,
        fulfillment_status_id = v_ful_accepted,
        paid_at = now(),
        pickup_code = CASE WHEN v_mode = 'pickup' THEN v_pickup_code ELSE pickup_code END,
        updated_at = now()
    WHERE id = v_pay.order_id;

    INSERT INTO qr_marketplace.company_shop_fulfillment_history (
        order_id, from_status_id, to_status_id, actor_user_id, notes
    )
    SELECT o.id, NULL, v_ful_accepted, o.buyer_user_id, 'Оплата получена'
    FROM qr_marketplace.company_shop_orders o
    WHERE o.id = v_pay.order_id;

    PERFORM qr_api.sp_referral_accrue_shop_order(v_pay.order_id);

    SELECT o.buyer_user_id, o.company_id,
           coalesce(c.short_name, c.legal_name)::TEXT,
           o.total_rub, o.order_number
    INTO v_buyer_id, v_company_id, v_company_name, v_total, v_order_number
    FROM qr_marketplace.company_shop_orders o
    JOIN qr_marketplace.companies c ON c.id = o.company_id
    WHERE o.id = v_pay.order_id;

    IF v_buyer_id IS NOT NULL THEN
        BEGIN
            PERFORM qr_api.sp_user_notification_create(
                v_buyer_id,
                'company_shop_paid',
                'Заказ оплачен',
                format(
                    'Оплата заказа №%s у «%s» на %s ₽ прошла успешно.',
                    v_order_number,
                    coalesce(v_company_name, 'компанию'),
                    trim(to_char(v_total, 'FM999999990.00'))
                ),
                'company_shop_order',
                v_pay.order_id,
                '/cabinet/purchases?tab=shop'
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'company_shop_paid notification failed for order %: %',
                v_pay.order_id, SQLERRM;
        END;
    END IF;

    IF v_company_id IS NOT NULL THEN
        FOR v_member IN
            SELECT cm.user_id
            FROM qr_marketplace.company_members cm
            WHERE cm.company_id = v_company_id
              AND (v_buyer_id IS NULL OR cm.user_id IS DISTINCT FROM v_buyer_id)
        LOOP
            BEGIN
                PERFORM qr_api.sp_user_notification_create(
                    v_member.user_id,
                    'company_shop_order_received',
                    'Новый оплаченный заказ',
                    format(
                        'Покупатель оплатил заказ №%s на %s ₽ — откройте раздел «Заказы».',
                        v_order_number,
                        trim(to_char(v_total, 'FM999999990.00'))
                    ),
                    'company_shop_order',
                    v_pay.order_id,
                    '/cabinet/executor?tab=orders'
                );
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'company_shop_order_received notification failed: %', SQLERRM;
            END;
        END LOOP;
    END IF;

    RETURN v_pay.order_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_payment_create(p_buyer_user_id UUID, p_order_id UUID, p_payment_id UUID, p_idempotence_key UUID, p_provider_payment_id VARCHAR, p_confirmation_url TEXT) RETURNS DECIMAL LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_pending_pay BIGINT;
    v_waiting BIGINT;
    v_amount NUMERIC(12,2);
BEGIN
    SELECT id INTO v_pending_pay FROM qr_ref.order_statuses WHERE code = 'pending_payment';
    SELECT id INTO v_waiting FROM qr_ref.payment_statuses WHERE code = 'waiting';

    SELECT o.* INTO v_order
    FROM qr_marketplace.company_shop_orders o
    WHERE o.id = p_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;
    IF v_order.buyer_user_id <> p_buyer_user_id THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;
    IF v_order.status_id <> v_pending_pay THEN
        RAISE EXCEPTION 'ORDER_NOT_PENDING_PAYMENT';
    END IF;

    IF EXISTS (
        SELECT 1 FROM qr_marketplace.company_shop_order_payments p
        WHERE p.order_id = p_order_id AND p.status_id = v_waiting
    ) THEN
        RAISE EXCEPTION 'DUPLICATE_PAYMENT';
    END IF;

    v_amount := v_order.total_rub;

    INSERT INTO qr_marketplace.company_shop_order_payments (
        id, order_id, status_id, amount_rub, provider,
        provider_payment_id, idempotence_key, confirmation_url
    ) VALUES (
        p_payment_id, p_order_id, v_waiting, v_amount, 'yookassa',
        p_provider_payment_id, p_idempotence_key, p_confirmation_url
    );

    RETURN v_amount;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_pickup_confirm(p_seller_user_id UUID, p_order_id UUID, p_code VARCHAR) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_company_id UUID;
    v_code VARCHAR(4);
    v_fulfilled BIGINT;
    v_ful_completed BIGINT;
BEGIN
    v_company_id := qr_api.sp_company_id_for_user(p_seller_user_id);
    IF v_company_id IS NULL THEN
        RAISE EXCEPTION 'COMPANY_NOT_FOUND';
    END IF;

    SELECT o.*, fs.code AS ful_code
    INTO v_order
    FROM qr_marketplace.company_shop_orders o
    JOIN qr_ref.fulfillment_statuses fs ON fs.id = o.fulfillment_status_id
    WHERE o.id = p_order_id
    FOR UPDATE OF o;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;
    IF v_order.company_id <> v_company_id THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;
    IF v_order.fulfillment_mode <> 'pickup' THEN
        RAISE EXCEPTION 'NOT_PICKUP_ORDER';
    END IF;
    IF v_order.ful_code <> 'ready_for_pickup' THEN
        RAISE EXCEPTION 'ORDER_NOT_READY_FOR_PICKUP';
    END IF;

    v_code := regexp_replace(coalesce(p_code, ''), '\D', '', 'g');
    IF length(v_code) <> 4
       OR v_order.pickup_code IS NULL
       OR v_code <> v_order.pickup_code THEN
        RAISE EXCEPTION 'PICKUP_CODE_MISMATCH';
    END IF;

    SELECT id INTO v_fulfilled FROM qr_ref.order_statuses WHERE code = 'fulfilled';
    SELECT id INTO v_ful_completed FROM qr_ref.fulfillment_statuses WHERE code = 'completed';

    UPDATE qr_marketplace.company_shop_orders
    SET fulfillment_status_id = v_ful_completed,
        status_id = v_fulfilled,
        pickup_confirmed_at = now(),
        buyer_confirmed_at = coalesce(buyer_confirmed_at, now()),
        updated_at = now()
    WHERE id = p_order_id;

    INSERT INTO qr_marketplace.company_shop_fulfillment_history (
        order_id, from_status_id, to_status_id, actor_user_id, notes
    ) VALUES (
        p_order_id,
        v_order.fulfillment_status_id,
        v_ful_completed,
        p_seller_user_id,
        'Самовывоз подтверждён по коду'
    );

    IF v_order.buyer_user_id IS NOT NULL THEN
        BEGIN
            PERFORM qr_api.sp_user_notification_create(
                v_order.buyer_user_id,
                'company_shop_fulfillment',
                'Заказ выдан',
                'Самовывоз подтверждён. Заказ выполнен.',
                'company_shop_order',
                p_order_id,
                '/cabinet/purchases?tab=shop'
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'pickup confirm notification failed: %', SQLERRM;
        END;
        PERFORM qr_api.sp_company_review_invite_shop_order(p_order_id);
    END IF;

    RETURN p_order_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_process_buyer_confirmation_deadlines() RETURNS TABLE (order_id UUID, conversation_id UUID) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
#variable_conflict use_column
DECLARE
    r RECORD;
    v_ful_admin BIGINT;
    v_ful_delivered BIGINT;
    v_conv UUID;
    v_member RECORD;
    v_order_number BIGINT;
    v_company_id UUID;
    v_buyer_id UUID;
BEGIN
    SELECT id INTO v_ful_admin FROM qr_ref.fulfillment_statuses WHERE code = 'under_administration';
    SELECT id INTO v_ful_delivered FROM qr_ref.fulfillment_statuses WHERE code = 'delivered';
    IF v_ful_admin IS NULL OR v_ful_delivered IS NULL THEN
        RETURN;
    END IF;

    FOR r IN
        SELECT o.id, o.fulfillment_status_id, o.buyer_user_id, o.company_id, o.order_number
        FROM qr_marketplace.company_shop_orders o
        JOIN qr_ref.fulfillment_statuses fs ON fs.id = o.fulfillment_status_id
        JOIN qr_ref.order_statuses os ON os.id = o.status_id
        WHERE o.fulfillment_mode = 'delivery'
          AND fs.code = 'delivered'
          AND os.code = 'paid'
          AND o.buyer_confirmed_at IS NULL
          AND o.buyer_confirmation_deadline_at IS NOT NULL
          AND o.buyer_confirmation_deadline_at <= now()
        FOR UPDATE OF o SKIP LOCKED
    LOOP
        UPDATE qr_marketplace.company_shop_orders
        SET fulfillment_status_id = v_ful_admin,
            updated_at = now()
        WHERE id = r.id;

        INSERT INTO qr_marketplace.company_shop_fulfillment_history (
            order_id, from_status_id, to_status_id, actor_user_id, notes
        ) VALUES (
            r.id,
            r.fulfillment_status_id,
            v_ful_admin,
            NULL,
            'buyer_confirmation_deadline_expired'
        );

        v_conv := qr_api.sp_support_escalate_shop_order(
            r.id,
            'shop_dispute',
            'Покупатель не подтвердил получение в течение 3 дней после доставки. Средства в холде — требуется решение.'
        );

        v_buyer_id := r.buyer_user_id;
        v_company_id := r.company_id;
        v_order_number := r.order_number;

        IF v_buyer_id IS NOT NULL THEN
            BEGIN
                PERFORM qr_api.sp_user_notification_create(
                    v_buyer_id,
                    'company_shop_fulfillment',
                    'Заказ на рассмотрении',
                    format(
                        'Истёк срок подтверждения по заказу №%s. Дело передано в поддержку.',
                        v_order_number
                    ),
                    'company_shop_order',
                    r.id,
                    '/cabinet/purchases?tab=shop'
                );
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'shop deadline buyer notification failed: %', SQLERRM;
            END;
        END IF;

        IF v_company_id IS NOT NULL THEN
            FOR v_member IN
                SELECT cm.user_id
                FROM qr_marketplace.company_members cm
                WHERE cm.company_id = v_company_id
                  AND (v_buyer_id IS NULL OR cm.user_id IS DISTINCT FROM v_buyer_id)
            LOOP
                BEGIN
                    PERFORM qr_api.sp_user_notification_create(
                        v_member.user_id,
                        'company_shop_fulfillment',
                        'Заказ на рассмотрении',
                        format(
                            'По заказу №%s истёк срок подтверждения покупателем. Дело в поддержке.',
                            v_order_number
                        ),
                        'company_shop_order',
                        r.id,
                        '/cabinet/executor?tab=orders'
                    );
                EXCEPTION WHEN OTHERS THEN
                    RAISE WARNING 'shop deadline seller notification failed: %', SQLERRM;
                END;
            END LOOP;
        END IF;

        order_id := r.id;
        conversation_id := v_conv;
        RETURN NEXT;
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_seller_accept(p_actor_user_id UUID, p_order_id UUID, p_delivery_price_rub DECIMAL, p_delivery_method_note TEXT, p_delivery_service_code VARCHAR DEFAULT CAST(NULL AS VARCHAR), p_delivery_destination_code VARCHAR DEFAULT CAST(NULL AS VARCHAR), p_seller_comment TEXT DEFAULT CAST(NULL AS TEXT)) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_company_id UUID;
    v_awaiting BIGINT;
    v_pending_pay BIGINT;
    v_del_price NUMERIC(12,2);
    v_del_note TEXT;
    v_svc VARCHAR(32);
    v_dest VARCHAR(32);
    v_svc_label TEXT;
    v_dest_label TEXT;
    v_order_number BIGINT;
    v_total NUMERIC(12,2);
BEGIN
    SELECT id INTO v_awaiting FROM qr_ref.order_statuses WHERE code = 'awaiting_seller';
    SELECT id INTO v_pending_pay FROM qr_ref.order_statuses WHERE code = 'pending_payment';

    SELECT o.* INTO v_order
    FROM qr_marketplace.company_shop_orders o
    WHERE o.id = p_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;
    IF v_order.status_id <> v_awaiting THEN
        RAISE EXCEPTION 'ORDER_NOT_AWAITING_SELLER';
    END IF;

    v_company_id := qr_api.sp_company_id_for_user(p_actor_user_id);
    IF v_company_id IS NULL OR v_company_id <> v_order.company_id THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;

    IF v_order.fulfillment_mode = 'pickup' THEN
        v_del_price := 0;
        v_del_note := coalesce(NULLIF(btrim(coalesce(p_delivery_method_note, '')), ''), 'Самовывоз');
        v_svc := NULL;
        v_dest := NULL;
        v_svc_label := 'Самовывоз';
        v_dest_label := 'у продавца';
    ELSE
        IF p_delivery_price_rub IS NULL OR p_delivery_price_rub < 0 THEN
            RAISE EXCEPTION 'DELIVERY_PRICE_REQUIRED';
        END IF;
        v_del_price := p_delivery_price_rub;
        v_svc := NULLIF(lower(btrim(coalesce(p_delivery_service_code, ''))), '');
        v_dest := NULLIF(lower(btrim(coalesce(p_delivery_destination_code, ''))), '');
        IF v_svc IS NULL OR v_svc NOT IN ('cdek', 'russian_post', 'boxberry', 'other') THEN
            RAISE EXCEPTION 'DELIVERY_SERVICE_REQUIRED';
        END IF;
        IF v_dest IS NULL OR v_dest NOT IN ('pickup_point', 'to_door', 'agreed_place') THEN
            RAISE EXCEPTION 'DELIVERY_DESTINATION_REQUIRED';
        END IF;
        v_svc_label := CASE v_svc
            WHEN 'cdek' THEN 'СДЭК'
            WHEN 'russian_post' THEN 'Почта России'
            WHEN 'boxberry' THEN 'Boxberry'
            ELSE 'Другое'
        END;
        v_dest_label := CASE v_dest
            WHEN 'pickup_point' THEN 'До пункта выдачи'
            WHEN 'to_door' THEN 'До двери'
            ELSE 'В согласованное место'
        END;
        v_del_note := coalesce(
            NULLIF(btrim(coalesce(p_delivery_method_note, '')), ''),
            v_svc_label || ' · ' || v_dest_label
        );
    END IF;

    v_total := v_order.goods_total_rub + v_del_price;

    UPDATE qr_marketplace.company_shop_orders
    SET status_id = v_pending_pay,
        delivery_price_rub = v_del_price,
        delivery_method_note = v_del_note,
        delivery_service_code = v_svc,
        delivery_destination_code = v_dest,
        total_rub = v_total,
        seller_user_id = p_actor_user_id,
        seller_responded_at = now(),
        seller_comment = NULLIF(btrim(coalesce(p_seller_comment, '')), ''),
        updated_at = now()
    WHERE id = p_order_id;

    SELECT order_number INTO v_order_number FROM qr_marketplace.company_shop_orders WHERE id = p_order_id;

    BEGIN
        PERFORM qr_api.sp_user_notification_create(
            v_order.buyer_user_id,
            'company_shop_seller_accepted',
            'Заказ подтверждён продавцом',
            format(
                'Заказ №%s подтверждён. Служба: %s. Куда: %s. Итого: %s ₽. Оплатите заказ.%s',
                v_order_number,
                coalesce(v_svc_label, 'самовывоз'),
                coalesce(v_dest_label, 'у продавца'),
                trim(to_char(v_total, 'FM999999990')),
                CASE
                    WHEN NULLIF(btrim(coalesce(p_seller_comment, '')), '') IS NULL THEN ''
                    ELSE format(' Комментарий продавца: %s', btrim(p_seller_comment))
                END
            ),
            'company_shop_order',
            p_order_id,
            '/cabinet/purchases?tab=shop'
        );
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'company_shop_seller_accepted notification failed: %', SQLERRM;
    END;

    RETURN p_order_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_seller_accept_return(p_actor_user_id UUID, p_order_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_company_id UUID;
    v_ful_returned BIGINT;
    v_refunded BIGINT;
    v_order_number BIGINT;
BEGIN
    v_company_id := qr_api.sp_company_id_for_user(p_actor_user_id);
    IF v_company_id IS NULL THEN
        RAISE EXCEPTION 'COMPANY_NOT_FOUND';
    END IF;

    SELECT o.*, fs.code AS ful_code, os.code AS ord_status_code
    INTO v_order
    FROM qr_marketplace.company_shop_orders o
    JOIN qr_ref.fulfillment_statuses fs ON fs.id = o.fulfillment_status_id
    JOIN qr_ref.order_statuses os ON os.id = o.status_id
    WHERE o.id = p_order_id
    FOR UPDATE OF o;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;
    IF v_order.company_id <> v_company_id THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;
    IF v_order.ful_code <> 'return_requested' THEN
        RAISE EXCEPTION 'RETURN_NOT_PENDING';
    END IF;
    IF v_order.ord_status_code <> 'paid' THEN
        RAISE EXCEPTION 'ORDER_NOT_RESOLVABLE';
    END IF;

    SELECT id INTO v_ful_returned FROM qr_ref.fulfillment_statuses WHERE code = 'returned';
    SELECT id INTO v_refunded FROM qr_ref.order_statuses WHERE code = 'refunded';
    IF v_ful_returned IS NULL OR v_refunded IS NULL THEN
        RAISE EXCEPTION 'STATUS_LOOKUP_MISSING';
    END IF;

    UPDATE qr_marketplace.company_shop_orders
    SET fulfillment_status_id = v_ful_returned,
        status_id = v_refunded,
        updated_at = now()
    WHERE id = p_order_id;

    INSERT INTO qr_marketplace.company_shop_fulfillment_history (
        order_id, from_status_id, to_status_id, actor_user_id, notes
    ) VALUES (
        p_order_id,
        v_order.fulfillment_status_id,
        v_ful_returned,
        p_actor_user_id,
        'seller_accepted_return'
    );

    UPDATE qr_marketplace.company_shop_dispute_chats
    SET status_code = 'closed',
        closed_at = now(),
        closed_by_user_id = p_actor_user_id
    WHERE shop_order_id = p_order_id
      AND status_code = 'open';

    SELECT order_number INTO v_order_number FROM qr_marketplace.company_shop_orders WHERE id = p_order_id;

    IF round(coalesce(v_order.total_rub, 0))::INTEGER > 0 THEN
        PERFORM qr_api.sp_wallet_credit(
            v_order.buyer_user_id,
            round(v_order.total_rub)::INTEGER,
            'shop_refund',
            'company_shop_order',
            p_order_id,
            format('Возврат по заказу №%s на баланс сайта', v_order_number),
            md5('shop_return:' || p_order_id::text)::uuid
        );
    END IF;

    BEGIN
        PERFORM qr_api.sp_user_notification_create(
            v_order.buyer_user_id,
            'company_shop_return_accepted',
            'Возврат принят',
            format('Продавец принял возврат по заказу №%s. Сумма вернулась на баланс сайта.', v_order_number),
            'company_shop_order',
            p_order_id,
            '/cabinet/purchases?tab=shop'
        );
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'seller accept return buyer notification failed: %', SQLERRM;
    END;

    RETURN p_order_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_seller_reject(p_actor_user_id UUID, p_order_id UUID, p_reason TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_company_id UUID;
    v_awaiting BIGINT;
    v_cancelled BIGINT;
    v_ful_failed BIGINT;
    v_order_number BIGINT;
BEGIN
    SELECT id INTO v_awaiting FROM qr_ref.order_statuses WHERE code = 'awaiting_seller';
    SELECT id INTO v_cancelled FROM qr_ref.order_statuses WHERE code = 'cancelled';
    SELECT id INTO v_ful_failed FROM qr_ref.fulfillment_statuses WHERE code = 'failed';

    SELECT o.* INTO v_order
    FROM qr_marketplace.company_shop_orders o
    WHERE o.id = p_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;
    IF v_order.status_id <> v_awaiting THEN
        RAISE EXCEPTION 'ORDER_NOT_AWAITING_SELLER';
    END IF;

    v_company_id := qr_api.sp_company_id_for_user(p_actor_user_id);
    IF v_company_id IS NULL OR v_company_id <> v_order.company_id THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;

    UPDATE qr_marketplace.company_shop_orders
    SET status_id = v_cancelled,
        fulfillment_status_id = v_ful_failed,
        seller_user_id = p_actor_user_id,
        seller_responded_at = now(),
        seller_reject_reason = NULLIF(btrim(coalesce(p_reason, '')), ''),
        updated_at = now()
    WHERE id = p_order_id;

    SELECT order_number INTO v_order_number FROM qr_marketplace.company_shop_orders WHERE id = p_order_id;

    BEGIN
        PERFORM qr_api.sp_user_notification_create(
            v_order.buyer_user_id,
            'company_shop_seller_rejected',
            'Заказ отклонён продавцом',
            format(
                'Заказ №%s отклонён продавцом.%s',
                v_order_number,
                CASE WHEN btrim(coalesce(p_reason, '')) <> ''
                     THEN ' Причина: ' || left(btrim(p_reason), 200)
                     ELSE '' END
            ),
            'company_shop_order',
            p_order_id,
            '/cabinet/purchases?tab=shop'
        );
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'company_shop_seller_rejected notification failed: %', SQLERRM;
    END;

    RETURN p_order_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_seller_reject_return(p_actor_user_id UUID, p_order_id UUID, p_reason TEXT DEFAULT CAST(NULL AS TEXT)) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_company_id UUID;
    v_prev_status_id BIGINT;
    v_notes TEXT;
    v_order_number BIGINT;
BEGIN
    v_company_id := qr_api.sp_company_id_for_user(p_actor_user_id);
    IF v_company_id IS NULL THEN
        RAISE EXCEPTION 'COMPANY_NOT_FOUND';
    END IF;

    SELECT o.*, fs.code AS ful_code, os.code AS ord_status_code
    INTO v_order
    FROM qr_marketplace.company_shop_orders o
    JOIN qr_ref.fulfillment_statuses fs ON fs.id = o.fulfillment_status_id
    JOIN qr_ref.order_statuses os ON os.id = o.status_id
    WHERE o.id = p_order_id
    FOR UPDATE OF o;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;
    IF v_order.company_id <> v_company_id THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;
    IF v_order.ful_code <> 'return_requested' THEN
        RAISE EXCEPTION 'RETURN_NOT_PENDING';
    END IF;
    IF v_order.ord_status_code <> 'paid' THEN
        RAISE EXCEPTION 'ORDER_NOT_RESOLVABLE';
    END IF;

    SELECT h.from_status_id INTO v_prev_status_id
    FROM qr_marketplace.company_shop_fulfillment_history h
    WHERE h.order_id = p_order_id
    ORDER BY h.created_at DESC
    LIMIT 1;
    IF v_prev_status_id IS NULL THEN
        SELECT id INTO v_prev_status_id FROM qr_ref.fulfillment_statuses WHERE code = 'delivered';
    END IF;
    IF v_prev_status_id IS NULL THEN
        RAISE EXCEPTION 'STATUS_LOOKUP_MISSING';
    END IF;

    v_notes := NULLIF(btrim(coalesce(p_reason, '')), '');

    UPDATE qr_marketplace.company_shop_orders
    SET fulfillment_status_id = v_prev_status_id,
        updated_at = now()
    WHERE id = p_order_id;

    INSERT INTO qr_marketplace.company_shop_fulfillment_history (
        order_id, from_status_id, to_status_id, actor_user_id, notes
    ) VALUES (
        p_order_id,
        v_order.fulfillment_status_id,
        v_prev_status_id,
        p_actor_user_id,
        coalesce(v_notes, 'seller_rejected_return')
    );

    UPDATE qr_marketplace.company_shop_dispute_chats
    SET status_code = 'closed',
        closed_at = now(),
        closed_by_user_id = p_actor_user_id
    WHERE shop_order_id = p_order_id
      AND status_code = 'open';

    SELECT order_number INTO v_order_number FROM qr_marketplace.company_shop_orders WHERE id = p_order_id;

    BEGIN
        PERFORM qr_api.sp_user_notification_create(
            v_order.buyer_user_id,
            'company_shop_return_rejected',
            'Возврат отклонён',
            format('Продавец отклонил возврат по заказу №%s.', v_order_number),
            'company_shop_order',
            p_order_id,
            '/cabinet/purchases?tab=shop'
        );
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'seller reject return buyer notification failed: %', SQLERRM;
    END;

    RETURN p_order_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_set_buyer_proof(p_buyer_user_id UUID, p_order_id UUID, p_storage_key TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_key TEXT;
BEGIN
    v_key := NULLIF(btrim(coalesce(p_storage_key, '')), '');
    IF v_key IS NULL THEN
        RAISE EXCEPTION 'BUYER_PROOF_REQUIRED';
    END IF;

    SELECT o.*, fs.code AS ful_code
    INTO v_order
    FROM qr_marketplace.company_shop_orders o
    JOIN qr_ref.fulfillment_statuses fs ON fs.id = o.fulfillment_status_id
    WHERE o.id = p_order_id
    FOR UPDATE OF o;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;
    IF v_order.buyer_user_id <> p_buyer_user_id THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;
    IF v_order.fulfillment_mode <> 'delivery' THEN
        RAISE EXCEPTION 'NOT_DELIVERY_ORDER';
    END IF;
    IF v_order.ful_code = 'under_administration' THEN
        RAISE EXCEPTION 'ORDER_UNDER_ADMINISTRATION';
    END IF;
    IF v_order.ful_code = 'return_requested' THEN
        RAISE EXCEPTION 'ORDER_RETURN_PENDING';
    END IF;
    IF v_order.ful_code <> 'delivered' THEN
        RAISE EXCEPTION 'ORDER_NOT_DELIVERED';
    END IF;
    IF v_order.buyer_confirmation_deadline_at IS NOT NULL
       AND v_order.buyer_confirmation_deadline_at <= now() THEN
        RAISE EXCEPTION 'BUYER_CONFIRMATION_EXPIRED';
    END IF;

    UPDATE qr_marketplace.company_shop_orders
    SET buyer_proof_storage_key = v_key,
        buyer_proof_uploaded_at = now(),
        updated_at = now()
    WHERE id = p_order_id;

    RETURN p_order_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_shop_set_seller_proof(p_actor_user_id UUID, p_order_id UUID, p_storage_key TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_company_id UUID;
    v_key TEXT;
BEGIN
    v_key := NULLIF(btrim(coalesce(p_storage_key, '')), '');
    IF v_key IS NULL THEN
        RAISE EXCEPTION 'SELLER_PROOF_REQUIRED';
    END IF;

    v_company_id := qr_api.sp_company_id_for_user(p_actor_user_id);
    IF v_company_id IS NULL THEN
        RAISE EXCEPTION 'COMPANY_NOT_FOUND';
    END IF;

    SELECT o.*, fs.code AS ful_code, os.code AS ord_status_code
    INTO v_order
    FROM qr_marketplace.company_shop_orders o
    JOIN qr_ref.fulfillment_statuses fs ON fs.id = o.fulfillment_status_id
    JOIN qr_ref.order_statuses os ON os.id = o.status_id
    WHERE o.id = p_order_id
    FOR UPDATE OF o;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;
    IF v_order.company_id <> v_company_id THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;
    IF v_order.fulfillment_mode <> 'delivery' THEN
        RAISE EXCEPTION 'NOT_DELIVERY_ORDER';
    END IF;
    IF v_order.ord_status_code NOT IN ('paid', 'fulfilled') THEN
        RAISE EXCEPTION 'ORDER_NOT_PAID';
    END IF;
    IF v_order.ful_code NOT IN ('accepted', 'processing', 'pending', 'shipped', 'in_transit', 'delivered') THEN
        RAISE EXCEPTION 'INVALID_STATUS_TRANSITION';
    END IF;

    UPDATE qr_marketplace.company_shop_orders
    SET seller_proof_storage_key = v_key,
        seller_proof_uploaded_at = now(),
        updated_at = now()
    WHERE id = p_order_id;

    RETURN p_order_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_start_upgrade(p_user_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_company_id UUID;
    v_status_code VARCHAR;
    v_tier VARCHAR;
    v_draft_id BIGINT;
BEGIN
    SELECT c.id, cvs.code, let.contractor_tier
      INTO v_company_id, v_status_code, v_tier
    FROM qr_marketplace.company_members cm
    JOIN qr_marketplace.companies c ON c.id = cm.company_id AND c.deleted_at IS NULL
    JOIN qr_ref.company_verification_statuses cvs ON cvs.id = c.verification_status_id
    JOIN qr_ref.legal_entity_types let ON let.id = c.legal_entity_type_id
    WHERE cm.user_id = p_user_id
    ORDER BY cm.invited_at
    LIMIT 1;

    IF v_company_id IS NULL THEN
        RAISE EXCEPTION 'COMPANY_NOT_FOUND';
    END IF;
    IF v_tier <> 'small' THEN
        RAISE EXCEPTION 'COMPANY_ALREADY_BIG';
    END IF;
    IF v_status_code <> 'verified' THEN
        RAISE EXCEPTION 'COMPANY_NOT_VERIFIED';
    END IF;

    SELECT qr_api.sp_lookup_company_verification_status_id('draft') INTO v_draft_id;

    UPDATE qr_marketplace.companies SET
        verification_status_id = v_draft_id,
        is_active = FALSE,
        verified_at = NULL,
        verified_by_user_id = NULL,
        submitted_at = NULL,
        rejection_reason = NULL
    WHERE id = v_company_id;

    RETURN v_company_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_submit_for_review(p_user_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_company_id UUID;
    v_status_code VARCHAR;
    v_pending_id BIGINT;
    v_tier VARCHAR;
    v_entity VARCHAR;
    v_has_passport BOOLEAN;
    v_has_npd BOOLEAN;
BEGIN
    SELECT c.id, cvs.code, let.contractor_tier, let.code
      INTO v_company_id, v_status_code, v_tier, v_entity
    FROM qr_marketplace.company_members cm
    JOIN qr_marketplace.companies c ON c.id = cm.company_id AND c.deleted_at IS NULL
    JOIN qr_ref.company_verification_statuses cvs ON cvs.id = c.verification_status_id
    JOIN qr_ref.legal_entity_types let ON let.id = c.legal_entity_type_id
    WHERE cm.user_id = p_user_id
    ORDER BY cm.invited_at
    LIMIT 1;

    IF v_company_id IS NULL THEN
        RAISE EXCEPTION 'COMPANY_NOT_FOUND';
    END IF;

    IF v_status_code NOT IN ('draft', 'rejected') THEN
        RAISE EXCEPTION 'COMPANY_ALREADY_SUBMITTED';
    END IF;

    IF v_tier = 'small' THEN
        SELECT EXISTS (
            SELECT 1
            FROM qr_marketplace.company_verification_documents d
            JOIN qr_ref.company_document_types dt ON dt.id = d.document_type_id
            WHERE d.company_id = v_company_id
              AND dt.code = 'passport'
              AND d.storage_key IS NOT NULL
              AND btrim(d.storage_key) <> ''
        ) INTO v_has_passport;
        IF NOT v_has_passport THEN
            RAISE EXCEPTION 'PASSPORT_REQUIRED';
        END IF;
        IF v_entity = 'self_employed' THEN
            SELECT EXISTS (
                SELECT 1
                FROM qr_marketplace.company_verification_documents d
                JOIN qr_ref.company_document_types dt ON dt.id = d.document_type_id
                WHERE d.company_id = v_company_id
                  AND dt.code = 'npd_certificate'
                  AND d.storage_key IS NOT NULL
                  AND btrim(d.storage_key) <> ''
            ) INTO v_has_npd;
            IF NOT v_has_npd THEN
                RAISE EXCEPTION 'NPD_REQUIRED';
            END IF;
        END IF;
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM qr_marketplace.company_bank_details bd
        WHERE bd.company_id = v_company_id AND bd.is_primary = TRUE
    ) THEN
        RAISE EXCEPTION 'BANK_REQUIRED';
    END IF;

    SELECT qr_api.sp_lookup_company_verification_status_id('pending_review') INTO v_pending_id;

    UPDATE qr_marketplace.companies SET
        verification_status_id = v_pending_id,
        submitted_at = now()
    WHERE id = v_company_id;

    RETURN v_company_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_update_description(p_user_id UUID, p_description TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_company_id UUID;
    v_status_code VARCHAR;
BEGIN
    v_company_id := qr_api.sp_company_id_for_user(p_user_id);
    IF v_company_id IS NULL THEN
        RAISE EXCEPTION 'COMPANY_NOT_FOUND';
    END IF;

    SELECT cvs.code INTO v_status_code
    FROM qr_marketplace.companies c
    JOIN qr_ref.company_verification_statuses cvs ON cvs.id = c.verification_status_id
    WHERE c.id = v_company_id AND c.deleted_at IS NULL;

    IF v_status_code IS NULL THEN
        RAISE EXCEPTION 'COMPANY_NOT_FOUND';
    END IF;
    IF v_status_code NOT IN ('draft', 'rejected', 'verified') THEN
        RAISE EXCEPTION 'COMPANY_NOT_EDITABLE: status=%', v_status_code;
    END IF;

    UPDATE qr_marketplace.companies
    SET description = NULLIF(left(btrim(coalesce(p_description, '')), 4000), ''),
        updated_at = now()
    WHERE id = v_company_id;
    RETURN v_company_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_update_draft(p_user_id UUID, p_legal_entity_type_code VARCHAR, p_inn VARCHAR, p_kpp VARCHAR, p_ogrn VARCHAR, p_legal_name VARCHAR, p_short_name VARCHAR, p_legal_address TEXT, p_actual_address TEXT, p_public_email citext, p_public_phone VARCHAR, p_website VARCHAR, p_description TEXT, p_contact_person_name VARCHAR, p_contact_person_position VARCHAR, p_vat_payer BOOLEAN, p_vat_rate DECIMAL, p_bank_name VARCHAR, p_bik VARCHAR, p_correspondent_account VARCHAR, p_settlement_account VARCHAR) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_company_id UUID;
    v_status_code VARCHAR;
    v_entity_type_id BIGINT;
    v_old_tier VARCHAR;
    v_new_tier VARCHAR;
BEGIN
    SELECT c.id, cvs.code, let.contractor_tier
      INTO v_company_id, v_status_code, v_old_tier
    FROM qr_marketplace.company_members cm
    JOIN qr_marketplace.companies c ON c.id = cm.company_id AND c.deleted_at IS NULL
    JOIN qr_ref.company_verification_statuses cvs ON cvs.id = c.verification_status_id
    JOIN qr_ref.legal_entity_types let ON let.id = c.legal_entity_type_id
    WHERE cm.user_id = p_user_id
    ORDER BY cm.invited_at
    LIMIT 1;

    IF v_company_id IS NULL THEN
        RAISE EXCEPTION 'COMPANY_NOT_FOUND';
    END IF;

    IF v_status_code NOT IN ('draft', 'rejected') THEN
        RAISE EXCEPTION 'COMPANY_NOT_EDITABLE: status=%', v_status_code;
    END IF;

    SELECT qr_api.sp_lookup_legal_entity_type_id(p_legal_entity_type_code) INTO v_entity_type_id;
    IF v_entity_type_id IS NULL THEN
        RAISE EXCEPTION 'LOOKUP_NOT_FOUND';
    END IF;

    SELECT contractor_tier INTO v_new_tier
    FROM qr_ref.legal_entity_types WHERE id = v_entity_type_id;

    IF v_old_tier = 'big' AND v_new_tier = 'small' THEN
        RAISE EXCEPTION 'COMPANY_DOWNGRADE_FORBIDDEN';
    END IF;

    IF v_new_tier = 'big' THEN
        IF p_inn IS NULL OR p_ogrn IS NULL OR btrim(coalesce(p_legal_name, '')) = ''
           OR btrim(coalesce(p_legal_address, '')) = '' THEN
            RAISE EXCEPTION 'BIG_COMPANY_REQUISITES_REQUIRED';
        END IF;
        IF p_bank_name IS NULL OR p_bik IS NULL
           OR p_correspondent_account IS NULL OR p_settlement_account IS NULL THEN
            RAISE EXCEPTION 'BANK_REQUIRED';
        END IF;
    ELSIF v_new_tier = 'small' THEN
        IF btrim(coalesce(p_legal_name, '')) = '' THEN
            RAISE EXCEPTION 'FULL_NAME_REQUIRED';
        END IF;
        IF p_bank_name IS NULL OR p_bik IS NULL
           OR p_correspondent_account IS NULL OR p_settlement_account IS NULL THEN
            RAISE EXCEPTION 'BANK_REQUIRED';
        END IF;
    END IF;

    IF p_inn IS NOT NULL AND EXISTS (
        SELECT 1 FROM qr_marketplace.companies c
        WHERE c.inn = p_inn AND c.id <> v_company_id AND c.deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION 'INN_ALREADY_REGISTERED'
            USING ERRCODE = 'unique_violation';
    END IF;

    UPDATE qr_marketplace.companies SET
        legal_entity_type_id = v_entity_type_id,
        inn = p_inn,
        kpp = CASE WHEN v_new_tier = 'small' THEN NULL ELSE p_kpp END,
        ogrn = CASE WHEN v_new_tier = 'small' THEN NULL ELSE p_ogrn END,
        legal_name = p_legal_name,
        short_name = p_short_name,
        legal_address = p_legal_address,
        actual_address = p_actual_address,
        public_email = p_public_email,
        public_phone = p_public_phone,
        website = p_website,
        description = p_description,
        contact_person_name = p_contact_person_name,
        contact_person_position = p_contact_person_position,
        vat_payer = coalesce(p_vat_payer, FALSE),
        vat_rate = p_vat_rate,
        rejection_reason = NULL
    WHERE id = v_company_id;

    IF p_bank_name IS NOT NULL THEN
        UPDATE qr_marketplace.company_bank_details SET
            bank_name = p_bank_name,
            bik = p_bik,
            correspondent_account = p_correspondent_account,
            settlement_account = p_settlement_account
        WHERE company_id = v_company_id AND is_primary = TRUE;

        IF NOT FOUND THEN
            INSERT INTO qr_marketplace.company_bank_details (
                company_id, bank_name, bik, correspondent_account, settlement_account
            ) VALUES (
                v_company_id, p_bank_name, p_bik, p_correspondent_account, p_settlement_account
            );
        END IF;
    END IF;

    RETURN v_company_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_company_verify(p_company_id UUID, p_admin_user_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_verified BIGINT;
    v_owner UUID;
    v_company_name VARCHAR;
    v_current_name VARCHAR;
BEGIN
    PERFORM qr_api.sp_admin_assert_actor(p_admin_user_id);
    SELECT qr_api.sp_lookup_company_verification_status_id('verified') INTO v_verified;
    UPDATE qr_marketplace.companies SET verification_status_id = v_verified, verified_at = now(), verified_by_user_id = p_admin_user_id,
        is_active = TRUE
    WHERE id = p_company_id AND deleted_at IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'COMPANY_NOT_FOUND'; END IF;

    SELECT cm.user_id, btrim(c.legal_name), btrim(coalesce(u.full_name, ''))
    INTO v_owner, v_company_name, v_current_name
    FROM qr_marketplace.companies c
    JOIN qr_marketplace.company_members cm ON cm.company_id = c.id
    JOIN qr_identity.users u ON u.id = cm.user_id
    WHERE c.id = p_company_id
    ORDER BY cm.is_primary_contact DESC, cm.invited_at
    LIMIT 1;

    IF v_owner IS NOT NULL AND coalesce(v_company_name, '') <> '' THEN
        IF v_current_name = '' THEN
            UPDATE qr_identity.users
            SET full_name = v_company_name, pending_full_name = NULL, updated_at = now()
            WHERE id = v_owner;
        ELSIF lower(v_current_name) IS DISTINCT FROM lower(v_company_name) THEN
            UPDATE qr_identity.users
            SET pending_full_name = v_company_name, updated_at = now()
            WHERE id = v_owner;
        ELSE
            UPDATE qr_identity.users
            SET pending_full_name = NULL, updated_at = now()
            WHERE id = v_owner;
        END IF;
    END IF;

    IF v_owner IS NOT NULL THEN
        PERFORM qr_api.sp_user_notification_create(
            v_owner,
            'company_verified', 'Исполнитель подтверждён', 'Можно откликаться на задания',
            'company', p_company_id, '/cabinet/executor'
        );
    END IF;
    RETURN p_company_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_create_checkout_order(p_order_id UUID, p_user_id UUID, p_status_id BIGINT, p_buyer_email citext, p_buyer_phone VARCHAR, p_buyer_name VARCHAR, p_total_amount DECIMAL, p_package_type_id BIGINT, p_quantity INT, p_unit_price_rub DECIMAL, p_line_total_rub DECIMAL, p_snapshot_max_photos INT, p_snapshot_max_video_sec INT, p_snapshot_package_name VARCHAR, p_fulfillment_status_id BIGINT, p_delivery_address TEXT, p_created_by_user_id UUID DEFAULT CAST(NULL AS UUID), p_plaque_fulfillment_mode VARCHAR DEFAULT CAST(NULL AS VARCHAR), p_notes TEXT DEFAULT CAST(NULL AS TEXT)) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
BEGIN
    INSERT INTO qr_commerce.orders (
        id, user_id, status_id, buyer_email, buyer_phone, buyer_name, total_amount,
        created_by_user_id, updated_by_user_id,
        plaque_fulfillment_mode, plaque_fulfillment_chosen_at, notes
    ) VALUES (
        p_order_id, p_user_id, p_status_id, lower(p_buyer_email::text)::citext,
        p_buyer_phone, p_buyer_name, p_total_amount,
        p_created_by_user_id, p_created_by_user_id,
        p_plaque_fulfillment_mode,
        CASE WHEN p_plaque_fulfillment_mode IS NOT NULL THEN now() ELSE NULL END,
        p_notes
    );

    INSERT INTO qr_commerce.order_lines (
        order_id, package_type_id, quantity, unit_price_rub, line_total_rub,
        snapshot_max_photos, snapshot_max_video_sec, snapshot_package_name
    ) VALUES (
        p_order_id, p_package_type_id, p_quantity, p_unit_price_rub, p_line_total_rub,
        p_snapshot_max_photos, p_snapshot_max_video_sec, p_snapshot_package_name
    );

    INSERT INTO qr_commerce.order_deliveries (
        order_id, shipment_number, quantity, fulfillment_status_id, delivery_address
    ) VALUES (
        p_order_id, 1, p_quantity, p_fulfillment_status_id, p_delivery_address
    );

    RETURN p_order_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_create_memorial_review(p_id UUID, p_memorial_id UUID, p_visitor_token UUID, p_author_user_id UUID, p_author_name VARCHAR, p_body TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_pending_id BIGINT;
    v_approved_id BIGINT;
    v_owner_id UUID;
    v_status_id BIGINT;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM qr_memorial.memorials m
        WHERE m.id = p_memorial_id AND m.deleted_at IS NULL AND m.is_published
    ) THEN
        RAISE EXCEPTION 'MEMORIAL_NOT_PUBLISHED' USING ERRCODE = 'check_violation';
    END IF;

    IF p_visitor_token IS NOT NULL AND EXISTS (
        SELECT 1 FROM qr_memorial.memorial_reviews mr
        WHERE mr.memorial_id = p_memorial_id
          AND mr.visitor_token = p_visitor_token
          AND mr.deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION 'REVIEW_ALREADY_EXISTS' USING ERRCODE = 'unique_violation';
    END IF;

    IF p_author_user_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM qr_memorial.memorial_reviews mr
        WHERE mr.memorial_id = p_memorial_id
          AND mr.author_user_id = p_author_user_id
          AND mr.deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION 'REVIEW_ALREADY_EXISTS' USING ERRCODE = 'unique_violation';
    END IF;

    SELECT id INTO v_pending_id FROM qr_ref.review_moderation_statuses WHERE code = 'pending';
    SELECT id INTO v_approved_id FROM qr_ref.review_moderation_statuses WHERE code = 'approved';

    SELECT m.owner_user_id INTO v_owner_id
    FROM qr_memorial.memorials m
    WHERE m.id = p_memorial_id AND m.deleted_at IS NULL;

    IF p_author_user_id IS NOT NULL AND p_author_user_id = v_owner_id THEN
        v_status_id := v_approved_id;
    ELSE
        v_status_id := v_pending_id;
    END IF;

    INSERT INTO qr_memorial.memorial_reviews (
        id, memorial_id, author_user_id, visitor_token,
        author_name, body, moderation_status_id
    ) VALUES (
        p_id, p_memorial_id, p_author_user_id, p_visitor_token,
        p_author_name, p_body, v_status_id
    );

    RETURN p_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_delete_memorial_owner(p_memorial_id UUID, p_actor_user_id UUID) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_owner UUID;
BEGIN
    SELECT owner_user_id INTO v_owner
    FROM qr_memorial.memorials
    WHERE id = p_memorial_id AND deleted_at IS NULL;

    IF v_owner IS NULL THEN
        RAISE EXCEPTION 'MEMORIAL_NOT_FOUND'
            USING ERRCODE = 'no_data_found';
    END IF;

    IF v_owner IS DISTINCT FROM p_actor_user_id THEN
        RAISE EXCEPTION 'FORBIDDEN'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    UPDATE qr_commerce.qr_codes
    SET
        memorial_id = NULL,
        updated_at = now(),
        updated_by_user_id = p_actor_user_id
    WHERE memorial_id = p_memorial_id;

    UPDATE qr_memorial.memorials
    SET
        deleted_at = now(),
        is_published = FALSE,
        updated_at = now(),
        updated_by_user_id = p_actor_user_id
    WHERE id = p_memorial_id AND deleted_at IS NULL;

    RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_delete_memorial_review_owner(p_review_id UUID, p_memorial_id UUID, p_actor_user_id UUID) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_owner UUID;
    v_status VARCHAR(32);
BEGIN
    SELECT m.owner_user_id, rms.code
    INTO v_owner, v_status
    FROM qr_memorial.memorial_reviews mr
    JOIN qr_memorial.memorials m ON m.id = mr.memorial_id AND m.deleted_at IS NULL
    JOIN qr_ref.review_moderation_statuses rms ON rms.id = mr.moderation_status_id
    WHERE mr.id = p_review_id
      AND mr.memorial_id = p_memorial_id
      AND mr.deleted_at IS NULL;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'REVIEW_NOT_FOUND' USING ERRCODE = 'no_data_found';
    END IF;

    IF v_owner IS DISTINCT FROM p_actor_user_id THEN
        RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF v_status NOT IN ('pending', 'approved') THEN
        RAISE EXCEPTION 'REVIEW_NOT_DELETABLE' USING ERRCODE = 'check_violation';
    END IF;

    UPDATE qr_memorial.memorial_reviews
    SET deleted_at = now()
    WHERE id = p_review_id AND deleted_at IS NULL;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_ensure_buyer_user(p_actor_user_id UUID, p_id UUID, p_email citext, p_password_hash VARCHAR, p_full_name VARCHAR DEFAULT CAST(NULL AS VARCHAR), p_phone VARCHAR DEFAULT CAST(NULL AS VARCHAR)) RETURNS TABLE (user_id UUID, created BOOLEAN, email citext, must_change_password BOOLEAN) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_email CITEXT;
    v_existing UUID;
    v_must BOOLEAN;
    v_buyer_role_id BIGINT;
    v_phone VARCHAR;
BEGIN
    IF p_actor_user_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM qr_identity.users u WHERE u.id = p_actor_user_id AND u.deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;

    IF p_email IS NULL OR btrim(p_email::text) = '' THEN
        RAISE EXCEPTION 'EMAIL_REQUIRED' USING ERRCODE = 'check_violation';
    END IF;

    v_email := lower(p_email::text)::citext;
    v_phone := nullif(btrim(coalesce(p_phone, '')), '');

    SELECT u.id, u.must_change_password
    INTO v_existing, v_must
    FROM qr_identity.users u
    WHERE u.email = v_email AND u.deleted_at IS NULL
    LIMIT 1;

    IF v_existing IS NOT NULL THEN
        user_id := v_existing;
        created := FALSE;
        email := v_email;
        must_change_password := coalesce(v_must, FALSE);
        RETURN NEXT;
        RETURN;
    END IF;

    IF p_password_hash IS NULL OR btrim(p_password_hash) = '' THEN
        RAISE EXCEPTION 'PASSWORD_REQUIRED' USING ERRCODE = 'P0001';
    END IF;

    SELECT id INTO v_buyer_role_id FROM qr_ref.user_roles WHERE code = 'buyer';
    IF v_buyer_role_id IS NULL THEN
        RAISE EXCEPTION 'ROLE_NOT_FOUND';
    END IF;

    INSERT INTO qr_identity.users (
        id, role_id, email, phone, password_hash, full_name,
        email_verified, must_change_password, suggest_password_change, is_active,
        created_by_user_id, updated_by_user_id
    ) VALUES (
        p_id, v_buyer_role_id, v_email, v_phone, p_password_hash,
        NULLIF(btrim(coalesce(p_full_name, '')), ''),
        TRUE, FALSE, TRUE, TRUE, p_actor_user_id, p_actor_user_id
    );

    user_id := p_id;
    created := TRUE;
    email := v_email;
    must_change_password := FALSE;
    RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_generate_qr_codes_for_order(p_order_id UUID) RETURNS INT LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_line              qr_commerce.order_lines%ROWTYPE;
    v_order             qr_commerce.orders%ROWTYPE;
    v_generated_status  BIGINT;
    v_i                 INTEGER;
    v_slug              VARCHAR(16);
    v_created           INTEGER := 0;
BEGIN
    IF EXISTS (SELECT 1 FROM qr_commerce.qr_codes WHERE order_id = p_order_id) THEN
        RETURN 0;
    END IF;

    SELECT ol.* INTO v_line FROM qr_commerce.order_lines ol WHERE ol.order_id = p_order_id;
    IF NOT FOUND THEN
        RETURN 0;
    END IF;

    SELECT o.* INTO v_order FROM qr_commerce.orders o WHERE o.id = p_order_id;

    SELECT id INTO v_generated_status FROM qr_ref.qr_code_statuses WHERE code = 'generated';

    FOR v_i IN 1..v_line.quantity LOOP
        LOOP
            v_slug := lower(substring(replace(uuidv7()::text, '-', ''), 1, 10));
            EXIT WHEN NOT EXISTS (SELECT 1 FROM qr_commerce.qr_codes WHERE code_slug = v_slug);
        END LOOP;

        INSERT INTO qr_commerce.qr_codes (
            order_id, order_line_id, package_type_id, status_id, code_slug, sequence_num,
            plaque_fulfillment_mode, plaque_fulfillment_chosen_at
        )
        VALUES (
            p_order_id, v_line.id, v_line.package_type_id, v_generated_status, v_slug, v_i,
            v_order.plaque_fulfillment_mode, v_order.plaque_fulfillment_chosen_at
        );
        v_created := v_created + 1;
    END LOOP;

    RETURN v_created;
END;
$function$

