CREATE OR REPLACE FUNCTION qr_api.sp_insert_media_file(p_id UUID, p_memorial_id UUID, p_media_type_id BIGINT, p_processing_status_id BIGINT, p_uploaded_by_user_id UUID, p_storage_bucket VARCHAR, p_storage_key VARCHAR, p_original_filename VARCHAR, p_mime_type VARCHAR, p_size_bytes BIGINT, p_duration_seconds INT, p_sort_order INT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_photo_type_id BIGINT;
    v_photo_count INTEGER;
    v_max_photos INTEGER;
BEGIN
    SELECT id INTO v_photo_type_id FROM qr_ref.media_types WHERE code = 'photo';

    IF p_media_type_id = v_photo_type_id THEN
        v_photo_count := qr_api.sp_count_memorial_photos(p_memorial_id);
        v_max_photos := qr_api.sp_get_memorial_max_photos(p_memorial_id);

        IF v_photo_count >= v_max_photos THEN
            RAISE EXCEPTION 'PHOTO_LIMIT_REACHED'
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;

    INSERT INTO qr_memorial.media_files (
        id, memorial_id, media_type_id, processing_status_id,
        uploaded_by_user_id, storage_bucket, storage_key,
        original_filename, mime_type, size_bytes, duration_seconds, sort_order
    ) VALUES (
        p_id, p_memorial_id, p_media_type_id, p_processing_status_id,
        p_uploaded_by_user_id, p_storage_bucket, p_storage_key,
        p_original_filename, p_mime_type, p_size_bytes, p_duration_seconds, p_sort_order
    );

    RETURN p_id;
END;
$function$

