END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_memorial_access_check(p_memorial_id UUID, p_visitor_token UUID) RETURNS TABLE (memorial_exists BOOLEAN, is_published BOOLEAN, has_access BOOLEAN, request_id UUID, request_status VARCHAR, grant_expires_at TIMESTAMPTZ) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_published BOOLEAN;
    v_req_id UUID;
    v_status_code VARCHAR(32);
    v_grant TIMESTAMPTZ;
    v_revoked TIMESTAMPTZ;
    v_effective_status VARCHAR(32);
BEGIN
    SELECT m.is_published INTO v_published
    FROM qr_memorial.memorials m
    WHERE m.id = p_memorial_id AND m.deleted_at IS NULL;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, FALSE, FALSE, NULL::UUID, NULL::VARCHAR, NULL::TIMESTAMPTZ;
        RETURN;
    END IF;

    SELECT r.id, s.code, r.grant_expires_at, r.revoked_at
    INTO v_req_id, v_status_code, v_grant, v_revoked
    FROM qr_memorial.memorial_access_requests r
    JOIN qr_ref.memorial_access_request_statuses s ON s.id = r.status_id
    WHERE r.memorial_id = p_memorial_id AND r.visitor_token = p_visitor_token;

    v_effective_status := v_status_code;
    IF v_status_code = 'approved' AND v_revoked IS NULL
       AND v_grant IS NOT NULL AND v_grant <= now() THEN
        v_effective_status := 'expired';
    END IF;

    RETURN QUERY SELECT
        TRUE,
        v_published,
        (
            v_effective_status = 'approved'
            AND v_revoked IS NULL
            AND v_grant IS NOT NULL
            AND v_grant > now()
        ),
        v_req_id,
        v_effective_status,
        v_grant;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_memorial_access_decide(p_request_id UUID, p_actor_user_id UUID, p_approve BOOLEAN) RETURNS TABLE (request_status VARCHAR, grant_expires_at TIMESTAMPTZ) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_req RECORD;
    v_pending_id BIGINT;
    v_approved_id BIGINT;
    v_rejected_id BIGINT;
    v_expires TIMESTAMPTZ;
BEGIN
    SELECT r.id, r.memorial_id, r.visitor_token, s.code, m.owner_user_id
    INTO v_req
    FROM qr_memorial.memorial_access_requests r
    JOIN qr_ref.memorial_access_request_statuses s ON s.id = r.status_id
    JOIN qr_memorial.memorials m ON m.id = r.memorial_id
    WHERE r.id = p_request_id AND m.deleted_at IS NULL;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'REQUEST_NOT_FOUND' USING ERRCODE = 'no_data_found';
    END IF;

    IF v_req.owner_user_id IS DISTINCT FROM p_actor_user_id THEN
        RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT id INTO v_pending_id FROM qr_ref.memorial_access_request_statuses WHERE code = 'pending';
    IF (SELECT status_id FROM qr_memorial.memorial_access_requests WHERE id = p_request_id) <> v_pending_id THEN
        RAISE EXCEPTION 'REQUEST_NOT_PENDING' USING ERRCODE = 'check_violation';
    END IF;

    SELECT id INTO v_approved_id FROM qr_ref.memorial_access_request_statuses WHERE code = 'approved';
    SELECT id INTO v_rejected_id FROM qr_ref.memorial_access_request_statuses WHERE code = 'rejected';

    IF p_approve THEN
        v_expires := now() + interval '7 days';
        UPDATE qr_memorial.memorial_access_requests
        SET status_id = v_approved_id,
            decided_by_user_id = p_actor_user_id,
            decided_at = now(),
            grant_expires_at = v_expires,
            revoked_at = NULL
        WHERE id = p_request_id;

        PERFORM qr_api.sp_memorial_access_log_event(
            v_req.memorial_id, v_req.visitor_token, 'approved', p_request_id, p_actor_user_id,
            jsonb_build_object('grant_expires_at', v_expires)
        );

        RETURN QUERY SELECT 'approved'::VARCHAR, v_expires;
    ELSE
        UPDATE qr_memorial.memorial_access_requests
        SET status_id = v_rejected_id,
            decided_by_user_id = p_actor_user_id,
            decided_at = now(),
            grant_expires_at = NULL
        WHERE id = p_request_id;

        PERFORM qr_api.sp_memorial_access_log_event(
            v_req.memorial_id, v_req.visitor_token, 'rejected', p_request_id, p_actor_user_id, NULL
        );

        RETURN QUERY SELECT 'rejected'::VARCHAR, NULL::TIMESTAMPTZ;
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_memorial_access_log_event(p_memorial_id UUID, p_visitor_token UUID, p_event_type VARCHAR, p_request_id UUID DEFAULT CAST(NULL AS UUID), p_actor_user_id UUID DEFAULT CAST(NULL AS UUID), p_details JSONB DEFAULT CAST(NULL AS JSONB)) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_id UUID := uuidv7();
BEGIN
    INSERT INTO qr_memorial.memorial_access_log (
        id, memorial_id, visitor_token, event_type, request_id, actor_user_id, details
    ) VALUES (
        v_id, p_memorial_id, p_visitor_token, p_event_type, p_request_id, p_actor_user_id, p_details
    );
    RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_memorial_access_request_create(p_memorial_id UUID, p_visitor_token UUID, p_visitor_name VARCHAR, p_message TEXT) RETURNS TABLE (request_id UUID, request_status VARCHAR) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_published BOOLEAN;
    v_owner_id UUID;
    v_memorial_title VARCHAR;
    v_pending_id BIGINT;
    v_approved_id BIGINT;
    v_rejected_id BIGINT;
    v_expired_id BIGINT;
    v_revoked_id BIGINT;
    v_existing RECORD;
    v_new_id UUID;
BEGIN
    SELECT m.is_published, m.owner_user_id, m.deceased_full_name
    INTO v_published, v_owner_id, v_memorial_title
    FROM qr_memorial.memorials m
    WHERE m.id = p_memorial_id AND m.deleted_at IS NULL;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'MEMORIAL_NOT_FOUND' USING ERRCODE = 'no_data_found';
    END IF;

    IF NOT v_published THEN
        RAISE EXCEPTION 'MEMORIAL_NOT_PUBLISHED' USING ERRCODE = 'check_violation';
    END IF;

    SELECT id INTO v_pending_id FROM qr_ref.memorial_access_request_statuses WHERE code = 'pending';
    SELECT id INTO v_approved_id FROM qr_ref.memorial_access_request_statuses WHERE code = 'approved';
    SELECT id INTO v_rejected_id FROM qr_ref.memorial_access_request_statuses WHERE code = 'rejected';
    SELECT id INTO v_expired_id FROM qr_ref.memorial_access_request_statuses WHERE code = 'expired';
    SELECT id INTO v_revoked_id FROM qr_ref.memorial_access_request_statuses WHERE code = 'revoked';

    SELECT r.id, s.code, r.grant_expires_at, r.revoked_at
    INTO v_existing
    FROM qr_memorial.memorial_access_requests r
    JOIN qr_ref.memorial_access_request_statuses s ON s.id = r.status_id
    WHERE r.memorial_id = p_memorial_id AND r.visitor_token = p_visitor_token;

    IF FOUND THEN
        IF v_existing.code = 'approved' AND v_existing.revoked_at IS NULL
           AND v_existing.grant_expires_at IS NOT NULL AND v_existing.grant_expires_at > now() THEN
            RAISE EXCEPTION 'ACCESS_ALREADY_GRANTED' USING ERRCODE = 'check_violation';
        END IF;

        IF v_existing.code = 'pending' THEN
            RAISE EXCEPTION 'ACCESS_REQUEST_ALREADY_PENDING' USING ERRCODE = 'check_violation';
        END IF;

        UPDATE qr_memorial.memorial_access_requests
        SET visitor_name = p_visitor_name,
            message = p_message,
            status_id = v_pending_id,
            decided_by_user_id = NULL,
            decided_at = NULL,
            grant_expires_at = NULL,
            revoked_at = NULL
        WHERE id = v_existing.id;

        PERFORM qr_api.sp_memorial_access_log_event(
            p_memorial_id, p_visitor_token, 'request_resubmitted', v_existing.id, NULL,
            jsonb_build_object('visitor_name', p_visitor_name)
        );

        PERFORM qr_api.sp_user_notification_create(
            v_owner_id,
            'memorial_access_request',
            'Повторный запрос доступа к мемориалу',
            coalesce(p_visitor_name, 'Посетитель') || ' просит просмотр «' || coalesce(v_memorial_title, 'мемориал') || '»',
            'memorial',
            p_memorial_id,
            '/memorial/' || p_memorial_id::TEXT || '/edit'
        );

        RETURN QUERY SELECT v_existing.id, 'pending'::VARCHAR;
        RETURN;
    END IF;

    v_new_id := uuidv7();
    INSERT INTO qr_memorial.memorial_access_requests (
        id, memorial_id, visitor_token, visitor_name, message, status_id
    ) VALUES (
        v_new_id, p_memorial_id, p_visitor_token, p_visitor_name, p_message, v_pending_id
    );

    PERFORM qr_api.sp_memorial_access_log_event(
        p_memorial_id, p_visitor_token, 'request_created', v_new_id, NULL,
        jsonb_build_object('visitor_name', p_visitor_name)
    );

    PERFORM qr_api.sp_user_notification_create(
        v_owner_id,
        'memorial_access_request',
        'Запрос доступа к мемориалу',
        coalesce(p_visitor_name, 'Посетитель') || ' хочет просмотреть «' || coalesce(v_memorial_title, 'мемориал') || '»',
        'memorial',
        p_memorial_id,
        '/memorial/' || p_memorial_id::TEXT || '/edit'
    );

    RETURN QUERY SELECT v_new_id, 'pending'::VARCHAR;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_memorial_access_revoke(p_request_id UUID, p_actor_user_id UUID) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_req RECORD;
    v_revoked_id BIGINT;
BEGIN
    SELECT r.id, r.memorial_id, r.visitor_token, m.owner_user_id
    INTO v_req
    FROM qr_memorial.memorial_access_requests r
    JOIN qr_memorial.memorials m ON m.id = r.memorial_id
    WHERE r.id = p_request_id AND m.deleted_at IS NULL;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'REQUEST_NOT_FOUND' USING ERRCODE = 'no_data_found';
    END IF;

    IF v_req.owner_user_id IS DISTINCT FROM p_actor_user_id THEN
        RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT id INTO v_revoked_id FROM qr_ref.memorial_access_request_statuses WHERE code = 'revoked';

    UPDATE qr_memorial.memorial_access_requests
    SET status_id = v_revoked_id,
        revoked_at = now()
    WHERE id = p_request_id;

    PERFORM qr_api.sp_memorial_access_log_event(
        v_req.memorial_id, v_req.visitor_token, 'revoked', p_request_id, p_actor_user_id, NULL
    );

    RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_moderate_memorial_review(p_review_id UUID, p_memorial_id UUID, p_actor_user_id UUID, p_decision VARCHAR, p_note TEXT DEFAULT CAST(NULL AS TEXT)) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_owner UUID;
    v_status VARCHAR(32);
    v_target_id BIGINT;
BEGIN
    IF p_decision NOT IN ('approved', 'rejected') THEN
        RAISE EXCEPTION 'INVALID_DECISION' USING ERRCODE = 'check_violation';
    END IF;

    SELECT m.owner_user_id, rms.code
    INTO v_owner, v_status
    FROM qr_memorial.memorial_reviews mr
    JOIN qr_memorial.memorials m ON m.id = mr.memorial_id AND m.deleted_at IS NULL
    JOIN qr_ref.review_moderation_statuses rms ON rms.id = mr.moderation_status_id
    WHERE mr.id = p_review_id
      AND mr.memorial_id = p_memorial_id
      AND mr.deleted_at IS NULL;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'REVIEW_NOT_FOUND' USING ERRCODE = 'no_data_found';
    END IF;

    IF v_owner IS DISTINCT FROM p_actor_user_id THEN
        RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF v_status <> 'pending' THEN
        RAISE EXCEPTION 'REVIEW_NOT_PENDING' USING ERRCODE = 'check_violation';
    END IF;

    SELECT id INTO v_target_id FROM qr_ref.review_moderation_statuses WHERE code = p_decision;

    UPDATE qr_memorial.memorial_reviews
    SET
        moderation_status_id = v_target_id,
        moderated_by_user_id = p_actor_user_id,
        moderated_at = now(),
        moderation_note = NULLIF(TRIM(COALESCE(p_note, '')), '')
    WHERE id = p_review_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_monitoring_snapshot_insert(p_metrics JSONB, p_services JSONB, p_alerts TEXT[]) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_platform', 'public'
AS $function$
DECLARE
    v_id UUID;
BEGIN
    INSERT INTO qr_platform.monitoring_snapshots (metrics, services, alerts)
    VALUES (COALESCE(p_metrics, '{}'), COALESCE(p_services, '{}'), COALESCE(p_alerts, '{}'))
    RETURNING id INTO v_id;

    UPDATE qr_platform.monitoring_settings
    SET last_scan_at = NOW()
    WHERE id = 1;

    RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_notify_admins_task_dispute(p_task_id UUID) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_task RECORD;
    v_admin UUID;
BEGIN
    SELECT st.task_number, st.title INTO v_task
    FROM qr_marketplace.service_tasks st
    WHERE st.id = p_task_id;
    IF NOT FOUND THEN RETURN; END IF;

    FOR v_admin IN SELECT user_id FROM qr_api.sp_list_admin_user_ids()
    LOOP
        BEGIN
            PERFORM qr_api.sp_user_notification_create(
                v_admin,
                'task_dispute',
                'Спор по заданию',
                format('Задание №%s «%s» требует решения администратора', v_task.task_number, v_task.title),
                'service_task',
                p_task_id,
                '/admin#tasks'
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'admin task_dispute notification failed admin=% task=%: %', v_admin, p_task_id, SQLERRM;
        END;
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_order_choose_plaque_fulfillment(p_order_id UUID, p_mode VARCHAR, p_user_id UUID DEFAULT CAST(NULL AS UUID)) RETURNS TABLE (order_id UUID, status_code VARCHAR, plaque_fulfillment_mode VARCHAR, plaque_fulfillment_chosen_at TIMESTAMPTZ) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order qr_commerce.orders%ROWTYPE;
    v_paid_id BIGINT;
    v_fulfilled_id BIGINT;
    v_self_print_id BIGINT;
    v_pending_id BIGINT;
    v_processing_id BIGINT;
    v_delivery RECORD;
    v_actor UUID;
BEGIN
    IF p_mode IS NULL OR p_mode NOT IN ('self_print', 'ship') THEN
        RAISE EXCEPTION 'INVALID_PLAQUE_MODE' USING ERRCODE = 'P0001';
    END IF;

    SELECT * INTO v_order
    FROM qr_commerce.orders
    WHERE id = p_order_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
    END IF;

    IF p_user_id IS NOT NULL AND v_order.user_id IS DISTINCT FROM p_user_id THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
    END IF;

    IF v_order.plaque_fulfillment_mode IS NOT NULL THEN
        RAISE EXCEPTION 'PLAQUE_MODE_ALREADY_CHOSEN' USING ERRCODE = 'P0001';
    END IF;

    SELECT id INTO v_paid_id FROM qr_ref.order_statuses WHERE code = 'paid';
    SELECT id INTO v_fulfilled_id FROM qr_ref.order_statuses WHERE code = 'fulfilled';

    IF v_order.status_id IS DISTINCT FROM v_paid_id
       AND v_order.status_id IS DISTINCT FROM v_fulfilled_id
       AND v_order.paid_at IS NULL THEN
        RAISE EXCEPTION 'ORDER_NOT_PAID' USING ERRCODE = 'P0001';
    END IF;

    v_actor := COALESCE(p_user_id, v_order.user_id);

    UPDATE qr_commerce.orders
    SET plaque_fulfillment_mode = p_mode,
        plaque_fulfillment_chosen_at = now(),
        updated_at = now(),
        updated_by_user_id = v_actor
    WHERE id = p_order_id;

    IF p_mode = 'self_print' THEN
        SELECT id INTO v_self_print_id FROM qr_ref.fulfillment_statuses WHERE code = 'self_print';
        SELECT id INTO v_pending_id FROM qr_ref.fulfillment_statuses WHERE code = 'pending';
        SELECT id INTO v_processing_id FROM qr_ref.fulfillment_statuses WHERE code = 'processing';

        FOR v_delivery IN
            SELECT od.id, od.fulfillment_status_id
            FROM qr_commerce.order_deliveries od
            WHERE od.order_id = p_order_id
              AND od.fulfillment_status_id IN (v_pending_id, v_processing_id)
            FOR UPDATE
        LOOP
            INSERT INTO qr_commerce.fulfillment_status_history (
                order_delivery_id, from_status_id, to_status_id, notes, changed_by_user_id
            ) VALUES (
                v_delivery.id,
                v_delivery.fulfillment_status_id,
                v_self_print_id,
                'Покупатель выбрал самостоятельную печать QR',
                v_actor
            );

            UPDATE qr_commerce.order_deliveries
            SET fulfillment_status_id = v_self_print_id,
                updated_at = now(),
                updated_by_user_id = v_actor
            WHERE id = v_delivery.id;
        END LOOP;

        PERFORM qr_api.sp_try_mark_order_fulfilled(p_order_id);
    END IF;

    RETURN QUERY
    SELECT o.id, os.code, o.plaque_fulfillment_mode, o.plaque_fulfillment_chosen_at
    FROM qr_commerce.orders o
    JOIN qr_ref.order_statuses os ON os.id = o.status_id
    WHERE o.id = p_order_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_package_upgrade_from_wallet(p_user_id UUID, p_order_id UUID, p_target_pkg_id BIGINT, p_unit_price DECIMAL, p_max_photos INT, p_max_video_seconds INT, p_pkg_name VARCHAR, p_amount INT, p_description TEXT, p_qr_code_id UUID DEFAULT CAST(NULL AS UUID)) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_commerce', 'qr_memorial', 'qr_identity', 'qr_ref', 'public'
AS $function$
DECLARE
    v_owner UUID;
    v_status VARCHAR;
    v_debit_key UUID;
BEGIN
    SELECT o.user_id, os.code
    INTO v_owner, v_status
    FROM qr_commerce.orders o
    JOIN qr_ref.order_statuses os ON os.id = o.status_id
    WHERE o.id = p_order_id;

    IF v_owner IS NULL THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;
    IF v_owner <> p_user_id THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;
    IF v_status NOT IN ('paid', 'fulfilled') THEN
        RAISE EXCEPTION 'ORDER_NOT_PAID';
    END IF;
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'INVALID_AMOUNT';
    END IF;

    v_debit_key := uuidv7();
    PERFORM qr_api.sp_wallet_debit(
        p_user_id,
        p_amount,
        'package_upgrade',
        'order',
        p_order_id,
        coalesce(nullif(btrim(p_description), ''), 'Повышение пакета мемориала'),
        v_debit_key
    );

    PERFORM qr_api.sp_apply_package_upgrade(
        p_order_id,
        p_target_pkg_id,
        p_unit_price,
        p_max_photos,
        p_max_video_seconds,
        p_pkg_name,
        p_qr_code_id
    );
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_password_reset_issue(p_id UUID, p_user_id UUID, p_token_hash VARCHAR, p_expires_at TIMESTAMPTZ) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
BEGIN
    UPDATE qr_identity.password_reset_tokens
    SET used_at = now()
    WHERE user_id = p_user_id AND used_at IS NULL;

    INSERT INTO qr_identity.password_reset_tokens (id, user_id, token_hash, expires_at)
    VALUES (p_id, p_user_id, p_token_hash, p_expires_at);

    RETURN p_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_password_reset_mark_used(p_id UUID) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
BEGIN
    UPDATE qr_identity.password_reset_tokens
    SET used_at = now()
    WHERE id = p_id AND used_at IS NULL;
    RETURN FOUND;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_qr_choose_plaque_fulfillment(p_qr_code_id UUID, p_mode VARCHAR, p_user_id UUID) RETURNS TABLE (qr_code_id UUID, plaque_fulfillment_mode VARCHAR, plaque_fulfillment_chosen_at TIMESTAMPTZ, order_id UUID) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_qr qr_commerce.qr_codes%ROWTYPE;
    v_order qr_commerce.orders%ROWTYPE;
    v_paid_id BIGINT;
    v_fulfilled_id BIGINT;
BEGIN
    IF p_mode IS NULL OR p_mode NOT IN ('self_print', 'ship') THEN
        RAISE EXCEPTION 'INVALID_PLAQUE_MODE' USING ERRCODE = 'P0001';
    END IF;

    SELECT q.* INTO v_qr
    FROM qr_commerce.qr_codes q
    WHERE q.id = p_qr_code_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'QR_NOT_FOUND' USING ERRCODE = 'P0001';
    END IF;

    IF v_qr.plaque_fulfillment_mode IS NOT NULL THEN
        RAISE EXCEPTION 'PLAQUE_MODE_ALREADY_CHOSEN' USING ERRCODE = 'P0001';
    END IF;

    SELECT o.* INTO v_order
    FROM qr_commerce.orders o
    WHERE o.id = v_qr.order_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
    END IF;

    IF v_order.user_id IS DISTINCT FROM p_user_id THEN
        IF NOT EXISTS (
            SELECT 1 FROM qr_identity.users u
            WHERE u.id = p_user_id
              AND lower(v_order.buyer_email::text) = lower(u.email::text)
        ) THEN
            RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
        END IF;
    END IF;

    SELECT id INTO v_paid_id FROM qr_ref.order_statuses WHERE code = 'paid';
    SELECT id INTO v_fulfilled_id FROM qr_ref.order_statuses WHERE code = 'fulfilled';

    IF v_order.status_id IS DISTINCT FROM v_paid_id
       AND v_order.status_id IS DISTINCT FROM v_fulfilled_id
       AND v_order.paid_at IS NULL THEN
        RAISE EXCEPTION 'ORDER_NOT_PAID' USING ERRCODE = 'P0001';
    END IF;

    UPDATE qr_commerce.qr_codes
    SET plaque_fulfillment_mode = p_mode,
        plaque_fulfillment_chosen_at = now(),
        updated_at = now(),
        updated_by_user_id = p_user_id
    WHERE id = p_qr_code_id;

    PERFORM qr_api.sp_reconcile_order_fulfillment_from_qrs(v_qr.order_id);

    RETURN QUERY
    SELECT q.id, q.plaque_fulfillment_mode, q.plaque_fulfillment_chosen_at, q.order_id
    FROM qr_commerce.qr_codes q
    WHERE q.id = p_qr_code_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_qr_code_set_image_storage_key(p_qr_code_id UUID, p_storage_key VARCHAR) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
BEGIN
    UPDATE qr_commerce.qr_codes
    SET image_storage_key = p_storage_key,
        updated_at = now()
    WHERE id = p_qr_code_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'QR_CODE_NOT_FOUND' USING ERRCODE = 'no_data_found';
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_reconcile_order_fulfillment_from_qrs(p_order_id UUID) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_total INTEGER;
    v_chosen INTEGER;
    v_ship INTEGER;
    v_self INTEGER;
    v_self_print_id BIGINT;
    v_pending_id BIGINT;
    v_processing_id BIGINT;
    v_delivery RECORD;
    v_actor UUID;
BEGIN
    SELECT COUNT(*)::INTEGER,
           COUNT(*) FILTER (WHERE plaque_fulfillment_mode IS NOT NULL)::INTEGER,
           COUNT(*) FILTER (WHERE plaque_fulfillment_mode = 'ship')::INTEGER,
           COUNT(*) FILTER (WHERE plaque_fulfillment_mode = 'self_print')::INTEGER
    INTO v_total, v_chosen, v_ship, v_self
    FROM qr_commerce.qr_codes
    WHERE order_id = p_order_id;

    IF v_total = 0 OR v_chosen < v_total THEN
        RETURN;
    END IF;

    SELECT user_id INTO v_actor FROM qr_commerce.orders WHERE id = p_order_id;

    IF v_self = v_total THEN
        UPDATE qr_commerce.orders
        SET plaque_fulfillment_mode = 'self_print',
            plaque_fulfillment_chosen_at = COALESCE(plaque_fulfillment_chosen_at, now()),
            updated_at = now(),
            updated_by_user_id = v_actor
        WHERE id = p_order_id;

        SELECT id INTO v_self_print_id FROM qr_ref.fulfillment_statuses WHERE code = 'self_print';
        SELECT id INTO v_pending_id FROM qr_ref.fulfillment_statuses WHERE code = 'pending';
        SELECT id INTO v_processing_id FROM qr_ref.fulfillment_statuses WHERE code = 'processing';

        FOR v_delivery IN
            SELECT od.id, od.fulfillment_status_id
            FROM qr_commerce.order_deliveries od
            WHERE od.order_id = p_order_id
              AND od.fulfillment_status_id IN (v_pending_id, v_processing_id)
            FOR UPDATE
        LOOP
            INSERT INTO qr_commerce.fulfillment_status_history (
                order_delivery_id, from_status_id, to_status_id, notes, changed_by_user_id
            ) VALUES (
                v_delivery.id,
                v_delivery.fulfillment_status_id,
                v_self_print_id,
                'Все QR: самостоятельная печать',
                v_actor
            );

            UPDATE qr_commerce.order_deliveries
            SET fulfillment_status_id = v_self_print_id,
                updated_at = now(),
                updated_by_user_id = v_actor
            WHERE id = v_delivery.id;
        END LOOP;
    ELSE
        UPDATE qr_commerce.orders
        SET plaque_fulfillment_mode = 'ship',
            plaque_fulfillment_chosen_at = COALESCE(plaque_fulfillment_chosen_at, now()),
            updated_at = now(),
            updated_by_user_id = v_actor
        WHERE id = p_order_id;

        IF v_ship > 0 THEN
            UPDATE qr_commerce.order_deliveries
            SET quantity = v_ship,
                updated_at = now(),
                updated_by_user_id = v_actor
            WHERE order_id = p_order_id
              AND shipment_number = 1;
        END IF;
    END IF;

    PERFORM qr_api.sp_try_mark_order_fulfilled(p_order_id);
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_register_user(p_id UUID, p_role_id BIGINT, p_email citext, p_phone VARCHAR, p_password_hash VARCHAR, p_full_name VARCHAR, p_email_verified BOOLEAN DEFAULT TRUE) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_email CITEXT;
BEGIN
    IF p_email IS NULL AND p_phone IS NULL THEN
        RAISE EXCEPTION 'LOGIN_REQUIRED'
            USING ERRCODE = 'check_violation';
    END IF;

    IF p_email IS NOT NULL THEN
        v_email := lower(p_email::text)::citext;
        IF qr_api.sp_user_email_exists(v_email) THEN
            RAISE EXCEPTION 'LOGIN_ALREADY_EXISTS'
                USING ERRCODE = 'unique_violation';
        END IF;
    END IF;

    IF p_phone IS NOT NULL AND qr_api.sp_user_phone_exists(p_phone) THEN
        RAISE EXCEPTION 'LOGIN_ALREADY_EXISTS'
            USING ERRCODE = 'unique_violation';
    END IF;

    INSERT INTO qr_identity.users (
        id, role_id, email, phone, password_hash, full_name, email_verified
    ) VALUES (
        p_id, p_role_id, v_email, p_phone,
        p_password_hash, NULLIF(btrim(p_full_name), ''),
        CASE WHEN v_email IS NOT NULL THEN p_email_verified ELSE FALSE END
    );

    IF v_email IS NOT NULL THEN
        PERFORM qr_api.fn_link_guest_orders_to_user(p_id, v_email);
    END IF;

    RETURN p_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_revoke_refresh_token_by_hash(p_token_hash VARCHAR) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
BEGIN
    UPDATE qr_identity.refresh_tokens
    SET revoked_at = now()
    WHERE token_hash = p_token_hash AND revoked_at IS NULL;

    RETURN FOUND;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_admin_confirm_deletion(p_task_id UUID, p_admin_user_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE v_role VARCHAR; v_from BIGINT; v_to BIGINT; v_code VARCHAR;
BEGIN
    SELECT ur.code INTO v_role FROM qr_identity.users u JOIN qr_ref.user_roles ur ON ur.id = u.role_id
    WHERE u.id = p_admin_user_id AND u.deleted_at IS NULL;
    IF v_role IS DISTINCT FROM 'admin' THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

    SELECT sts.code, st.status_id INTO v_code, v_from FROM qr_marketplace.service_tasks st
    JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id WHERE st.id = p_task_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'TASK_NOT_FOUND'; END IF;
    IF v_code <> 'pending_deletion' THEN RAISE EXCEPTION 'INVALID_STATUS'; END IF;

    SELECT qr_api.sp_lookup_service_task_status_id('cancelled') INTO v_to;
    UPDATE qr_marketplace.service_tasks SET status_id = v_to, cancelled_at = now() WHERE id = p_task_id;
    PERFORM qr_api.sp_service_task_log_status(p_task_id, v_from, v_to, p_admin_user_id, 'deletion_confirmed');
    RETURN p_task_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_admin_delete(p_task_id UUID, p_admin_user_id UUID, p_reason TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_role VARCHAR;
    v_title VARCHAR;
    v_number BIGINT;
    v_customer UUID;
    v_company UUID;
    v_owner UUID;
    v_reason TEXT;
BEGIN
    SELECT ur.code INTO v_role
    FROM qr_identity.users u
    JOIN qr_ref.user_roles ur ON ur.id = u.role_id
    WHERE u.id = p_admin_user_id AND u.deleted_at IS NULL;

    IF v_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;

    v_reason := btrim(coalesce(p_reason, ''));
    IF char_length(v_reason) < 3 THEN
        RAISE EXCEPTION 'REASON_REQUIRED';
    END IF;

    SELECT t.title, t.task_number, t.customer_user_id, t.assigned_company_id
    INTO v_title, v_number, v_customer, v_company
    FROM qr_marketplace.service_tasks t
    WHERE t.id = p_task_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'TASK_NOT_FOUND';
    END IF;

    IF v_company IS NOT NULL THEN
        SELECT owner_user_id INTO v_owner
        FROM qr_marketplace.companies
        WHERE id = v_company AND deleted_at IS NULL;
    END IF;

    PERFORM qr_api.sp_user_notification_create(
        v_customer,
        'admin_moderation',
        'Задание удалено',
        format(
            'Задание №%s «%s» было удалено администратором по причине: %s',
            v_number, v_title, v_reason
        ),
        'service_task',
        p_task_id,
        '/cabinet/purchases?tab=tasks'
    );
    IF v_owner IS NOT NULL AND v_owner IS DISTINCT FROM v_customer THEN
        PERFORM qr_api.sp_user_notification_create(
            v_owner,
            'admin_moderation',
            'Задание удалено',
            format(
                'Задание №%s «%s» было удалено администратором по причине: %s',
                v_number, v_title, v_reason
            ),
            'service_task',
            p_task_id,
            '/cabinet/executor'
        );
    END IF;

    DELETE FROM qr_marketplace.executor_payouts WHERE service_task_id = p_task_id;
    DELETE FROM qr_marketplace.service_task_payments WHERE service_task_id = p_task_id;
    UPDATE qr_marketplace.service_tasks SET assigned_bid_id = NULL WHERE id = p_task_id;
    DELETE FROM qr_marketplace.service_tasks WHERE id = p_task_id;

    RETURN p_task_id;
END;
$function$

