CREATE OR REPLACE FUNCTION qr_api.sp_service_task_admin_resolve_dispute(p_task_id UUID, p_admin_user_id UUID, p_winner VARCHAR) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_task RECORD;
    v_from BIGINT;
    v_to BIGINT;
    v_winner VARCHAR;
    v_member RECORD;
    v_pay_cancelled BIGINT;
    v_payout_paid BIGINT;
    v_pay RECORD;
    v_refund_rub INTEGER;
    v_refund_wallet BOOLEAN := FALSE;
BEGIN
    PERFORM qr_api.sp_admin_assert_actor(p_admin_user_id);

    v_winner := lower(btrim(coalesce(p_winner, '')));
    IF v_winner NOT IN ('executor', 'customer') THEN
        RAISE EXCEPTION 'INVALID_WINNER';
    END IF;

    SELECT st.id, st.status_id, st.customer_user_id, st.assigned_company_id,
           st.task_number, st.title, sts.code AS status_code
    INTO v_task
    FROM qr_marketplace.service_tasks st
    JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
    WHERE st.id = p_task_id
    FOR UPDATE OF st;

    IF NOT FOUND THEN RAISE EXCEPTION 'TASK_NOT_FOUND'; END IF;
    IF v_task.status_code <> 'disputed' THEN RAISE EXCEPTION 'NOT_DISPUTED'; END IF;

    v_from := v_task.status_id;

    IF v_winner = 'executor' THEN
        SELECT qr_api.sp_lookup_service_task_status_id('completed') INTO v_to;
        UPDATE qr_marketplace.service_tasks
        SET status_id = v_to,
            verified_at = now(),
            payment_deadline_at = NULL
        WHERE id = p_task_id;
        PERFORM qr_api.sp_service_task_insert_executor_payout(p_task_id);
    ELSE
        SELECT id INTO v_payout_paid FROM qr_ref.payout_statuses WHERE code = 'paid';
        IF EXISTS (
            SELECT 1
            FROM qr_marketplace.executor_payouts ep
            WHERE ep.service_task_id = p_task_id
              AND ep.status_id = v_payout_paid
        ) THEN
            RAISE EXCEPTION 'PAYOUT_ALREADY_PAID';
        END IF;

        DELETE FROM qr_marketplace.executor_payouts ep
        WHERE ep.service_task_id = p_task_id;

        SELECT p.provider, p.provider_payment_id, p.amount_rub
        INTO v_pay
        FROM qr_marketplace.service_task_payments p
        JOIN qr_ref.payment_statuses ps ON ps.id = p.status_id
        WHERE p.service_task_id = p_task_id
          AND ps.code = 'succeeded'
        ORDER BY p.paid_at DESC NULLS LAST, p.created_at DESC
        LIMIT 1;
        IF FOUND AND (
            v_pay.provider = 'wallet'
            OR coalesce(v_pay.provider_payment_id, '') LIKE 'wallet-%'
        ) THEN
            v_refund_wallet := TRUE;
        END IF;

        SELECT id INTO v_pay_cancelled FROM qr_ref.payment_statuses WHERE code = 'cancelled';
        IF v_pay_cancelled IS NULL THEN
            RAISE EXCEPTION 'PAYMENT_STATUS_LOOKUP_FAILED';
        END IF;
        UPDATE qr_marketplace.service_task_payments p
        SET status_id = v_pay_cancelled,
            updated_at = now()
        FROM qr_ref.payment_statuses ps
        WHERE p.service_task_id = p_task_id
          AND p.status_id = ps.id
          AND ps.code = 'succeeded';

        SELECT qr_api.sp_lookup_service_task_status_id('cancelled') INTO v_to;
        UPDATE qr_marketplace.service_tasks
        SET status_id = v_to,
            cancelled_at = now(),
            cancel_reason = 'dispute_resolved_customer',
            payment_deadline_at = NULL,
            verification_deadline_at = NULL
        WHERE id = p_task_id;

        IF v_refund_wallet THEN
            v_refund_rub := round(coalesce(v_pay.amount_rub, 0))::INTEGER;
            IF v_refund_rub > 0 THEN
                PERFORM qr_api.sp_wallet_credit(
                    v_task.customer_user_id,
                    v_refund_rub,
                    'work_refund',
                    'service_task',
                    p_task_id,
                    format('Возврат оплаты работы по заданию №%s', v_task.task_number),
                    md5('dispute_work_refund:' || p_task_id::text)::uuid
                );
            END IF;
        END IF;

        BEGIN
            IF NOT EXISTS (
                SELECT 1 FROM qr_identity.user_payout_details d WHERE d.user_id = v_task.customer_user_id
            ) THEN
                PERFORM qr_api.sp_user_notification_create(
                    v_task.customer_user_id,
                    'payout_details_request',
                    'Укажите реквизиты для возврата',
                    'Спор решён в вашу пользу. Заполните счёт, чтобы перевести деньги.',
                    'user',
                    v_task.customer_user_id,
                    '/cabinet/settings#payout'
                );
            END IF;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'customer payout details request failed: %', SQLERRM;
        END;
    END IF;

    PERFORM qr_api.sp_service_task_log_status(
        p_task_id,
        v_from,
        v_to,
        p_admin_user_id,
        'dispute_resolved_' || v_winner
    );

    BEGIN
        PERFORM qr_api.sp_user_notification_create(
            v_task.customer_user_id,
            'task_verified',
            CASE v_winner
                WHEN 'executor' THEN 'Спор решён в пользу исполнителя'
                ELSE 'Спор решён в вашу пользу'
            END,
            CASE v_winner
                WHEN 'executor' THEN format('Задание №%s принято, выплата исполнителю в обработке', v_task.task_number)
                ELSE format('Задание №%s закрыто, оплата работы возвращается', v_task.task_number)
            END,
            'service_task',
            p_task_id,
            '/tasks/' || p_task_id::TEXT
        );
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'dispute resolve customer notification failed: %', SQLERRM;
    END;

    IF v_task.assigned_company_id IS NOT NULL THEN
        FOR v_member IN
            SELECT cm.user_id
            FROM qr_marketplace.company_members cm
            WHERE cm.company_id = v_task.assigned_company_id
        LOOP
            BEGIN
                PERFORM qr_api.sp_user_notification_create(
                    v_member.user_id,
                    'task_verified',
                    CASE v_winner
                        WHEN 'executor' THEN 'Спор решён в вашу пользу'
                        ELSE 'Спор решён в пользу заказчика'
                    END,
                    CASE v_winner
                        WHEN 'executor' THEN format('Задание №%s: выплата в обработке', v_task.task_number)
                        ELSE format('Задание №%s закрыто, выплата не производится', v_task.task_number)
                    END,
                    'service_task',
                    p_task_id,
                    '/tasks/' || p_task_id::TEXT
                );
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'dispute resolve executor notification failed: %', SQLERRM;
            END;
        END LOOP;
    END IF;

    RETURN p_task_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_admin_restore_published(p_task_id UUID, p_admin_user_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE v_role VARCHAR; v_from BIGINT; v_to BIGINT; v_code VARCHAR;
BEGIN
    SELECT ur.code INTO v_role FROM qr_identity.users u JOIN qr_ref.user_roles ur ON ur.id = u.role_id
    WHERE u.id = p_admin_user_id AND u.deleted_at IS NULL;
    IF v_role IS DISTINCT FROM 'admin' THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

    SELECT sts.code, st.status_id INTO v_code, v_from FROM qr_marketplace.service_tasks st
    JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id WHERE st.id = p_task_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'TASK_NOT_FOUND'; END IF;
