    PERFORM qr_api.sp_service_task_log_status(p_task_id, v_from, v_to, p_admin_user_id, 'restored');
    RETURN p_task_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_apply_payment_succeeded(p_provider_payment_id VARCHAR) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_pay RECORD;
    v_succeeded BIGINT;
BEGIN
    SELECT p.*, st.assigned_company_id, ps.code AS pay_status_code
    INTO v_pay
    FROM qr_marketplace.service_task_payments p
    JOIN qr_marketplace.service_tasks st ON st.id = p.service_task_id
    JOIN qr_ref.payment_statuses ps ON ps.id = p.status_id
    WHERE p.provider_payment_id = p_provider_payment_id
    ORDER BY p.created_at DESC
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    -- Сериализуем параллельные вебхуки по одному заданию: блокируем строку
    -- задания до конца транзакции, чтобы два вебхука не провели выплату дважды.
    PERFORM 1 FROM qr_marketplace.service_tasks WHERE id = v_pay.service_task_id FOR UPDATE;

    -- Этот платёж уже применён (повтор webhook / sync)
    IF v_pay.pay_status_code = 'succeeded' THEN
        RETURN v_pay.service_task_id;
    END IF;

    -- На задание уже проведён другой успешный платёж (двойная оплата/устаревший
    -- или поддельный вебхук по старому платежу) → не проводим и не дублируем выплату.
    IF EXISTS (
        SELECT 1
        FROM qr_marketplace.service_task_payments p2
        JOIN qr_ref.payment_statuses ps2 ON ps2.id = p2.status_id
        WHERE p2.service_task_id = v_pay.service_task_id
          AND ps2.code = 'succeeded'
    ) THEN
        RETURN v_pay.service_task_id;
    END IF;

    IF v_pay.assigned_company_id IS NULL THEN
        RAISE EXCEPTION 'TASK_HAS_NO_ASSIGNED_COMPANY';
    END IF;

    SELECT id INTO v_succeeded FROM qr_ref.payment_statuses WHERE code = 'succeeded';

    IF v_succeeded IS NULL THEN
        RAISE EXCEPTION 'PAYMENT_STATUS_LOOKUP_FAILED';
    END IF;

    UPDATE qr_marketplace.service_task_payments
    SET status_id = v_succeeded, paid_at = now(), updated_at = now()
    WHERE id = v_pay.id;

    -- В работу только если исполнитель тоже оплатил комиссию отклика.
    PERFORM qr_api.sp_service_task_try_start_work(v_pay.service_task_id);

    RETURN v_pay.service_task_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_assign_executor(p_task_id UUID, p_bid_id UUID, p_user_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_from BIGINT; v_to BIGINT; v_code VARCHAR;
    v_bid RECORD; v_final NUMERIC(12,2);
    v_items_total NUMERIC(12,2);
    v_factor NUMERIC(20,6);
    v_accepted BIGINT; v_rejected BIGINT;
    v_is_customer BOOLEAN;
    v_is_executor BOOLEAN;
BEGIN
    SELECT sts.code, st.status_id, (st.customer_user_id = p_user_id) INTO v_code, v_from, v_is_customer
    FROM qr_marketplace.service_tasks st JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
    WHERE st.id = p_task_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'TASK_NOT_FOUND'; END IF;
    IF v_code <> 'published' THEN RAISE EXCEPTION 'INVALID_STATUS'; END IF;

    SELECT b.id, b.company_id, b.proposed_amount_rub, b.status_id,
           b.customer_accepted_at, b.executor_accepted_at,
           bs.code AS bid_status_code
    INTO v_bid
    FROM qr_marketplace.service_task_bids b
    JOIN qr_ref.bid_statuses bs ON bs.id = b.status_id
    WHERE b.id = p_bid_id AND b.service_task_id = p_task_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'BID_NOT_FOUND'; END IF;
    IF v_bid.bid_status_code <> 'submitted' THEN RAISE EXCEPTION 'BID_NOT_OPEN'; END IF;

    SELECT EXISTS (
        SELECT 1 FROM qr_marketplace.company_members cm
        WHERE cm.company_id = v_bid.company_id AND cm.user_id = p_user_id
          AND coalesce(cm.can_manage_bids, TRUE)
    ) INTO v_is_executor;

    IF NOT coalesce(v_is_customer, FALSE) AND NOT coalesce(v_is_executor, FALSE) THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;

    -- Назначение только после обоюдного принятия текущей цены.
    IF v_bid.customer_accepted_at IS NULL OR v_bid.executor_accepted_at IS NULL THEN
        RAISE EXCEPTION 'PRICE_NOT_MUTUALLY_ACCEPTED';
    END IF;

    v_final := coalesce(v_bid.proposed_amount_rub, (SELECT desired_amount_rub FROM qr_marketplace.service_tasks WHERE id = p_task_id));
    IF v_final IS NULL THEN RAISE EXCEPTION 'INVALID_AMOUNT'; END IF;

    SELECT qr_api.sp_lookup_service_task_status_id('awaiting_payment') INTO v_to;
    SELECT qr_api.sp_lookup_bid_status_id('accepted') INTO v_accepted;
    SELECT qr_api.sp_lookup_bid_status_id('rejected') INTO v_rejected;

    UPDATE qr_marketplace.service_tasks SET
        status_id = v_to, assigned_company_id = v_bid.company_id, assigned_bid_id = p_bid_id,
        assigned_at = now(), final_amount_rub = v_final,
        payment_deadline_at = now() + interval '1 day'
    WHERE id = p_task_id;

    -- Обновляем “сумму услуги” в строках service_task_items, чтобы карточка услуги
    -- совпадала с согласованной (final_amount_rub) ценой.
    SELECT coalesce(sum(line_total_rub), 0) INTO v_items_total
    FROM qr_marketplace.service_task_items
    WHERE service_task_id = p_task_id;

    IF v_items_total > 0 THEN
        v_factor := v_final / v_items_total;
        UPDATE qr_marketplace.service_task_items
        SET
            unit_price_rub = round(unit_price_rub * v_factor, 2),
            line_total_rub = round(line_total_rub * v_factor, 2),
            updated_at = now()
        WHERE service_task_id = p_task_id;
    ELSE
        UPDATE qr_marketplace.service_task_items
        SET
            unit_price_rub = v_final,
            line_total_rub = v_final * quantity,
            updated_at = now()
        WHERE service_task_id = p_task_id;
    END IF;

    UPDATE qr_marketplace.service_task_items SET is_locked = TRUE WHERE service_task_id = p_task_id;
    UPDATE qr_marketplace.service_task_bids SET status_id = v_accepted, updated_at = now() WHERE id = p_bid_id;
    UPDATE qr_marketplace.service_task_bids SET status_id = v_rejected, updated_at = now()
    WHERE service_task_id = p_task_id AND id <> p_bid_id AND status_id = qr_api.sp_lookup_bid_status_id('submitted');

    PERFORM qr_api.sp_service_task_log_status(p_task_id, v_from, v_to, p_user_id, 'executor_assigned');

    PERFORM qr_api.sp_user_notification_create(
        (SELECT cm.user_id FROM qr_marketplace.company_members cm WHERE cm.company_id = v_bid.company_id LIMIT 1),
        'task_assigned', 'Оплатите комиссию отклика',
        'Цена согласована по заданию «' || (SELECT title FROM qr_marketplace.service_tasks WHERE id = p_task_id)
            || '». Оплатите комиссию 10% с баланса — после оплаты обеих сторон откроется чат.',
        'service_task', p_task_id, '/tasks/' || p_task_id::TEXT
    );
    PERFORM qr_api.sp_user_notification_create(
        (SELECT customer_user_id FROM qr_marketplace.service_tasks WHERE id = p_task_id),
        'task_payment_required',
        'Оплатите работу исполнителя',
        'Цена согласована — оплатите работу картой. Чат откроется, когда оплатите вы и исполнитель.',
        'service_task', p_task_id, '/tasks/' || p_task_id::TEXT
    );
    RETURN p_task_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_bid_accept_price(p_user_id UUID, p_bid_id UUID) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_bid RECORD;
    v_task RECORD;
    v_role VARCHAR(16);
    v_notify_user UUID;
    v_company_name VARCHAR;
    v_customer_ok BOOLEAN;
    v_executor_ok BOOLEAN;
BEGIN
    SELECT b.id, b.service_task_id, b.company_id, b.proposed_amount_rub,
           b.customer_accepted_at, b.executor_accepted_at, bs.code AS bid_status_code
    INTO v_bid
    FROM qr_marketplace.service_task_bids b
    JOIN qr_ref.bid_statuses bs ON bs.id = b.status_id
    WHERE b.id = p_bid_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'BID_NOT_FOUND'; END IF;
    IF v_bid.bid_status_code <> 'submitted' THEN RAISE EXCEPTION 'BID_NOT_OPEN'; END IF;
    IF v_bid.proposed_amount_rub IS NULL THEN RAISE EXCEPTION 'INVALID_AMOUNT'; END IF;

    SELECT st.id, st.customer_user_id, sts.code AS status_code, st.title, st.task_number
    INTO v_task
    FROM qr_marketplace.service_tasks st
    JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
    WHERE st.id = v_bid.service_task_id;
    IF v_task.status_code <> 'published' THEN RAISE EXCEPTION 'TASK_NOT_OPEN_FOR_BIDS'; END IF;

    IF v_task.customer_user_id = p_user_id THEN
        v_role := 'customer';
        SELECT cm.user_id INTO v_notify_user
        FROM qr_marketplace.company_members cm
        WHERE cm.company_id = v_bid.company_id
        ORDER BY coalesce(cm.can_manage_bids, TRUE) DESC, cm.invited_at
        LIMIT 1;
        UPDATE qr_marketplace.service_task_bids
        SET customer_accepted_at = coalesce(customer_accepted_at, now()), updated_at = now()
        WHERE id = p_bid_id;
    ELSIF EXISTS (
        SELECT 1 FROM qr_marketplace.company_members cm
        WHERE cm.company_id = v_bid.company_id AND cm.user_id = p_user_id
          AND coalesce(cm.can_manage_bids, TRUE)
    ) THEN
        v_role := 'executor';
        v_notify_user := v_task.customer_user_id;
        UPDATE qr_marketplace.service_task_bids
        SET executor_accepted_at = coalesce(executor_accepted_at, now()), updated_at = now()
        WHERE id = p_bid_id;
    ELSE
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;

    SELECT customer_accepted_at IS NOT NULL, executor_accepted_at IS NOT NULL
    INTO v_customer_ok, v_executor_ok
    FROM qr_marketplace.service_task_bids WHERE id = p_bid_id;

    SELECT coalesce(c.short_name, c.legal_name) INTO v_company_name
    FROM qr_marketplace.companies c WHERE c.id = v_bid.company_id;

    IF v_customer_ok AND v_executor_ok THEN
        PERFORM qr_api.sp_service_task_assign_executor(v_task.id, p_bid_id, p_user_id);
        RETURN TRUE;
    END IF;

    PERFORM qr_api.sp_user_notification_create(
        v_notify_user,
        'task_bid_price_accepted',
        'Цена принята по заданию № ' || v_task.task_number,
        CASE
            WHEN v_role = 'customer' THEN
                'Заказчик принял цену ' || trim(to_char(v_bid.proposed_amount_rub, '9999999990.99'))
                || ' ₽. Подтвердите со своей стороны, чтобы закрепить задание.'
            ELSE
                coalesce(v_company_name, 'Исполнитель') || ' принял(а) цену '
                || trim(to_char(v_bid.proposed_amount_rub, '9999999990.99'))
                || ' ₽. Подтвердите со своей стороны, чтобы закрепить задание.'
        END,
        'service_task',
        v_task.id,
        '/tasks/' || v_task.id::TEXT
    );
    RETURN FALSE;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_bid_propose_amount(p_user_id UUID, p_bid_id UUID, p_amount_rub DECIMAL) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_bid RECORD;
    v_task RECORD;
    v_role VARCHAR(16);
    v_notify_user UUID;
    v_company_name VARCHAR;
BEGIN
    IF p_amount_rub IS NULL OR p_amount_rub < 0 THEN
        RAISE EXCEPTION 'INVALID_AMOUNT' USING ERRCODE = 'check_violation';
    END IF;

    SELECT b.id, b.service_task_id, b.company_id, b.proposed_amount_rub, bs.code AS bid_status_code
    INTO v_bid
    FROM qr_marketplace.service_task_bids b
    JOIN qr_ref.bid_statuses bs ON bs.id = b.status_id
    WHERE b.id = p_bid_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'BID_NOT_FOUND'; END IF;
    IF v_bid.bid_status_code <> 'submitted' THEN RAISE EXCEPTION 'BID_NOT_OPEN'; END IF;

    SELECT st.id, st.customer_user_id, sts.code AS status_code, st.title, st.task_number,
           st.desired_amount_rub
    INTO v_task
    FROM qr_marketplace.service_tasks st
    JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
    WHERE st.id = v_bid.service_task_id;
    IF v_task.status_code <> 'published' THEN RAISE EXCEPTION 'TASK_NOT_OPEN_FOR_BIDS'; END IF;

    IF v_task.customer_user_id = p_user_id THEN
        v_role := 'customer';
        SELECT cm.user_id INTO v_notify_user
        FROM qr_marketplace.company_members cm
        WHERE cm.company_id = v_bid.company_id
        ORDER BY coalesce(cm.can_manage_bids, TRUE) DESC, cm.invited_at
        LIMIT 1;
    ELSIF EXISTS (
        SELECT 1 FROM qr_marketplace.company_members cm
        WHERE cm.company_id = v_bid.company_id AND cm.user_id = p_user_id
          AND coalesce(cm.can_manage_bids, TRUE)
    ) THEN
        v_role := 'executor';
        v_notify_user := v_task.customer_user_id;
    ELSE
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;

    UPDATE qr_marketplace.service_task_bids SET
        proposed_amount_rub = p_amount_rub,
        customer_accepted_at = CASE WHEN v_role = 'customer' THEN now() ELSE NULL END,
        executor_accepted_at = CASE WHEN v_role = 'executor' THEN now() ELSE NULL END,
        updated_at = now()
    WHERE id = p_bid_id;

    INSERT INTO qr_marketplace.service_task_bid_offers (
        bid_id, amount_rub, offered_by_role, offered_by_user_id
    ) VALUES (
        p_bid_id, p_amount_rub, v_role, p_user_id
    );

    SELECT coalesce(c.short_name, c.legal_name) INTO v_company_name
    FROM qr_marketplace.companies c WHERE c.id = v_bid.company_id;

    PERFORM qr_api.sp_user_notification_create(
        v_notify_user,
        'task_bid_price_proposed',
        'Новая ставка по заданию № ' || v_task.task_number,
        CASE
            WHEN v_role = 'customer' THEN
                'заказчик предлагает ' || round(p_amount_rub)::bigint::text
                || ' рублей по заданию «' || v_task.title || '»'
            ELSE
                'компания «' || coalesce(v_company_name, 'компания') || '» предлагает '
                || round(p_amount_rub)::bigint::text || ' рублей по заданию «' || v_task.title || '»'
        END,
        'service_task',
        v_task.id,
        '/tasks/' || v_task.id::TEXT
    );

    RETURN p_bid_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_bid_submit(p_user_id UUID, p_task_id UUID, p_message TEXT, p_proposed_amount_rub DECIMAL) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_company_id UUID;
    v_verification_code VARCHAR;
    v_task RECORD;
    v_bid_id UUID;
    v_submitted_id BIGINT;
    v_company_name VARCHAR;
    v_amount NUMERIC(12, 2);
BEGIN
    SELECT c.id, cvs.code, coalesce(c.short_name, c.legal_name)
    INTO v_company_id, v_verification_code, v_company_name
    FROM qr_marketplace.company_members cm
    JOIN qr_marketplace.companies c ON c.id = cm.company_id AND c.deleted_at IS NULL
    JOIN qr_ref.company_verification_statuses cvs ON cvs.id = c.verification_status_id
    WHERE cm.user_id = p_user_id
      AND coalesce(cm.can_manage_bids, TRUE)
    LIMIT 1;

    IF v_company_id IS NULL THEN
        RAISE EXCEPTION 'COMPANY_NOT_FOUND' USING ERRCODE = 'no_data_found';
    END IF;

    IF v_verification_code <> 'verified' THEN
        RAISE EXCEPTION 'COMPANY_NOT_VERIFIED' USING ERRCODE = 'check_violation';
    END IF;

    SELECT st.id, st.customer_user_id, sts.code AS status_code, st.title, st.task_number,
           st.desired_amount_rub
    INTO v_task
    FROM qr_marketplace.service_tasks st
    JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
    WHERE st.id = p_task_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'TASK_NOT_FOUND' USING ERRCODE = 'no_data_found';
    END IF;

    IF v_task.customer_user_id = p_user_id THEN
        RAISE EXCEPTION 'CANNOT_BID_OWN_TASK' USING ERRCODE = 'check_violation';
    END IF;

    IF v_task.status_code <> 'published' THEN
        RAISE EXCEPTION 'TASK_NOT_OPEN_FOR_BIDS' USING ERRCODE = 'check_violation';
    END IF;

    v_amount := coalesce(p_proposed_amount_rub, v_task.desired_amount_rub);
    IF v_amount IS NULL OR v_amount < 0 THEN
        RAISE EXCEPTION 'INVALID_AMOUNT' USING ERRCODE = 'check_violation';
    END IF;

    SELECT qr_api.sp_lookup_bid_status_id('submitted') INTO v_submitted_id;

    INSERT INTO qr_marketplace.service_task_bids (
        service_task_id, company_id, status_id, proposed_amount_rub,
        message, created_by_user_id,
        customer_accepted_at, executor_accepted_at
    ) VALUES (
        p_task_id, v_company_id, v_submitted_id, v_amount,
        p_message, p_user_id,
        NULL, now()
    )
    RETURNING id INTO v_bid_id;

    INSERT INTO qr_marketplace.service_task_bid_offers (
        bid_id, amount_rub, offered_by_role, offered_by_user_id
    ) VALUES (
        v_bid_id, v_amount, 'executor', p_user_id
    );

    -- Статус и desired_amount задания не меняются: согласование цены идёт внутри отклика.
    -- Комиссия исполнителя списывается после согласования цены (не при первичном отклике).

    PERFORM qr_api.sp_user_notification_create(
        v_task.customer_user_id,
        'task_bid_received',
        'Новый отклик на задание № ' || v_task.task_number,
        'компания «' || coalesce(v_company_name, 'компания') || '» предложила '
            || round(v_amount)::bigint::text || ' рублей по заданию «' || v_task.title || '»',
        'service_task',
        p_task_id,
        '/tasks/' || p_task_id::TEXT
    );

    RETURN v_bid_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_bid_withdraw(p_task_id UUID, p_user_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE v_bid_id UUID; v_withdrawn BIGINT;
BEGIN
    SELECT b.id INTO v_bid_id FROM qr_marketplace.service_task_bids b
    JOIN qr_marketplace.company_members cm ON cm.company_id = b.company_id AND cm.user_id = p_user_id
    WHERE b.service_task_id = p_task_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'BID_NOT_FOUND'; END IF;
    SELECT qr_api.sp_lookup_bid_status_id('withdrawn') INTO v_withdrawn;
    UPDATE qr_marketplace.service_task_bids SET
        status_id = v_withdrawn,
        customer_accepted_at = NULL,
        executor_accepted_at = NULL,
        updated_at = now()
    WHERE id = v_bid_id;
    RETURN v_bid_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_cancel(p_task_id UUID, p_user_id UUID, p_reason TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_from BIGINT;
    v_to BIGINT;
    v_code VARCHAR;
    v_owner_id UUID;
    v_assigned_bid_id UUID;
    v_publish_fee INTEGER;
    v_bid_fee INTEGER;
    v_executor_user_id UUID;
    v_task_number BIGINT;
    v_title VARCHAR;
BEGIN
    SELECT sts.code, st.status_id, st.customer_user_id, st.assigned_bid_id, st.task_number, st.title
    INTO v_code, v_from, v_owner_id, v_assigned_bid_id, v_task_number, v_title
    FROM qr_marketplace.service_tasks st JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
    WHERE st.id = p_task_id AND st.customer_user_id = p_user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
    IF v_code IN ('completed', 'cancelled') THEN RAISE EXCEPTION 'INVALID_STATUS'; END IF;
    SELECT qr_api.sp_lookup_service_task_status_id('cancelled') INTO v_to;
    UPDATE qr_marketplace.service_tasks SET status_id = v_to, cancelled_at = now(), cancel_reason = p_reason
    WHERE id = p_task_id;
    PERFORM qr_api.sp_service_task_log_status(p_task_id, v_from, v_to, p_user_id, p_reason);

    SELECT abs(wt.amount) INTO v_publish_fee
    FROM qr_commerce.wallet_transactions wt
    WHERE wt.reference_type = 'service_task'
      AND wt.reference_id = p_task_id
      AND wt.type = 'task_publish_fee'
    LIMIT 1;

    IF v_publish_fee IS NOT NULL AND v_publish_fee > 0 THEN
        PERFORM qr_api.sp_wallet_credit(
            v_owner_id,
            v_publish_fee,
            'task_cancel_refund',
            'service_task',
            p_task_id,
            format('Возврат комиссии за задание «%s»', v_title),
            uuidv7()
        );
    END IF;

    IF v_code = 'awaiting_payment' AND v_assigned_bid_id IS NOT NULL THEN
        SELECT abs(wt.amount), cm.user_id
        INTO v_bid_fee, v_executor_user_id
        FROM qr_commerce.wallet_transactions wt
        JOIN qr_marketplace.service_task_bids b ON b.id = wt.reference_id
        JOIN qr_marketplace.company_members cm ON cm.company_id = b.company_id
        WHERE wt.reference_type = 'bid'
          AND wt.type = 'bid_fee'
          AND b.id = v_assigned_bid_id
        ORDER BY cm.is_primary_contact DESC NULLS LAST
        LIMIT 1;

        IF v_bid_fee IS NOT NULL AND v_bid_fee > 0 AND v_executor_user_id IS NOT NULL THEN
            PERFORM qr_api.sp_wallet_credit(
                v_executor_user_id,
                v_bid_fee,
                'bid_refund',
                'bid',
                v_assigned_bid_id,
                format('Возврат комиссии за отклик на задание «%s»', v_title),
                uuidv7()
            );
        END IF;
    END IF;

    RETURN p_task_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_count_by_customer(p_user_id UUID) RETURNS BIGINT LANGUAGE sql STABLE AS $$
    SELECT COUNT(*)::BIGINT FROM qr_marketplace.service_tasks st WHERE st.customer_user_id = p_user_id;
$$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_create(p_customer_user_id UUID, p_title VARCHAR, p_description TEXT, p_category_code VARCHAR, p_desired_amount_rub DECIMAL, p_grave_latitude DECIMAL, p_grave_longitude DECIMAL, p_grave_location_label VARCHAR, p_cemetery_id INT, p_memorial_id UUID, p_preferred_company_id UUID, p_publish BOOLEAN, p_items_json JSONB, p_graves_json JSONB DEFAULT CAST(NULL AS JSONB), p_desired_completion_at DATE DEFAULT CAST(NULL AS DATE), p_attributes JSONB DEFAULT CAST(NULL AS JSONB)) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_task_id UUID;
    v_status_id BIGINT;
    v_category_id BIGINT;
    v_item JSONB;
    v_grave JSONB;
    v_sort SMALLINT := 0;
    v_grave_sort SMALLINT := 0;
    v_first_memorial UUID;
    v_first_lat NUMERIC(10, 7);
    v_first_lng NUMERIC(10, 7);
    v_member RECORD;
    v_attributes JSONB;
    v_task_number BIGINT;
BEGIN
    IF p_desired_completion_at IS NOT NULL AND p_desired_completion_at <= CURRENT_DATE THEN
        RAISE EXCEPTION 'DESIRED_COMPLETION_NOT_IN_FUTURE';
    END IF;

    IF p_desired_amount_rub IS NOT NULL AND p_desired_amount_rub < 10 THEN
        RAISE EXCEPTION 'MIN_TASK_AMOUNT';
    END IF;

    SELECT qr_api.sp_lookup_service_category_id(p_category_code) INTO v_category_id;
    IF v_category_id IS NULL THEN
        RAISE EXCEPTION 'CATEGORY_NOT_FOUND';
    END IF;

    IF p_graves_json IS NOT NULL AND jsonb_array_length(p_graves_json) > 1 THEN
        RAISE EXCEPTION 'TOO_MANY_GRAVES';
    END IF;
    IF p_items_json IS NOT NULL AND jsonb_array_length(p_items_json) > 1 THEN
        RAISE EXCEPTION 'TOO_MANY_ITEMS';
    END IF;

    v_attributes := coalesce(p_attributes, '{}'::jsonb);
    IF jsonb_typeof(v_attributes) <> 'object' THEN
        RAISE EXCEPTION 'INVALID_ATTRIBUTES';
    END IF;
    IF length(v_attributes::text) > 4096 THEN
        RAISE EXCEPTION 'ATTRIBUTES_TOO_LARGE';
    END IF;

    IF coalesce(p_publish, FALSE) THEN
        SELECT qr_api.sp_lookup_service_task_status_id('published') INTO v_status_id;
    ELSE
        SELECT qr_api.sp_lookup_service_task_status_id('draft') INTO v_status_id;
    END IF;

    IF p_graves_json IS NOT NULL AND jsonb_array_length(p_graves_json) > 0 THEN
        SELECT
            NULLIF(g.elem->>'memorial_id', '')::UUID,
            NULLIF(g.elem->>'grave_latitude', '')::NUMERIC,
            NULLIF(g.elem->>'grave_longitude', '')::NUMERIC
        INTO v_first_memorial, v_first_lat, v_first_lng
        FROM jsonb_array_elements(p_graves_json) AS g(elem)
        LIMIT 1;
    END IF;

    INSERT INTO qr_marketplace.service_tasks (
        customer_user_id, status_id, memorial_id, cemetery_id,
        title, description, category_id,
        grave_latitude, grave_longitude, grave_location_label,
        desired_completion_at, desired_amount_rub, preferred_company_id, published_at,
        attributes
    ) VALUES (
        p_customer_user_id, v_status_id,
        coalesce(p_memorial_id, v_first_memorial), p_cemetery_id,
        p_title, p_description, v_category_id,
        coalesce(p_grave_latitude, v_first_lat),
        coalesce(p_grave_longitude, v_first_lng),
        p_grave_location_label,
        p_desired_completion_at,
        p_desired_amount_rub, p_preferred_company_id,
        CASE WHEN coalesce(p_publish, FALSE) THEN now() ELSE NULL END,
        v_attributes
    )
    RETURNING id, task_number INTO v_task_id, v_task_number;

    IF p_graves_json IS NOT NULL AND jsonb_array_length(p_graves_json) > 0 THEN
        FOR v_grave IN SELECT * FROM jsonb_array_elements(p_graves_json)
        LOOP
            IF trim(coalesce(v_grave->>'deceased_full_name', '')) = '' THEN
                RAISE EXCEPTION 'DECEASED_NAME_REQUIRED';
            END IF;
            INSERT INTO qr_marketplace.service_task_graves (
                service_task_id, memorial_id, deceased_full_name, region_name, city_name,
                cemetery_name, placement_hint, grave_latitude, grave_longitude,
                grave_photo_storage_key, notes, sort_order
            ) VALUES (
                v_task_id,
                NULLIF(v_grave->>'memorial_id', '')::UUID,
                trim(v_grave->>'deceased_full_name'),
                NULLIF(v_grave->>'region_name', ''),
                NULLIF(v_grave->>'city_name', ''),
                NULLIF(v_grave->>'cemetery_name', ''),
                NULLIF(v_grave->>'placement_hint', ''),
                NULLIF(v_grave->>'grave_latitude', '')::NUMERIC,
                NULLIF(v_grave->>'grave_longitude', '')::NUMERIC,
                NULLIF(v_grave->>'grave_photo_storage_key', ''),
                NULLIF(v_grave->>'notes', ''),
                v_grave_sort
            );
            v_grave_sort := v_grave_sort + 1;
        END LOOP;
    END IF;

    IF p_items_json IS NOT NULL AND jsonb_array_length(p_items_json) > 0 THEN
        FOR v_item IN SELECT * FROM jsonb_array_elements(p_items_json)
        LOOP
            INSERT INTO qr_marketplace.service_task_items (
                service_task_id, title, description, quantity, unit,
                unit_price_rub, line_total_rub, sort_order
            ) VALUES (
                v_task_id,
                v_item->>'title',
                v_item->>'description',
                coalesce((v_item->>'quantity')::NUMERIC, 1),
                coalesce(v_item->>'unit', 'усл.'),
                (v_item->>'unit_price_rub')::NUMERIC,
                (v_item->>'line_total_rub')::NUMERIC,
                v_sort
            );
            v_sort := v_sort + 1;
        END LOOP;
    ELSE
        INSERT INTO qr_marketplace.service_task_items (
            service_task_id, title, quantity, unit, unit_price_rub, line_total_rub
        ) VALUES (
            v_task_id, p_title, 1, 'усл.', p_desired_amount_rub, p_desired_amount_rub
        );
    END IF;

    INSERT INTO qr_marketplace.service_task_status_history (service_task_id, to_status_id, changed_by_user_id)
    VALUES (v_task_id, v_status_id, p_customer_user_id);

    IF coalesce(p_publish, FALSE) AND p_preferred_company_id IS NOT NULL THEN
        FOR v_member IN
            SELECT cm.user_id
            FROM qr_marketplace.company_members cm
            WHERE cm.company_id = p_preferred_company_id
        LOOP
            PERFORM qr_api.sp_user_notification_create(
                v_member.user_id,
                'task_preferred_company',
                'Заказчик указал вашу компанию',
                'Новое задание «' || p_title || '» — вас выбрали предпочтительным исполнителем',
                'service_task',
                v_task_id,
                '/tasks/' || v_task_id::TEXT
            );
        END LOOP;
    END IF;

    RETURN v_task_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_create_payment_record(p_task_id UUID, p_user_id UUID, p_payment_id UUID, p_idempotence_key UUID, p_amount DECIMAL, p_platform_fee DECIMAL, p_executor_payout DECIMAL, p_provider_payment_id VARCHAR, p_confirmation_url TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE v_waiting BIGINT;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM qr_marketplace.service_tasks st JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
        WHERE st.id = p_task_id AND st.customer_user_id = p_user_id AND sts.code = 'awaiting_payment'
    ) THEN RAISE EXCEPTION 'INVALID_STATUS'; END IF;

    SELECT id INTO v_waiting FROM qr_ref.payment_statuses WHERE code = 'waiting';
    IF v_waiting IS NULL THEN
        RAISE EXCEPTION 'PAYMENT_STATUS_LOOKUP_FAILED';
    END IF;

    INSERT INTO qr_marketplace.service_task_payments (
        id, service_task_id, status_id, idempotence_key, amount_rub,
        platform_fee_rub, executor_payout_rub, provider_payment_id, confirmation_url
    ) VALUES (
        p_payment_id, p_task_id, v_waiting, p_idempotence_key, p_amount,
        p_platform_fee, p_executor_payout, p_provider_payment_id, p_confirmation_url
    );
    UPDATE qr_marketplace.service_tasks SET platform_fee_rub = 0 WHERE id = p_task_id;
    RETURN p_payment_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_customer_confirm_verification(p_task_id UUID, p_user_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_from BIGINT;
    v_to BIGINT;
    v_code VARCHAR;
    v_company UUID;
    v_deadline TIMESTAMPTZ;
BEGIN
    SELECT sts.code, st.status_id, st.assigned_company_id, st.verification_deadline_at
    INTO v_code, v_from, v_company, v_deadline
    FROM qr_marketplace.service_tasks st
    JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
    WHERE st.id = p_task_id AND st.customer_user_id = p_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;
    IF v_code <> 'awaiting_verification' THEN
        RAISE EXCEPTION 'INVALID_STATUS';
    END IF;
    IF v_deadline IS NOT NULL AND v_deadline <= now() THEN
        RAISE EXCEPTION 'VERIFICATION_EXPIRED';
    END IF;

    SELECT qr_api.sp_lookup_service_task_status_id('completed') INTO v_to;
    UPDATE qr_marketplace.service_tasks
    SET status_id = v_to,
        verified_at = now(),
        payment_deadline_at = NULL
    WHERE id = p_task_id;
    PERFORM qr_api.sp_service_task_log_status(p_task_id, v_from, v_to, p_user_id, 'customer_confirmed_verification');
    PERFORM qr_api.sp_service_task_insert_executor_payout(p_task_id);

    IF v_company IS NOT NULL THEN
        PERFORM qr_api.sp_user_notification_create(
            (SELECT cm.user_id FROM qr_marketplace.company_members cm WHERE cm.company_id = v_company LIMIT 1),
            'task_verified',
            'Заказчик подтвердил выполнение',
            'Работа принята — выплата в обработке',
            'service_task', p_task_id, '/tasks/' || p_task_id::TEXT
        );
    END IF;

    PERFORM qr_api.sp_company_review_invite_task(p_task_id);
    RETURN p_task_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_customer_open_dispute(p_task_id UUID, p_user_id UUID, p_comment TEXT DEFAULT CAST(NULL AS TEXT)) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_task RECORD;
    v_from BIGINT;
    v_to BIGINT;
    v_comment TEXT;
    v_member RECORD;
BEGIN
    v_comment := NULLIF(btrim(coalesce(p_comment, '')), '');
    IF v_comment IS NOT NULL THEN
        v_comment := left(v_comment, 2000);
    END IF;

    SELECT st.id, st.status_id, st.customer_user_id, st.assigned_company_id,
           st.task_number, st.verification_deadline_at, sts.code AS status_code
    INTO v_task
    FROM qr_marketplace.service_tasks st
    JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
    WHERE st.id = p_task_id
    FOR UPDATE OF st;

    IF NOT FOUND THEN RAISE EXCEPTION 'TASK_NOT_FOUND'; END IF;
    IF v_task.customer_user_id IS DISTINCT FROM p_user_id THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
    IF v_task.status_code = 'awaiting_verification' THEN
        IF v_task.verification_deadline_at IS NOT NULL AND v_task.verification_deadline_at <= now() THEN
            RAISE EXCEPTION 'VERIFICATION_EXPIRED';
        END IF;
    ELSIF v_task.status_code = 'completed' THEN
        IF EXISTS (
            SELECT 1
            FROM qr_marketplace.executor_payouts ep
            JOIN qr_ref.payout_statuses pst ON pst.id = ep.status_id
            WHERE ep.service_task_id = p_task_id AND pst.code = 'paid'
        ) THEN
            RAISE EXCEPTION 'PAYOUT_ALREADY_PAID';
        END IF;
        DELETE FROM qr_marketplace.executor_payouts ep
        WHERE ep.service_task_id = p_task_id;
    ELSE
        RAISE EXCEPTION 'INVALID_STATUS';
    END IF;

    v_from := v_task.status_id;
    SELECT qr_api.sp_lookup_service_task_status_id('disputed') INTO v_to;

    UPDATE qr_marketplace.service_tasks
    SET status_id = v_to
    WHERE id = p_task_id AND status_id = v_from;
    IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_STATUS'; END IF;

    PERFORM qr_api.sp_service_task_log_status(
        p_task_id, v_from, v_to, p_user_id,
        coalesce(v_comment, 'customer_opened_dispute')
    );
    PERFORM qr_api.sp_notify_admins_task_dispute(p_task_id);
    BEGIN
        PERFORM qr_api.sp_support_escalate_task(
            p_task_id,
            'task_dispute',
            coalesce(v_comment, 'Заказчик открыл спор: работа выполнена плохо')
        );
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'customer dispute support escalation failed: %', SQLERRM;
    END;
    IF NOT EXISTS (
        SELECT 1 FROM qr_identity.user_payout_details d WHERE d.user_id = p_user_id
    ) THEN
        BEGIN
            PERFORM qr_api.sp_user_notification_create(
                p_user_id,
                'payout_details_request',
                'Нужны реквизиты для перевода',
                'Если спор решится в вашу пользу, укажите счёт, куда вернуть деньги.',
                'user',
                p_user_id,
                '/cabinet/settings#payout'
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'customer payout details request failed: %', SQLERRM;
        END;
    END IF;

    IF v_task.assigned_company_id IS NOT NULL THEN
        FOR v_member IN
            SELECT cm.user_id
            FROM qr_marketplace.company_members cm
            WHERE cm.company_id = v_task.assigned_company_id
        LOOP
            BEGIN
                PERFORM qr_api.sp_user_notification_create(
                    v_member.user_id,
                    'task_dispute',
                    'Заказчик открыл спор',
                    format('Задание №%s: оплата заморожена до решения администратора', v_task.task_number),
                    'service_task',
                    p_task_id,
                    '/tasks/' || p_task_id::TEXT
                );
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'customer dispute executor notification failed: %', SQLERRM;
            END;
        END LOOP;
    END IF;

    RETURN p_task_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_executor_confirm_verification(p_task_id UUID, p_user_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE v_from BIGINT; v_to BIGINT; v_code VARCHAR; v_customer UUID; v_deadline TIMESTAMPTZ;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM qr_marketplace.service_tasks st
        JOIN qr_marketplace.company_members cm ON cm.company_id = st.assigned_company_id AND cm.user_id = p_user_id
        WHERE st.id = p_task_id
    ) THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;

    SELECT sts.code, st.status_id, st.customer_user_id, st.verification_deadline_at
    INTO v_code, v_from, v_customer, v_deadline
    FROM qr_marketplace.service_tasks st
    JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
    WHERE st.id = p_task_id;

    IF v_code <> 'awaiting_verification' THEN
        RAISE EXCEPTION 'INVALID_STATUS';
    END IF;
    IF v_deadline IS NOT NULL AND v_deadline <= now() THEN
        RAISE EXCEPTION 'VERIFICATION_EXPIRED';
    END IF;

    SELECT qr_api.sp_lookup_service_task_status_id('completed') INTO v_to;
    UPDATE qr_marketplace.service_tasks
    SET status_id = v_to,
        verified_at = now(),
        payment_deadline_at = NULL
    WHERE id = p_task_id;
    PERFORM qr_api.sp_service_task_log_status(p_task_id, v_from, v_to, p_user_id, 'executor_confirmed_verification');
    PERFORM qr_api.sp_service_task_insert_executor_payout(p_task_id);

    PERFORM qr_api.sp_user_notification_create(
        v_customer, 'task_verified',
        'Работа принята',
        'Задание завершено — выплата исполнителю в обработке',
        'service_task', p_task_id, '/tasks/' || p_task_id::TEXT
    );
    PERFORM qr_api.sp_company_review_invite_task(p_task_id);
    RETURN p_task_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_grave_set_photo(p_grave_id UUID, p_user_id UUID, p_storage_key VARCHAR) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_task_id UUID;
    v_code VARCHAR;
BEGIN
    SELECT g.service_task_id INTO v_task_id
    FROM qr_marketplace.service_task_graves g
    WHERE g.id = p_grave_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'GRAVE_NOT_FOUND';
    END IF;

    SELECT sts.code INTO v_code
    FROM qr_marketplace.service_tasks st
    JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
    WHERE st.id = v_task_id AND st.customer_user_id = p_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;

    IF v_code NOT IN ('draft', 'published', 'reviewing') THEN
        RAISE EXCEPTION 'INVALID_STATUS';
    END IF;

    IF EXISTS (
        SELECT 1 FROM qr_marketplace.service_tasks
        WHERE id = v_task_id AND assigned_company_id IS NOT NULL
    ) THEN
        RAISE EXCEPTION 'TASK_ASSIGNED';
    END IF;

    UPDATE qr_marketplace.service_task_graves
    SET grave_photo_storage_key = p_storage_key
    WHERE id = p_grave_id;

    RETURN p_grave_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_insert_executor_payout(p_task_id UUID) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_task RECORD;
    v_payment_id UUID;
    v_pending BIGINT;
BEGIN
    SELECT st.id, st.assigned_company_id, st.final_amount_rub
    INTO v_task
    FROM qr_marketplace.service_tasks st
    WHERE st.id = p_task_id;
    IF NOT FOUND OR v_task.assigned_company_id IS NULL THEN
        RETURN;
    END IF;

    SELECT p.id INTO v_payment_id
    FROM qr_marketplace.service_task_payments p
    JOIN qr_ref.payment_statuses ps ON ps.id = p.status_id
    WHERE p.service_task_id = p_task_id AND ps.code = 'succeeded'
    ORDER BY p.created_at DESC
    LIMIT 1;
    IF v_payment_id IS NULL THEN
        RETURN;
    END IF;

    SELECT qr_api.sp_lookup_payout_status_id('pending') INTO v_pending;
    IF v_pending IS NULL THEN
        RAISE EXCEPTION 'PAYOUT_STATUS_LOOKUP_FAILED';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM qr_marketplace.executor_payouts ep WHERE ep.service_task_id = p_task_id
    ) THEN
        INSERT INTO qr_marketplace.executor_payouts (
            service_task_id, company_id, service_task_payment_id, status_id, amount_rub
        ) VALUES (
            p_task_id,
            v_task.assigned_company_id,
            v_payment_id,
            v_pending,
            coalesce(v_task.final_amount_rub, 0)
        );
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_invite_verifier(p_task_id UUID, p_user_id UUID, p_verifier_type VARCHAR, p_email citext, p_phone VARCHAR, p_name VARCHAR) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_id UUID;
    v_type BIGINT;
    v_pending BIGINT;
    v_code VARCHAR;
    v_deadline TIMESTAMPTZ;
BEGIN
    SELECT sts.code, st.verification_deadline_at
    INTO v_code, v_deadline
    FROM qr_marketplace.service_tasks st
    JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
    WHERE st.id = p_task_id
      AND st.customer_user_id = p_user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
    IF v_code <> 'awaiting_verification' THEN RAISE EXCEPTION 'INVALID_STATUS'; END IF;
    -- Срок общий с момента отметки исполнителем; приглашение не продлевает таймер.
    IF v_deadline IS NULL OR v_deadline <= now() THEN
        RAISE EXCEPTION 'VERIFICATION_EXPIRED';
    END IF;

    SELECT qr_api.sp_lookup_verifier_type_id(p_verifier_type) INTO v_type;
    SELECT qr_api.sp_lookup_task_verifier_status_id('pending') INTO v_pending;
    IF v_type IS NULL THEN RAISE EXCEPTION 'INVALID_VERIFIER_TYPE'; END IF;

    v_id := uuidv7();
    INSERT INTO qr_marketplace.service_task_verifiers (
        id, service_task_id, verifier_type_id, invite_email, invite_phone, invite_name, status_id, expires_at
    ) VALUES (v_id, p_task_id, v_type, p_email, p_phone, p_name, v_pending, v_deadline);

    RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_mark_completed(p_task_id UUID, p_user_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE v_from BIGINT; v_to BIGINT; v_code VARCHAR;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM qr_marketplace.service_tasks st
        JOIN qr_marketplace.company_members cm ON cm.company_id = st.assigned_company_id AND cm.user_id = p_user_id
        WHERE st.id = p_task_id
    ) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

    SELECT sts.code, st.status_id INTO v_code, v_from
    FROM qr_marketplace.service_tasks st JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id WHERE st.id = p_task_id;
    IF v_code <> 'in_progress' THEN RAISE EXCEPTION 'INVALID_STATUS'; END IF;

    SELECT qr_api.sp_lookup_service_task_status_id('awaiting_verification') INTO v_to;
    UPDATE qr_marketplace.service_tasks SET
        status_id = v_to, completed_by_executor_at = now(),
        verification_deadline_at = now() + interval '3 days'
    WHERE id = p_task_id;
    PERFORM qr_api.sp_service_task_log_status(p_task_id, v_from, v_to, p_user_id, 'executor_completed');

    PERFORM qr_api.sp_user_notification_create(
        (SELECT customer_user_id FROM qr_marketplace.service_tasks WHERE id = p_task_id),
        'task_completed', 'Исполнитель отметил задание выполненным',
        '3 дня на проверку: принять самим, пригласить проверяющего от Заказчика (ссылка, без регистрации) или открыть спор. Молчание - работа принята, средства исполнителю. Спор замораживает выплату до решения администратора.',
        'service_task', p_task_id, '/tasks/' || p_task_id::TEXT
    );
    RETURN p_task_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_mark_messages_read(p_task_id UUID, p_user_id UUID) RETURNS INT LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE v_count INTEGER;
BEGIN
    IF NOT qr_api.sp_service_task_user_can_view_private_details(p_task_id, p_user_id) THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;

    UPDATE qr_marketplace.service_task_messages
    SET read_at = now()
    WHERE service_task_id = p_task_id
      AND sender_user_id <> p_user_id
      AND read_at IS NULL;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_pay_executor_fee(p_task_id UUID, p_user_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_task RECORD;
    v_fee INTEGER;
    v_title VARCHAR;
BEGIN
    SELECT st.id, sts.code AS status_code, st.assigned_company_id, st.assigned_bid_id,
           st.final_amount_rub, st.executor_fee_paid_at, st.title
    INTO v_task
    FROM qr_marketplace.service_tasks st
    JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
    WHERE st.id = p_task_id
    FOR UPDATE OF st;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'TASK_NOT_FOUND' USING ERRCODE = 'no_data_found';
    END IF;

    IF v_task.status_code <> 'awaiting_payment' THEN
        RAISE EXCEPTION 'INVALID_STATUS' USING ERRCODE = 'check_violation';
    END IF;

    IF v_task.assigned_company_id IS NULL OR v_task.assigned_bid_id IS NULL THEN
        RAISE EXCEPTION 'NO_EXECUTOR' USING ERRCODE = 'check_violation';
    END IF;

    IF v_task.executor_fee_paid_at IS NOT NULL THEN
        PERFORM qr_api.sp_service_task_try_start_work(p_task_id);
        RETURN p_task_id;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM qr_marketplace.company_members cm
        WHERE cm.company_id = v_task.assigned_company_id
          AND cm.user_id = p_user_id
          AND coalesce(cm.can_manage_bids, TRUE)
    ) THEN
        RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF v_task.final_amount_rub IS NULL OR v_task.final_amount_rub < 0 THEN
        RAISE EXCEPTION 'INVALID_AMOUNT' USING ERRCODE = 'check_violation';
    END IF;

    v_fee := round(v_task.final_amount_rub * 0.10)::INTEGER;
    v_title := coalesce(v_task.title, 'задание');

    IF v_fee > 0 THEN
        PERFORM qr_api.sp_wallet_debit(
            p_user_id,
            v_fee,
            'bid_fee',
            'bid',
            v_task.assigned_bid_id,
            format('Комиссия за отклик на задание «%s»', v_title),
            v_task.assigned_bid_id
        );
    END IF;

    UPDATE qr_marketplace.service_tasks
    SET executor_fee_paid_at = now(), updated_at = now()
    WHERE id = p_task_id;

    PERFORM qr_api.sp_service_task_try_start_work(p_task_id);

    RETURN p_task_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_pay_work_from_wallet(p_task_id UUID, p_user_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_task RECORD;
    v_work INTEGER;
    v_fee INTEGER;
    v_need INTEGER;
    v_balance INTEGER;
    v_payment_id UUID;
    v_succeeded BIGINT;
    v_provider VARCHAR;
BEGIN
    SELECT st.id, st.customer_user_id, sts.code AS status_code,
           st.final_amount_rub, st.title, st.assigned_company_id, st.task_number
    INTO v_task
    FROM qr_marketplace.service_tasks st
    JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
    WHERE st.id = p_task_id
    FOR UPDATE OF st;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'TASK_NOT_FOUND' USING ERRCODE = 'no_data_found';
    END IF;
    IF v_task.customer_user_id <> p_user_id THEN
        RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF v_task.status_code <> 'awaiting_payment' THEN
        RAISE EXCEPTION 'INVALID_STATUS' USING ERRCODE = 'check_violation';
    END IF;
    IF v_task.assigned_company_id IS NULL THEN
        RAISE EXCEPTION 'NO_EXECUTOR' USING ERRCODE = 'check_violation';
    END IF;
    IF v_task.final_amount_rub IS NULL OR v_task.final_amount_rub < 0 THEN
        RAISE EXCEPTION 'INVALID_AMOUNT' USING ERRCODE = 'check_violation';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM qr_marketplace.service_task_payments p
        JOIN qr_ref.payment_statuses ps ON ps.id = p.status_id
        WHERE p.service_task_id = p_task_id AND ps.code = 'succeeded'
    ) THEN
        PERFORM qr_api.sp_service_task_try_start_work(p_task_id);
        RETURN p_task_id;
    END IF;

    v_work := round(v_task.final_amount_rub)::INTEGER;
    v_fee := round(v_task.final_amount_rub * 0.10)::INTEGER;
    v_need := v_work + v_fee;
    v_balance := qr_api.sp_wallet_ensure(p_user_id);
    IF v_need > 0 AND v_balance < v_need THEN
        RAISE EXCEPTION 'INSUFFICIENT_BALANCE';
    END IF;

    IF v_work > 0 THEN
        PERFORM qr_api.sp_wallet_debit(
            p_user_id,
            v_work,
            'work_payment',
            'service_task',
            p_task_id,
            format('Оплата работы по заданию «%s»', coalesce(v_task.title, 'задание')),
            p_task_id
        );
    END IF;
    IF v_fee > 0 THEN
        PERFORM qr_api.sp_wallet_debit(
            p_user_id,
            v_fee,
            'task_publish_fee',
            'service_task',
            p_task_id,
            format('Комиссия сайта по заданию «%s»', coalesce(v_task.title, 'задание')),
            md5('task_site_fee:' || p_task_id::text)::uuid
        );
    END IF;

    SELECT id INTO v_succeeded FROM qr_ref.payment_statuses WHERE code = 'succeeded';
    IF v_succeeded IS NULL THEN
        RAISE EXCEPTION 'PAYMENT_STATUS_LOOKUP_FAILED';
    END IF;

    v_payment_id := uuidv7();
    v_provider := 'wallet-' || v_payment_id::TEXT;
    INSERT INTO qr_marketplace.service_task_payments (
        id, service_task_id, status_id, provider, idempotence_key, amount_rub,
        platform_fee_rub, executor_payout_rub, provider_payment_id, confirmation_url, paid_at
    ) VALUES (
        v_payment_id, p_task_id, v_succeeded, 'wallet', v_payment_id, v_work,
        v_fee, v_work, v_provider, NULL, now()
    );
    UPDATE qr_marketplace.service_tasks SET platform_fee_rub = v_fee, updated_at = now() WHERE id = p_task_id;

    PERFORM qr_api.sp_service_task_try_start_work(p_task_id);
    RETURN p_task_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_process_deadlines() RETURNS TABLE (task_id UUID, kind VARCHAR, conversation_id UUID) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
#variable_conflict use_column
DECLARE
    r RECORD;
    v_from BIGINT;
    v_to BIGINT;
    v_conv UUID;
    v_member RECORD;
BEGIN
    FOR r IN
        SELECT st.id, st.status_id, st.customer_user_id, st.assigned_company_id, st.task_number
        FROM qr_marketplace.service_tasks st
        JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
        WHERE sts.code = 'awaiting_verification'
          AND st.verification_deadline_at IS NOT NULL
          AND st.verification_deadline_at <= now()
        FOR UPDATE OF st SKIP LOCKED
    LOOP
        v_from := r.status_id;
        SELECT qr_api.sp_lookup_service_task_status_id('completed') INTO v_to;
        UPDATE qr_marketplace.service_tasks
        SET status_id = v_to,
            verified_at = now(),
            payment_deadline_at = NULL
        WHERE id = r.id AND status_id = v_from;
        IF FOUND THEN
            PERFORM qr_api.sp_service_task_log_status(
                r.id, v_from, v_to, NULL, 'verification_timeout_accepted'
            );
            PERFORM qr_api.sp_service_task_insert_executor_payout(r.id);

            BEGIN
                PERFORM qr_api.sp_user_notification_create(
                    r.customer_user_id,
                    'task_verified',
                    'Работа принята автоматически',
                    format('Срок проверки задания №%s истёк без ответа - средства уходят исполнителю', r.task_number),
                    'service_task',
                    r.id,
                    '/tasks/' || r.id::TEXT
                );
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'verification timeout customer notification failed: %', SQLERRM;
            END;
            PERFORM qr_api.sp_company_review_invite_task(r.id);

            IF r.assigned_company_id IS NOT NULL THEN
                FOR v_member IN
                    SELECT cm.user_id
                    FROM qr_marketplace.company_members cm
                    WHERE cm.company_id = r.assigned_company_id
                LOOP
                    BEGIN
                        PERFORM qr_api.sp_user_notification_create(
                            v_member.user_id,
                            'task_verified',
                            'Работа принята автоматически',
                            format('Заказчик не ответил за 3 дня по заданию №%s - выплата в обработке', r.task_number),
                            'service_task',
                            r.id,
                            '/tasks/' || r.id::TEXT
                        );
                    EXCEPTION WHEN OTHERS THEN
                        RAISE WARNING 'verification timeout executor notification failed: %', SQLERRM;
                    END;
                END LOOP;
            END IF;

            task_id := r.id; kind := 'verification_timeout_accepted'; conversation_id := NULL;
            RETURN NEXT;
        END IF;
    END LOOP;

    FOR r IN
        SELECT st.id
        FROM qr_marketplace.service_tasks st
        JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
        WHERE sts.code = 'awaiting_payment'
          AND st.payment_deadline_at IS NOT NULL
          AND st.payment_deadline_at <= now()
          AND NOT EXISTS (
              SELECT 1 FROM qr_platform.support_conversations sc
              WHERE sc.service_task_id = st.id
                AND sc.category_code = 'task_overdue'
                AND sc.status_code <> 'archived'
          )
    LOOP
        v_conv := qr_api.sp_support_escalate_task(
            r.id,
            'task_overdue',
            'Истёк срок оплаты (3 дня после подтверждения). Деньги не поступили — требуется разбор.'
        );
        task_id := r.id; kind := 'payment_overdue'; conversation_id := v_conv;
        RETURN NEXT;
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_publish(p_task_id UUID, p_user_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_from BIGINT;
    v_to BIGINT;
    v_draft BIGINT;
BEGIN
    SELECT st.status_id
    INTO v_from
    FROM qr_marketplace.service_tasks st
    WHERE st.id = p_task_id AND st.customer_user_id = p_user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
    SELECT qr_api.sp_lookup_service_task_status_id('draft') INTO v_draft;
    SELECT qr_api.sp_lookup_service_task_status_id('published') INTO v_to;
    IF v_from <> v_draft THEN
        RAISE EXCEPTION 'INVALID_STATUS';
    END IF;
    UPDATE qr_marketplace.service_tasks SET status_id = v_to, published_at = now() WHERE id = p_task_id;
    PERFORM qr_api.sp_service_task_log_status(p_task_id, v_from, v_to, p_user_id, 'published');

    RETURN p_task_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_request_deletion(p_task_id UUID, p_user_id UUID, p_reason TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE v_from BIGINT; v_to BIGINT; v_code VARCHAR;
BEGIN
    SELECT sts.code, st.status_id INTO v_code, v_from
    FROM qr_marketplace.service_tasks st JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
    WHERE st.id = p_task_id AND st.customer_user_id = p_user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
    IF v_code NOT IN ('published', 'reviewing') THEN RAISE EXCEPTION 'INVALID_STATUS'; END IF;
    IF EXISTS (SELECT 1 FROM qr_marketplace.service_tasks WHERE id = p_task_id AND assigned_company_id IS NOT NULL) THEN
        RAISE EXCEPTION 'TASK_ASSIGNED';
    END IF;
    SELECT qr_api.sp_lookup_service_task_status_id('pending_deletion') INTO v_to;
    UPDATE qr_marketplace.service_tasks SET status_id = v_to, cancel_reason = p_reason WHERE id = p_task_id;
    PERFORM qr_api.sp_service_task_log_status(p_task_id, v_from, v_to, p_user_id, coalesce(p_reason, 'deletion_requested'));
    RETURN p_task_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_send_message(p_task_id UUID, p_sender_user_id UUID, p_body TEXT, p_storage_keys TEXT[] DEFAULT CAST(NULL AS TEXT[]), p_mime_types TEXT[] DEFAULT CAST(NULL AS TEXT[]), p_sizes BIGINT[] DEFAULT CAST(NULL AS BIGINT[]), p_filenames TEXT[] DEFAULT CAST(NULL AS TEXT[])) RETURNS TABLE (id UUID, created_at TIMESTAMPTZ) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
#variable_conflict use_column
DECLARE
    v_id UUID;
    v_created TIMESTAMPTZ;
    v_body TEXT := btrim(coalesce(p_body, ''));
    v_assigned UUID;
    v_status VARCHAR;
    v_keys TEXT[] := coalesce(p_storage_keys, ARRAY[]::TEXT[]);
    v_n INT;
    i INT;
    v_key TEXT;
BEGIN
    v_n := coalesce(array_length(v_keys, 1), 0);
    IF v_body = '' AND v_n = 0 THEN RAISE EXCEPTION 'EMPTY_MESSAGE'; END IF;
    IF length(v_body) > 4000 THEN v_body := left(v_body, 4000); END IF;
    IF v_n > 3 THEN RAISE EXCEPTION 'TOO_MANY_ATTACHMENTS'; END IF;

    IF NOT qr_api.sp_service_task_user_can_view_private_details(p_task_id, p_sender_user_id) THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;

    SELECT st.assigned_company_id, sts.code
    INTO v_assigned, v_status
    FROM qr_marketplace.service_tasks st
    JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
    WHERE st.id = p_task_id;
    IF v_assigned IS NULL THEN RAISE EXCEPTION 'NO_EXECUTOR'; END IF;
    IF v_status = 'awaiting_payment' THEN
        RAISE EXCEPTION 'CHAT_LOCKED' USING ERRCODE = 'check_violation';
    END IF;

    FOR i IN 1..v_n LOOP
        v_key := btrim(v_keys[i]);
        IF v_key IS NULL OR NOT (
            v_key LIKE ('chat/task/' || p_task_id::TEXT || '/%')
            OR v_key LIKE ('chats/tasks/' || p_task_id::TEXT || '/%')
        ) THEN
            RAISE EXCEPTION 'INVALID_STORAGE_KEY';
        END IF;
    END LOOP;

    v_id := uuidv7();
    INSERT INTO qr_marketplace.service_task_messages (id, service_task_id, sender_user_id, body)
    VALUES (v_id, p_task_id, p_sender_user_id, coalesce(v_body, ''))
    RETURNING created_at INTO v_created;

    FOR i IN 1..v_n LOOP
        INSERT INTO qr_marketplace.service_task_message_attachments (
            message_id, storage_key, mime_type, size_bytes, original_filename
        ) VALUES (
            v_id,
            btrim(v_keys[i]),
            coalesce(nullif(btrim(coalesce(p_mime_types[i], '')), ''), 'image/jpeg'),
            coalesce(p_sizes[i], 0),
            nullif(btrim(coalesce(p_filenames[i], '')), '')
        );
    END LOOP;

    id := v_id;
    created_at := v_created;
    RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_template_create(p_user_id UUID, p_name VARCHAR, p_payload JSONB) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_id UUID;
    v_count INTEGER;
BEGIN
    IF trim(coalesce(p_name, '')) = '' THEN
        RAISE EXCEPTION 'TEMPLATE_NAME_REQUIRED';
    END IF;

    SELECT count(*) INTO v_count
    FROM qr_marketplace.service_task_templates
    WHERE user_id = p_user_id;

    IF v_count >= 4 THEN
        RAISE EXCEPTION 'TEMPLATE_LIMIT_REACHED';
    END IF;

    v_id := uuidv7();
    INSERT INTO qr_marketplace.service_task_templates (id, user_id, name, payload)
    VALUES (v_id, p_user_id, trim(p_name), p_payload);

    RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_template_delete(p_id UUID, p_user_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
BEGIN
    DELETE FROM qr_marketplace.service_task_templates
    WHERE id = p_id AND user_id = p_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'TEMPLATE_NOT_FOUND';
    END IF;

    RETURN p_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_try_start_work(p_task_id UUID) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_status VARCHAR;
    v_from BIGINT;
    v_to BIGINT;
    v_fee_paid TIMESTAMPTZ;
    v_customer_paid BOOLEAN;
BEGIN
    SELECT sts.code, st.status_id, st.executor_fee_paid_at
    INTO v_status, v_from, v_fee_paid
    FROM qr_marketplace.service_tasks st
    JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
    WHERE st.id = p_task_id
    FOR UPDATE OF st;

    IF NOT FOUND OR v_status <> 'awaiting_payment' THEN
        RETURN FALSE;
    END IF;

    IF v_fee_paid IS NULL THEN
        RETURN FALSE;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM qr_marketplace.service_task_payments p
        JOIN qr_ref.payment_statuses ps ON ps.id = p.status_id
        WHERE p.service_task_id = p_task_id AND ps.code = 'succeeded'
    ) INTO v_customer_paid;

    IF NOT coalesce(v_customer_paid, FALSE) THEN
        RETURN FALSE;
    END IF;

    SELECT qr_api.sp_lookup_service_task_status_id('in_progress') INTO v_to;
    UPDATE qr_marketplace.service_tasks
    SET status_id = v_to, payment_deadline_at = NULL, updated_at = now()
    WHERE id = p_task_id;

    PERFORM qr_api.sp_service_task_log_status(p_task_id, v_from, v_to, NULL, 'both_parties_paid');

    PERFORM qr_api.sp_user_notification_create(
        (SELECT customer_user_id FROM qr_marketplace.service_tasks WHERE id = p_task_id),
        'task_in_progress',
        'Задание в работе',
        'Обе стороны оплатили — чат открыт, исполнитель приступает к работе.',
        'service_task', p_task_id, '/tasks/' || p_task_id::TEXT
    );
    PERFORM qr_api.sp_user_notification_create(
        (
            SELECT cm.user_id
            FROM qr_marketplace.service_tasks st
            JOIN qr_marketplace.company_members cm ON cm.company_id = st.assigned_company_id
            WHERE st.id = p_task_id
            LIMIT 1
        ),
        'task_in_progress',
        'Задание в работе',
        'Обе стороны оплатили — чат открыт, можно приступать.',
        'service_task', p_task_id, '/tasks/' || p_task_id::TEXT
    );

    RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_update(p_task_id UUID, p_user_id UUID, p_is_admin BOOLEAN, p_title VARCHAR, p_description TEXT, p_category_code VARCHAR, p_desired_amount_rub DECIMAL, p_grave_latitude DECIMAL, p_grave_longitude DECIMAL, p_grave_location_label VARCHAR, p_memorial_id UUID, p_items_json JSONB, p_graves_json JSONB, p_desired_completion_at DATE DEFAULT CAST(NULL AS DATE), p_attributes JSONB DEFAULT CAST(NULL AS JSONB)) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_owner UUID;
    v_code VARCHAR;
    v_category_id BIGINT;
    v_item JSONB;
    v_grave JSONB;
    v_sort SMALLINT := 0;
    v_grave_sort SMALLINT := 0;
    v_attributes JSONB;
BEGIN
    SELECT st.customer_user_id, sts.code INTO v_owner, v_code
    FROM qr_marketplace.service_tasks st
    JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
    WHERE st.id = p_task_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'TASK_NOT_FOUND'; END IF;
    IF v_owner IS DISTINCT FROM p_user_id AND NOT p_is_admin THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
    IF v_code NOT IN ('draft', 'published', 'reviewing') THEN RAISE EXCEPTION 'INVALID_STATUS'; END IF;
    IF EXISTS (SELECT 1 FROM qr_marketplace.service_tasks WHERE id = p_task_id AND assigned_company_id IS NOT NULL) THEN
        RAISE EXCEPTION 'TASK_ASSIGNED';
    END IF;

    IF p_desired_completion_at IS NOT NULL AND p_desired_completion_at <= CURRENT_DATE THEN
        RAISE EXCEPTION 'DESIRED_COMPLETION_NOT_IN_FUTURE';
    END IF;

    SELECT qr_api.sp_lookup_service_category_id(p_category_code) INTO v_category_id;
    IF v_category_id IS NULL THEN RAISE EXCEPTION 'CATEGORY_NOT_FOUND'; END IF;

    IF p_graves_json IS NOT NULL AND jsonb_array_length(p_graves_json) > 1 THEN
        RAISE EXCEPTION 'TOO_MANY_GRAVES';
    END IF;
    IF p_items_json IS NOT NULL AND jsonb_array_length(p_items_json) > 1 THEN
        RAISE EXCEPTION 'TOO_MANY_ITEMS';
    END IF;

    v_attributes := coalesce(p_attributes, '{}'::jsonb);
    IF jsonb_typeof(v_attributes) <> 'object' THEN
        RAISE EXCEPTION 'INVALID_ATTRIBUTES';
    END IF;
    IF length(v_attributes::text) > 4096 THEN
        RAISE EXCEPTION 'ATTRIBUTES_TOO_LARGE';
    END IF;

    UPDATE qr_marketplace.service_tasks SET
        title = p_title,
        description = p_description,
        category_id = v_category_id,
        desired_amount_rub = p_desired_amount_rub,
        grave_latitude = p_grave_latitude,
        grave_longitude = p_grave_longitude,
        grave_location_label = p_grave_location_label,
        memorial_id = p_memorial_id,
        desired_completion_at = p_desired_completion_at,
        attributes = v_attributes
    WHERE id = p_task_id;

    DELETE FROM qr_marketplace.service_task_graves WHERE service_task_id = p_task_id;
    IF p_graves_json IS NOT NULL AND jsonb_array_length(p_graves_json) > 0 THEN
        FOR v_grave IN SELECT * FROM jsonb_array_elements(p_graves_json)
        LOOP
            IF trim(coalesce(v_grave->>'deceased_full_name', '')) = '' THEN
                RAISE EXCEPTION 'DECEASED_NAME_REQUIRED';
            END IF;
            INSERT INTO qr_marketplace.service_task_graves (
                service_task_id, memorial_id, deceased_full_name, region_name, city_name,
                cemetery_name, placement_hint, grave_latitude, grave_longitude,
                grave_photo_storage_key, notes, sort_order
            ) VALUES (
                p_task_id,
                NULLIF(v_grave->>'memorial_id', '')::UUID,
                trim(v_grave->>'deceased_full_name'),
                NULLIF(v_grave->>'region_name', ''),
                NULLIF(v_grave->>'city_name', ''),
                NULLIF(v_grave->>'cemetery_name', ''),
                NULLIF(v_grave->>'placement_hint', ''),
                NULLIF(v_grave->>'grave_latitude', '')::NUMERIC,
                NULLIF(v_grave->>'grave_longitude', '')::NUMERIC,
                NULLIF(v_grave->>'grave_photo_storage_key', ''),
                NULLIF(v_grave->>'notes', ''),
                v_grave_sort
            );
            v_grave_sort := v_grave_sort + 1;
        END LOOP;
    END IF;

    DELETE FROM qr_marketplace.service_task_items WHERE service_task_id = p_task_id AND is_locked = FALSE;
    IF p_items_json IS NOT NULL AND jsonb_array_length(p_items_json) > 0 THEN
        FOR v_item IN SELECT * FROM jsonb_array_elements(p_items_json)
        LOOP
            INSERT INTO qr_marketplace.service_task_items (
                service_task_id, title, description, quantity, unit,
                unit_price_rub, line_total_rub, sort_order
            ) VALUES (
                p_task_id,
                v_item->>'title',
                v_item->>'description',
                coalesce((v_item->>'quantity')::NUMERIC, 1),
                coalesce(v_item->>'unit', 'усл.'),
                (v_item->>'unit_price_rub')::NUMERIC,
                (v_item->>'line_total_rub')::NUMERIC,
                v_sort
            );
            v_sort := v_sort + 1;
        END LOOP;
    END IF;

    RETURN p_task_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_service_task_verifier_respond(p_token UUID, p_confirm BOOLEAN, p_comment TEXT, p_storage_keys TEXT[] DEFAULT CAST(NULL AS TEXT[]), p_mime_types TEXT[] DEFAULT CAST(NULL AS TEXT[]), p_sizes BIGINT[] DEFAULT CAST(NULL AS BIGINT[]), p_filenames TEXT[] DEFAULT CAST(NULL AS TEXT[])) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_verifier RECORD; v_task_id UUID; v_from BIGINT; v_to BIGINT; v_status BIGINT;
    v_keys TEXT[] := coalesce(p_storage_keys, ARRAY[]::TEXT[]);
    v_n INT;
    i INT;
    v_key TEXT;
BEGIN
    SELECT v.*, st.status_id AS task_status_id, st.customer_user_id, st.verification_deadline_at
    INTO v_verifier
    FROM qr_marketplace.service_task_verifiers v
    JOIN qr_marketplace.service_tasks st ON st.id = v.service_task_id
    JOIN qr_ref.task_verifier_statuses tvs ON tvs.id = v.status_id
    WHERE v.invite_token = p_token AND tvs.code = 'pending';
    IF NOT FOUND THEN RAISE EXCEPTION 'VERIFIER_NOT_FOUND'; END IF;

    IF v_verifier.expires_at <= now()
       OR (v_verifier.verification_deadline_at IS NOT NULL AND v_verifier.verification_deadline_at <= now())
    THEN
        RAISE EXCEPTION 'VERIFIER_EXPIRED';
    END IF;

    v_task_id := v_verifier.service_task_id;
    IF (SELECT code FROM qr_ref.service_task_statuses WHERE id = v_verifier.task_status_id) <> 'awaiting_verification' THEN
        RAISE EXCEPTION 'INVALID_STATUS';
    END IF;

    v_n := coalesce(array_length(v_keys, 1), 0);
    IF v_n > 3 THEN RAISE EXCEPTION 'TOO_MANY_ATTACHMENTS'; END IF;
    FOR i IN 1..v_n LOOP
        v_key := btrim(v_keys[i]);
        IF v_key IS NULL OR NOT (
            v_key LIKE ('chat/verify/' || v_verifier.id::TEXT || '/%')
            OR v_key LIKE ('chats/verify/' || v_verifier.id::TEXT || '/%')
        ) THEN
            RAISE EXCEPTION 'INVALID_STORAGE_KEY';
        END IF;
    END LOOP;

    FOR i IN 1..v_n LOOP
        INSERT INTO qr_marketplace.service_task_verifier_attachments (
            verifier_id, storage_key, mime_type, size_bytes, original_filename
        ) VALUES (
            v_verifier.id,
            btrim(v_keys[i]),
            coalesce(nullif(btrim(coalesce(p_mime_types[i], '')), ''), 'image/jpeg'),
            coalesce(p_sizes[i], 0),
            nullif(btrim(coalesce(p_filenames[i], '')), '')
        );
    END LOOP;

    IF p_confirm THEN
        SELECT qr_api.sp_lookup_task_verifier_status_id('confirmed') INTO v_status;
        SELECT qr_api.sp_lookup_service_task_status_id('completed') INTO v_to;
        UPDATE qr_marketplace.service_tasks
        SET status_id = v_to,
            verified_at = now(),
            payment_deadline_at = NULL
        WHERE id = v_task_id;
        PERFORM qr_api.sp_service_task_log_status(v_task_id, v_verifier.task_status_id, v_to, NULL, 'verifier_confirmed');
        PERFORM qr_api.sp_service_task_insert_executor_payout(v_task_id);
        PERFORM qr_api.sp_user_notification_create(
            v_verifier.customer_user_id, 'task_verified',
            'Работа принята',
            'Проверка подтверждена — задание завершено',
            'service_task', v_task_id, '/tasks/' || v_task_id::TEXT
        );
        PERFORM qr_api.sp_company_review_invite_task(v_task_id);
    ELSE
        SELECT qr_api.sp_lookup_task_verifier_status_id('rejected') INTO v_status;
        SELECT qr_api.sp_lookup_service_task_status_id('disputed') INTO v_to;
        UPDATE qr_marketplace.service_tasks SET status_id = v_to WHERE id = v_task_id;
        PERFORM qr_api.sp_service_task_log_status(v_task_id, v_verifier.task_status_id, v_to, NULL, coalesce(p_comment, 'verifier_rejected'));
        PERFORM qr_api.sp_notify_admins_task_dispute(v_task_id);
    END IF;

    UPDATE qr_marketplace.service_task_verifiers SET status_id = v_status, responded_at = now(), comment = p_comment WHERE id = v_verifier.id;
    RETURN v_verifier.id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_set_yookassa_payment_method(p_provider_payment_id VARCHAR, p_payment_method VARCHAR) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_method VARCHAR(128) := left(btrim(coalesce(p_payment_method, '')), 128);
BEGIN
    IF p_provider_payment_id IS NULL OR btrim(p_provider_payment_id) = '' OR v_method = '' THEN
        RETURN;
    END IF;

    UPDATE qr_commerce.payments
    SET payment_method = v_method, updated_at = now()
    WHERE provider = 'yookassa' AND provider_payment_id = p_provider_payment_id;

    UPDATE qr_marketplace.service_task_payments
    SET payment_method = v_method, updated_at = now()
    WHERE provider_payment_id = p_provider_payment_id;

    UPDATE qr_marketplace.company_product_listing_payments
    SET payment_method = v_method, updated_at = now()
    WHERE provider_payment_id = p_provider_payment_id;

    UPDATE qr_marketplace.company_shop_order_payments
    SET payment_method = v_method, updated_at = now()
    WHERE provider_payment_id = p_provider_payment_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_soft_delete_media(p_media_id UUID) RETURNS VARCHAR LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_key VARCHAR(512);
BEGIN
    UPDATE qr_memorial.media_files
    SET deleted_at = now()
    WHERE id = p_media_id AND deleted_at IS NULL
    RETURNING storage_key INTO v_key;

    RETURN v_key;
