$function$

CREATE OR REPLACE FUNCTION qr_api.sp_support_admin_archive(p_admin_id UUID, p_conv_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_user UUID;
BEGIN
    PERFORM qr_api.sp_admin_assert_actor(p_admin_id);
    SELECT user_id INTO v_user FROM qr_platform.support_conversations WHERE id = p_conv_id;
    IF v_user IS NULL THEN RAISE EXCEPTION 'CONVERSATION_NOT_FOUND'; END IF;

    UPDATE qr_platform.support_conversations
    SET status_code = 'archived', closed_at = now()
    WHERE id = p_conv_id;

    UPDATE qr_platform.user_notifications
    SET read_at = coalesce(read_at, now())
    WHERE user_id = v_user
      AND notification_type_code = 'support_reply'
      AND entity_id = p_conv_id
      AND read_at IS NULL;

    RETURN p_conv_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_support_admin_send_message(p_admin_id UUID, p_conv_id UUID, p_body TEXT, p_storage_keys TEXT[] DEFAULT CAST(NULL AS TEXT[]), p_mime_types TEXT[] DEFAULT CAST(NULL AS TEXT[]), p_sizes BIGINT[] DEFAULT CAST(NULL AS BIGINT[]), p_filenames TEXT[] DEFAULT CAST(NULL AS TEXT[])) RETURNS TABLE (id UUID, created_at TIMESTAMPTZ) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
#variable_conflict use_column
DECLARE
    v_id UUID; v_created TIMESTAMPTZ; v_status VARCHAR;
    v_body TEXT := btrim(coalesce(p_body, ''));
    v_keys TEXT[] := coalesce(p_storage_keys, ARRAY[]::TEXT[]);
    v_n INT;
    i INT;
    v_key TEXT;
BEGIN
    PERFORM qr_api.sp_admin_assert_actor(p_admin_id);
    v_n := coalesce(array_length(v_keys, 1), 0);
    IF v_body = '' AND v_n = 0 THEN RAISE EXCEPTION 'EMPTY_MESSAGE'; END IF;
    IF length(v_body) > 4000 THEN v_body := left(v_body, 4000); END IF;
    IF v_n > 3 THEN RAISE EXCEPTION 'TOO_MANY_ATTACHMENTS'; END IF;

    SELECT sc.status_code INTO v_status FROM qr_platform.support_conversations sc WHERE sc.id = p_conv_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'CONVERSATION_NOT_FOUND'; END IF;
    IF v_status = 'archived' THEN RAISE EXCEPTION 'CONVERSATION_ARCHIVED'; END IF;

    FOR i IN 1..v_n LOOP
        v_key := btrim(v_keys[i]);
        IF v_key IS NULL OR NOT (
            v_key LIKE ('chat/support/' || p_conv_id::TEXT || '/%')
            OR v_key LIKE ('chats/support/' || p_conv_id::TEXT || '/%')
        ) THEN
            RAISE EXCEPTION 'INVALID_STORAGE_KEY';
        END IF;
    END LOOP;

    v_id := uuidv7();
    INSERT INTO qr_platform.support_messages (id, conversation_id, sender_user_id, is_admin, body)
    VALUES (v_id, p_conv_id, p_admin_id, TRUE, coalesce(v_body, ''))
    RETURNING created_at INTO v_created;

    FOR i IN 1..v_n LOOP
        INSERT INTO qr_platform.support_message_attachments (
            message_id, storage_key, mime_type, size_bytes, original_filename
        ) VALUES (
            v_id,
            btrim(v_keys[i]),
            coalesce(nullif(btrim(coalesce(p_mime_types[i], '')), ''), 'image/jpeg'),
            coalesce(p_sizes[i], 0),
            nullif(btrim(coalesce(p_filenames[i], '')), '')
        );
    END LOOP;

    UPDATE qr_platform.support_messages
    SET read_at = now()
    WHERE conversation_id = p_conv_id AND is_admin = FALSE AND read_at IS NULL;

    UPDATE qr_platform.support_conversations sc
    SET status_code = 'active', last_message_at = v_created,
        assigned_admin_id = coalesce(sc.assigned_admin_id, p_admin_id)
    WHERE sc.id = p_conv_id;

    id := v_id; created_at := v_created;
    RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_support_admin_start_conversation(p_admin_id UUID, p_user_id UUID, p_body TEXT, p_category_code VARCHAR DEFAULT CAST('general' AS VARCHAR)) RETURNS TABLE (conversation_id UUID, id UUID, created_at TIMESTAMPTZ) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
#variable_conflict use_column
DECLARE
    v_conv UUID;
    v_id UUID;
    v_created TIMESTAMPTZ;
    v_body TEXT := btrim(coalesce(p_body, ''));
    v_cat VARCHAR := coalesce(nullif(btrim(p_category_code), ''), 'general');
BEGIN
    PERFORM qr_api.sp_admin_assert_actor(p_admin_id);

    IF v_body = '' THEN
        RAISE EXCEPTION 'EMPTY_MESSAGE' USING ERRCODE = 'P0001';
    END IF;
    IF length(v_body) > 4000 THEN
        v_body := left(v_body, 4000);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM qr_identity.users u
        WHERE u.id = p_user_id AND u.deleted_at IS NULL AND u.is_active
    ) THEN
        RAISE EXCEPTION 'USER_NOT_FOUND' USING ERRCODE = 'P0001';
    END IF;

    IF v_cat NOT IN ('general', 'tasks', 'qr', 'account', 'payment') THEN
        RAISE EXCEPTION 'INVALID_CATEGORY' USING ERRCODE = 'P0001';
    END IF;

    SELECT c.id INTO v_conv
    FROM qr_platform.support_conversations c
    WHERE c.user_id = p_user_id AND c.status_code <> 'archived'
    ORDER BY c.last_message_at DESC NULLS LAST, c.created_at DESC
    LIMIT 1;

    IF v_conv IS NULL THEN
        v_conv := uuidv7();
        INSERT INTO qr_platform.support_conversations (
            id, user_id, status_code, category_code, assigned_admin_id, last_message_at
        ) VALUES (
            v_conv, p_user_id, 'active', v_cat, p_admin_id, now()
        );
    END IF;

    v_id := uuidv7();
    INSERT INTO qr_platform.support_messages (id, conversation_id, sender_user_id, is_admin, body)
    VALUES (v_id, v_conv, p_admin_id, TRUE, v_body)
    RETURNING created_at INTO v_created;

    UPDATE qr_platform.support_conversations sc
    SET status_code = 'active',
        last_message_at = v_created,
        assigned_admin_id = coalesce(sc.assigned_admin_id, p_admin_id)
    WHERE sc.id = v_conv;

    conversation_id := v_conv;
    id := v_id;
    created_at := v_created;
    RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_support_build_task_snapshot(p_task_id UUID, p_reason TEXT) RETURNS TEXT LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_task RECORD;
    v_lines TEXT := '';
    v_msg RECORD;
    v_media RECORD;
    v_ver RECORD;
    v_body TEXT;
BEGIN
    SELECT st.task_number, st.title, sts.code AS status_code, sts.name AS status_name,
           st.grave_photo_storage_key, st.verification_deadline_at, st.payment_deadline_at,
           st.customer_user_id
    INTO v_task
    FROM qr_marketplace.service_tasks st
    JOIN qr_ref.service_task_statuses sts ON sts.id = st.status_id
    WHERE st.id = p_task_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'TASK_NOT_FOUND'; END IF;

    v_lines := format(
        E'[Автоэскалация]\n%s\n\nЗадание №%s «%s»\nСтатус: %s (%s)\nКарточка: /tasks/%s\n',
        coalesce(nullif(btrim(p_reason), ''), 'Требуется вмешательство поддержки'),
        v_task.task_number,
        v_task.title,
        v_task.status_name,
        v_task.status_code,
        p_task_id
    );

    IF v_task.verification_deadline_at IS NOT NULL THEN
        v_lines := v_lines || format(E'Срок проверки: %s\n', v_task.verification_deadline_at);
    END IF;
    IF v_task.payment_deadline_at IS NOT NULL THEN
        v_lines := v_lines || format(E'Срок оплаты: %s\n', v_task.payment_deadline_at);
    END IF;

    IF v_task.grave_photo_storage_key IS NOT NULL THEN
        v_lines := v_lines || format(E'\nФото места (ключ хранилища): %s\n', v_task.grave_photo_storage_key);
    ELSE
        v_lines := v_lines || E'\nФото места: не загружено\n';
    END IF;

    FOR v_media IN
        SELECT media_type, storage_key, created_at
        FROM qr_marketplace.service_task_media
        WHERE service_task_id = p_task_id
        ORDER BY created_at
    LOOP
        v_lines := v_lines || format(
            E'Медиа [%s]: %s\n', v_media.media_type, v_media.storage_key
        );
    END LOOP;

    v_lines := v_lines || E'\n--- Проверяющие ---\n';
    FOR v_ver IN
        SELECT v.id, coalesce(v.invite_name, v.invite_email::TEXT, 'без имени') AS who,
               tvs.code AS st, v.comment, v.responded_at
        FROM qr_marketplace.service_task_verifiers v
        JOIN qr_ref.task_verifier_statuses tvs ON tvs.id = v.status_id
        WHERE v.service_task_id = p_task_id
        ORDER BY v.invited_at
    LOOP
        v_lines := v_lines || format(
            E'%s · %s%s\n',
            v_ver.who,
            v_ver.st,
            CASE WHEN v_ver.comment IS NOT NULL AND btrim(v_ver.comment) <> ''
                 THEN format(' · комментарий: %s', v_ver.comment) ELSE '' END
        );
        FOR v_media IN
            SELECT storage_key FROM qr_marketplace.service_task_verifier_attachments
            WHERE verifier_id = v_ver.id ORDER BY created_at
        LOOP
            v_lines := v_lines || format(E'  фото проверяющего: %s\n', v_media.storage_key);
        END LOOP;
    END LOOP;

    v_lines := v_lines || E'\n--- Переписка заказчик ↔ исполнитель ---\n';
    FOR v_msg IN
        SELECT m.body, m.created_at,
               coalesce(u.full_name, u.email::TEXT, 'участник') AS who
        FROM qr_marketplace.service_task_messages m
        JOIN qr_identity.users u ON u.id = m.sender_user_id
        WHERE m.service_task_id = p_task_id
        ORDER BY m.created_at
        LIMIT 80
    LOOP
        v_lines := v_lines || format(
            E'[%s] %s: %s\n',
            to_char(v_msg.created_at AT TIME ZONE 'Europe/Moscow', 'DD.MM.YYYY HH24:MI'),
            v_msg.who,
            left(v_msg.body, 500)
        );
    END LOOP;

    IF NOT EXISTS (SELECT 1 FROM qr_marketplace.service_task_messages WHERE service_task_id = p_task_id) THEN
        v_lines := v_lines || E'(сообщений в чате задания нет)\n';
    END IF;

    v_body := left(v_lines, 4000);
    RETURN v_body;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_support_escalate_shop_order(p_order_id UUID, p_category_code VARCHAR, p_reason TEXT DEFAULT CAST(NULL AS TEXT)) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_buyer UUID;
    v_conv UUID;
    v_body TEXT;
    v_msg_id UUID;
    v_order_number BIGINT;
    v_company_name TEXT;
BEGIN
    IF p_category_code NOT IN ('shop_dispute') THEN
        RAISE EXCEPTION 'INVALID_CATEGORY';
    END IF;

    SELECT o.buyer_user_id, o.order_number, coalesce(c.short_name, c.legal_name)::TEXT
    INTO v_buyer, v_order_number, v_company_name
    FROM qr_marketplace.company_shop_orders o
    JOIN qr_marketplace.companies c ON c.id = o.company_id
    WHERE o.id = p_order_id;
    IF v_buyer IS NULL THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;

    SELECT sc.id INTO v_conv
    FROM qr_platform.support_conversations sc
    WHERE sc.shop_order_id = p_order_id
      AND sc.category_code = p_category_code
      AND sc.status_code <> 'archived'
    ORDER BY sc.created_at DESC
    LIMIT 1;

    v_body := format(
        E'Заказ витрины №%s (%s)\n%s',
        v_order_number,
        coalesce(v_company_name, '—'),
        coalesce(nullif(btrim(p_reason), ''), 'Требуется решение поддержки.')
    );

    IF v_conv IS NULL THEN
        v_conv := uuidv7();
        INSERT INTO qr_platform.support_conversations (
            id, user_id, status_code, category_code, shop_order_id
        ) VALUES (
            v_conv, v_buyer, 'unread', p_category_code, p_order_id
        );
    ELSE
        UPDATE qr_platform.support_conversations
        SET status_code = 'unread', last_message_at = now()
        WHERE id = v_conv;
    END IF;

    v_msg_id := uuidv7();
    INSERT INTO qr_platform.support_messages (id, conversation_id, sender_user_id, is_admin, body)
    VALUES (v_msg_id, v_conv, v_buyer, FALSE, v_body);

    UPDATE qr_platform.support_conversations SET last_message_at = now() WHERE id = v_conv;

    PERFORM qr_api.sp_user_notification_create(
        v_buyer,
        'support_escalation',
        'Спор по заказу передан в поддержку',
        coalesce(nullif(btrim(p_reason), ''), 'Заказ передан на рассмотрение поддержки'),
        'support_conversation', v_conv, '#open-support'
    );

    RETURN v_conv;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_support_escalate_task(p_task_id UUID, p_category_code VARCHAR, p_reason TEXT DEFAULT CAST(NULL AS TEXT)) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_customer UUID;
    v_conv UUID;
    v_body TEXT;
    v_msg_id UUID;
    v_media RECORD;
BEGIN
    IF p_category_code NOT IN ('task_dispute', 'task_overdue') THEN
        RAISE EXCEPTION 'INVALID_CATEGORY';
    END IF;

    SELECT customer_user_id INTO v_customer
    FROM qr_marketplace.service_tasks WHERE id = p_task_id;
    IF v_customer IS NULL THEN RAISE EXCEPTION 'TASK_NOT_FOUND'; END IF;

    SELECT c.id INTO v_conv
    FROM qr_platform.support_conversations c
    WHERE c.service_task_id = p_task_id
      AND c.category_code = p_category_code
      AND c.status_code <> 'archived'
    ORDER BY c.created_at DESC
    LIMIT 1;

    v_body := qr_api.sp_support_build_task_snapshot(p_task_id, p_reason);

    IF v_conv IS NULL THEN
        v_conv := uuidv7();
        INSERT INTO qr_platform.support_conversations (
            id, user_id, status_code, category_code, service_task_id
        ) VALUES (
            v_conv, v_customer, 'unread', p_category_code, p_task_id
        );
    ELSE
        UPDATE qr_platform.support_conversations
        SET status_code = 'unread', last_message_at = now()
        WHERE id = v_conv;
    END IF;

    v_msg_id := uuidv7();
    INSERT INTO qr_platform.support_messages (id, conversation_id, sender_user_id, is_admin, body)
    VALUES (v_msg_id, v_conv, v_customer, FALSE, v_body);

    FOR v_media IN
        SELECT va.storage_key, va.mime_type, va.size_bytes, va.original_filename
        FROM qr_marketplace.service_task_verifier_attachments va
        JOIN qr_marketplace.service_task_verifiers v ON v.id = va.verifier_id
        WHERE v.service_task_id = p_task_id
        ORDER BY va.created_at
    LOOP
        INSERT INTO qr_platform.support_message_attachments (
            message_id, storage_key, mime_type, size_bytes, original_filename
        ) VALUES (
            v_msg_id,
            v_media.storage_key,
            coalesce(v_media.mime_type, 'image/jpeg'),
            coalesce(v_media.size_bytes, 0),
            v_media.original_filename
        );
    END LOOP;

    UPDATE qr_platform.support_conversations SET last_message_at = now() WHERE id = v_conv;

    PERFORM qr_api.sp_user_notification_create(
        v_customer,
        'support_escalation',
        'Обращение передано в поддержку',
        coalesce(nullif(btrim(p_reason), ''), 'По вашему заданию создано обращение в поддержку'),
        'support_conversation', v_conv, '#open-support'
    );

    RETURN v_conv;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_support_user_mark_read(p_user_id UUID) RETURNS INT LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE v_conv UUID; v_count INTEGER := 0;
BEGIN
    SELECT c.id INTO v_conv
    FROM qr_platform.support_conversations c
    WHERE c.user_id = p_user_id AND c.status_code <> 'archived'
    ORDER BY c.created_at DESC
    LIMIT 1;
    IF v_conv IS NULL THEN RETURN 0; END IF;

    UPDATE qr_platform.support_messages
    SET read_at = now()
    WHERE conversation_id = v_conv AND is_admin = TRUE AND read_at IS NULL;
    GET DIAGNOSTICS v_count = ROW_COUNT;

    UPDATE qr_platform.user_notifications
    SET read_at = coalesce(read_at, now())
    WHERE user_id = p_user_id
      AND notification_type_code = 'support_reply'
      AND entity_id = v_conv
      AND read_at IS NULL;

    RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_support_user_send_message(p_user_id UUID, p_body TEXT, p_category_code VARCHAR DEFAULT CAST(NULL AS VARCHAR), p_storage_keys TEXT[] DEFAULT CAST(NULL AS TEXT[]), p_mime_types TEXT[] DEFAULT CAST(NULL AS TEXT[]), p_sizes BIGINT[] DEFAULT CAST(NULL AS BIGINT[]), p_filenames TEXT[] DEFAULT CAST(NULL AS TEXT[])) RETURNS TABLE (conversation_id UUID, id UUID, created_at TIMESTAMPTZ, category_code VARCHAR) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
#variable_conflict use_column
DECLARE
    v_conv UUID; v_id UUID; v_created TIMESTAMPTZ; v_cat VARCHAR;
    v_body TEXT := btrim(coalesce(p_body, ''));
    v_keys TEXT[] := coalesce(p_storage_keys, ARRAY[]::TEXT[]);
    v_n INT;
    i INT;
    v_key TEXT;
BEGIN
    v_n := coalesce(array_length(v_keys, 1), 0);
    IF v_body = '' AND v_n = 0 THEN RAISE EXCEPTION 'EMPTY_MESSAGE'; END IF;
    IF length(v_body) > 4000 THEN v_body := left(v_body, 4000); END IF;
    IF v_n > 3 THEN RAISE EXCEPTION 'TOO_MANY_ATTACHMENTS'; END IF;

    SELECT c.id, c.category_code INTO v_conv, v_cat
    FROM qr_platform.support_conversations c
    WHERE c.user_id = p_user_id AND c.status_code <> 'archived'
    ORDER BY c.created_at DESC
    LIMIT 1;

    IF v_conv IS NULL THEN
        v_cat := coalesce(nullif(btrim(p_category_code), ''), 'general');
        IF v_cat NOT IN ('general', 'tasks', 'qr', 'account', 'payment') THEN
            RAISE EXCEPTION 'INVALID_CATEGORY';
        END IF;
        v_conv := uuidv7();
        INSERT INTO qr_platform.support_conversations (id, user_id, status_code, category_code)
        VALUES (v_conv, p_user_id, 'unread', v_cat);
    ELSE
        -- Уже открытая (active) беседа остаётся в «Активных»; счётчик непрочитанных
        -- растёт через support_messages.read_at. В «Новые» (unread) только ещё не открытые.
        UPDATE qr_platform.support_conversations sc
        SET status_code = CASE WHEN sc.status_code = 'active' THEN 'active' ELSE 'unread' END,
            last_message_at = now()
        WHERE sc.id = v_conv;
    END IF;

    -- Валидация ключей: pending/{user} или chat(s)/support/{conv}/
    FOR i IN 1..v_n LOOP
        v_key := btrim(v_keys[i]);
        IF v_key IS NULL OR v_key = '' THEN RAISE EXCEPTION 'INVALID_STORAGE_KEY'; END IF;
        IF NOT (
            v_key LIKE ('chat/support/pending/' || p_user_id::TEXT || '/%')
            OR v_key LIKE ('chats/support/pending/' || p_user_id::TEXT || '/%')
            OR v_key LIKE ('chat/support/' || v_conv::TEXT || '/%')
            OR v_key LIKE ('chats/support/' || v_conv::TEXT || '/%')
        ) THEN
            RAISE EXCEPTION 'INVALID_STORAGE_KEY';
        END IF;
    END LOOP;

    v_id := uuidv7();
    INSERT INTO qr_platform.support_messages (id, conversation_id, sender_user_id, is_admin, body)
    VALUES (v_id, v_conv, p_user_id, FALSE, coalesce(v_body, ''))
    RETURNING created_at INTO v_created;

    FOR i IN 1..v_n LOOP
        INSERT INTO qr_platform.support_message_attachments (
            message_id, storage_key, mime_type, size_bytes, original_filename
        ) VALUES (
            v_id,
            btrim(v_keys[i]),
            coalesce(nullif(btrim(coalesce(p_mime_types[i], '')), ''), 'image/jpeg'),
            coalesce(p_sizes[i], 0),
            nullif(btrim(coalesce(p_filenames[i], '')), '')
        );
    END LOOP;

    UPDATE qr_platform.support_conversations sc SET last_message_at = v_created WHERE sc.id = v_conv;

    conversation_id := v_conv; id := v_id; created_at := v_created; category_code := v_cat;
    RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_try_mark_order_fulfilled(p_order_id UUID) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order_qty INTEGER;
    v_shipment_qty INTEGER;
    v_done_qty INTEGER;
    v_open_shipments INTEGER;
    v_fulfilled_id BIGINT;
    v_mode VARCHAR;
BEGIN
    SELECT ol.quantity, o.plaque_fulfillment_mode
    INTO v_order_qty, v_mode
    FROM qr_commerce.orders o
    JOIN qr_commerce.order_lines ol ON ol.order_id = o.id
    WHERE o.id = p_order_id;

    IF v_order_qty IS NULL THEN
        RETURN;
    END IF;

    -- Самостоятельная печать: заказ закрыт без физической доставки.
    IF v_mode = 'self_print' THEN
        SELECT id INTO v_fulfilled_id FROM qr_ref.order_statuses WHERE code = 'fulfilled';
        UPDATE qr_commerce.orders
        SET status_id = v_fulfilled_id, updated_at = now()
        WHERE id = p_order_id
          AND status_id IN (SELECT id FROM qr_ref.order_statuses WHERE code IN ('paid', 'fulfilled'));
        RETURN;
    END IF;

    SELECT COALESCE(SUM(od.quantity), 0), COALESCE(SUM(od.quantity) FILTER (
        WHERE fs.code IN ('delivered', 'self_print', 'completed')
    ), 0), COUNT(*) FILTER (WHERE fs.code NOT IN ('delivered', 'self_print', 'completed', 'returned', 'failed'))
    INTO v_shipment_qty, v_done_qty, v_open_shipments
    FROM qr_commerce.order_deliveries od
    JOIN qr_ref.fulfillment_statuses fs ON fs.id = od.fulfillment_status_id
    WHERE od.order_id = p_order_id;

    IF v_shipment_qty = v_order_qty AND v_done_qty = v_order_qty AND v_open_shipments = 0 THEN
        SELECT id INTO v_fulfilled_id FROM qr_ref.order_statuses WHERE code = 'fulfilled';
        UPDATE qr_commerce.orders
        SET status_id = v_fulfilled_id, updated_at = now()
        WHERE id = p_order_id
          AND status_id IN (SELECT id FROM qr_ref.order_statuses WHERE code IN ('paid', 'fulfilled'));
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_update_user_profile(p_user_id UUID, p_set_full_name BOOLEAN, p_full_name VARCHAR, p_set_email BOOLEAN, p_email citext, p_set_phone BOOLEAN, p_phone VARCHAR) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_email CITEXT;
    v_current qr_identity.users%ROWTYPE;
BEGIN
    SELECT * INTO v_current
    FROM qr_identity.users
    WHERE id = p_user_id AND deleted_at IS NULL;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'USER_NOT_FOUND'
            USING ERRCODE = 'no_data_found';
    END IF;

    v_email := CASE
        WHEN p_set_email AND p_email IS NOT NULL THEN lower(p_email::text)::citext
        WHEN p_set_email THEN NULL
        ELSE v_current.email
    END;

    IF p_set_phone AND p_phone IS NOT NULL AND qr_api.sp_user_phone_exists(p_phone)
       AND v_current.phone IS DISTINCT FROM p_phone THEN
        RAISE EXCEPTION 'PHONE_ALREADY_EXISTS'
            USING ERRCODE = 'unique_violation';
    END IF;

    IF p_set_email AND v_email IS NOT NULL AND qr_api.sp_user_email_exists(v_email)
       AND v_current.email IS DISTINCT FROM v_email THEN
        RAISE EXCEPTION 'EMAIL_ALREADY_EXISTS'
            USING ERRCODE = 'unique_violation';
    END IF;

    IF coalesce(v_email, CASE WHEN p_set_phone THEN p_phone ELSE v_current.phone END) IS NULL THEN
        RAISE EXCEPTION 'EMAIL_OR_PHONE_REQUIRED'
            USING ERRCODE = 'check_violation';
    END IF;

    UPDATE qr_identity.users u
    SET
        full_name = CASE
            WHEN p_set_full_name THEN NULLIF(btrim(p_full_name), '')
            ELSE u.full_name
        END,
        pending_full_name = CASE
            WHEN p_set_full_name THEN NULL
            ELSE u.pending_full_name
        END,
        email = CASE WHEN p_set_email THEN v_email ELSE u.email END,
        phone = CASE WHEN p_set_phone THEN p_phone ELSE u.phone END
    WHERE u.id = p_user_id;

    RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_user_ensure_referral_code(p_user_id UUID) RETURNS VARCHAR LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_code VARCHAR(16);
BEGIN
    SELECT referral_code INTO v_code
    FROM qr_identity.users
    WHERE id = p_user_id AND deleted_at IS NULL
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'USER_NOT_FOUND';
    END IF;
    IF v_code IS NULL OR btrim(v_code) = '' THEN
        v_code := qr_api.sp_user_generate_referral_code();
        UPDATE qr_identity.users
        SET referral_code = v_code, updated_at = now()
        WHERE id = p_user_id;
    END IF;
    RETURN v_code;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_user_generate_referral_code() RETURNS VARCHAR LANGUAGE plpgsql AS $$
DECLARE
    v_code VARCHAR(16);
    v_alphabet TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    i INT;
BEGIN
    LOOP
        v_code := 'U';
        FOR i IN 1..7 LOOP
            v_code := v_code || substr(v_alphabet, 1 + floor(random() * length(v_alphabet))::INT, 1);
        END LOOP;
        EXIT WHEN NOT EXISTS (
            SELECT 1 FROM qr_marketplace.companies c WHERE c.referral_code = v_code AND c.deleted_at IS NULL
        ) AND NOT EXISTS (
            SELECT 1 FROM qr_identity.users u WHERE u.referral_code = v_code AND u.deleted_at IS NULL
        );
    END LOOP;
    RETURN v_code;
END;
$$

