CREATE OR REPLACE FUNCTION qr_api.sp_user_referral_overview(p_user_id UUID) RETURNS TABLE (user_id UUID, referral_code VARCHAR, referral_percent DECIMAL, invite_path VARCHAR) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
