CREATE OR REPLACE FUNCTION qr_api.sp_user_split_order_delivery(p_delivery_id UUID, p_user_id UUID, p_split_quantity INT, p_new_address TEXT DEFAULT CAST(NULL AS TEXT)) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_order_id UUID;
    v_order_user UUID;
    v_current_qty INTEGER;
    v_new_shipment INTEGER;
    v_pending_status_id BIGINT;
    v_new_delivery_id UUID;
    v_address TEXT;
BEGIN
    SELECT od.order_id, od.quantity, od.delivery_address, o.user_id
    INTO v_order_id, v_current_qty, v_address, v_order_user
    FROM qr_commerce.order_deliveries od
    JOIN qr_commerce.orders o ON o.id = od.order_id
    WHERE od.id = p_delivery_id
    FOR UPDATE;

    IF v_order_id IS NULL THEN
        RAISE EXCEPTION 'ORDER_DELIVERY_NOT_FOUND';
    END IF;

    IF v_order_user IS DISTINCT FROM p_user_id THEN
        RAISE EXCEPTION 'FORBIDDEN';
    END IF;

    IF p_split_quantity IS NULL OR p_split_quantity < 1 OR p_split_quantity >= v_current_qty THEN
        RAISE EXCEPTION 'INVALID_SPLIT_QUANTITY';
    END IF;

    SELECT id INTO v_pending_status_id FROM qr_ref.fulfillment_statuses WHERE code = 'pending';

    UPDATE qr_commerce.order_deliveries
    SET quantity = v_current_qty - p_split_quantity,
        updated_by_user_id = p_user_id
    WHERE id = p_delivery_id;

    SELECT COALESCE(MAX(shipment_number), 0) + 1 INTO v_new_shipment
    FROM qr_commerce.order_deliveries
    WHERE order_id = v_order_id;

    v_new_delivery_id := uuidv7();

    INSERT INTO qr_commerce.order_deliveries (
        id, order_id, shipment_number, quantity, fulfillment_status_id, delivery_address,
        created_by_user_id, updated_by_user_id
    ) VALUES (
        v_new_delivery_id, v_order_id, v_new_shipment, p_split_quantity, v_pending_status_id,
        COALESCE(NULLIF(btrim(p_new_address), ''), v_address),
        p_user_id, p_user_id
    );

    RETURN v_new_delivery_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_wallet_credit(p_user_id UUID, p_amount INT, p_type TEXT, p_ref_type TEXT, p_ref_id UUID, p_description TEXT, p_idempotency_key UUID DEFAULT CAST(NULL AS UUID)) RETURNS INT LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_balance INTEGER;
    v_new INTEGER;
    v_existing INTEGER;
BEGIN
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'INVALID_AMOUNT';
    END IF;

    IF p_idempotency_key IS NOT NULL THEN
        SELECT balance_after INTO v_existing
        FROM qr_commerce.wallet_transactions
        WHERE idempotency_key = p_idempotency_key;
        IF FOUND THEN
            RETURN v_existing;
        END IF;
    END IF;

    v_balance := qr_api.sp_wallet_ensure(p_user_id);
    v_new := v_balance + p_amount;
    UPDATE qr_commerce.user_wallets
    SET balance_rub = v_new, updated_at = now()
    WHERE user_id = p_user_id;

    INSERT INTO qr_commerce.wallet_transactions (
        user_id, type, amount, balance_after,
        reference_type, reference_id, description, idempotency_key
    ) VALUES (
        p_user_id, p_type, p_amount, v_new,
        p_ref_type, p_ref_id, p_description, p_idempotency_key
    );

    RETURN v_new;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_wallet_debit(p_user_id UUID, p_amount INT, p_type TEXT, p_ref_type TEXT, p_ref_id UUID, p_description TEXT, p_idempotency_key UUID DEFAULT CAST(NULL AS UUID)) RETURNS INT LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_balance INTEGER;
    v_new INTEGER;
    v_existing INTEGER;
BEGIN
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'INVALID_AMOUNT';
    END IF;

    IF p_idempotency_key IS NOT NULL THEN
        SELECT balance_after INTO v_existing
        FROM qr_commerce.wallet_transactions
        WHERE idempotency_key = p_idempotency_key;
        IF FOUND THEN
            RETURN v_existing;
        END IF;
    END IF;

    v_balance := qr_api.sp_wallet_ensure(p_user_id);
    IF v_balance < p_amount THEN
        RAISE EXCEPTION 'INSUFFICIENT_BALANCE';
    END IF;

    v_new := v_balance - p_amount;
    UPDATE qr_commerce.user_wallets
    SET balance_rub = v_new, updated_at = now()
    WHERE user_id = p_user_id;

    INSERT INTO qr_commerce.wallet_transactions (
        user_id, type, amount, balance_after,
        reference_type, reference_id, description, idempotency_key
    ) VALUES (
        p_user_id, p_type, -p_amount, v_new,
        p_ref_type, p_ref_id, p_description, p_idempotency_key
    );

    RETURN v_new;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_wallet_ensure(p_user_id UUID) RETURNS INT LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE v_balance INTEGER;
BEGIN
    INSERT INTO qr_commerce.user_wallets (user_id)
    VALUES (p_user_id)
    ON CONFLICT (user_id) DO NOTHING;

    SELECT balance_rub INTO v_balance
    FROM qr_commerce.user_wallets
    WHERE user_id = p_user_id
    FOR UPDATE;

    RETURN coalesce(v_balance, 0);
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_wallet_top_up_payment_apply(p_provider_payment_id VARCHAR) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE
    v_pay RECORD;
    v_succeeded BIGINT;
    v_waiting BIGINT;
BEGIN
    SELECT id INTO v_succeeded FROM qr_ref.payment_statuses WHERE code = 'succeeded';
    SELECT id INTO v_waiting FROM qr_ref.payment_statuses WHERE code = 'waiting';
    IF v_succeeded IS NULL OR v_waiting IS NULL THEN RAISE EXCEPTION 'PAYMENT_STATUS_MISSING'; END IF;

    SELECT * INTO v_pay
    FROM qr_commerce.wallet_top_up_payments
    WHERE provider_payment_id = p_provider_payment_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    IF v_pay.status_id = v_succeeded THEN
        RETURN v_pay.user_id;
    END IF;
    IF v_pay.status_id <> v_waiting THEN
        RAISE EXCEPTION 'INVALID_PAYMENT_STATUS';
    END IF;

    PERFORM qr_api.sp_wallet_credit(
        v_pay.user_id,
        v_pay.amount_rub,
        'top_up',
        'payment',
        v_pay.id,
        format('Пополнение баланса на %s ₽', v_pay.amount_rub),
        v_pay.id
    );

    UPDATE qr_commerce.wallet_top_up_payments
    SET status_id = v_succeeded, paid_at = now(), updated_at = now()
    WHERE id = v_pay.id;

    RETURN v_pay.user_id;
END;
$function$

CREATE OR REPLACE FUNCTION qr_api.sp_wallet_top_up_payment_create(p_user_id UUID, p_payment_id UUID, p_idempotence_key UUID, p_amount_rub INT, p_provider_payment_id VARCHAR, p_confirmation_url TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'qr_api', 'qr_marketplace', 'qr_memorial', 'qr_commerce', 'qr_identity', 'qr_ref', 'qr_platform', 'public'
AS $function$
DECLARE v_waiting BIGINT;
BEGIN
    IF p_amount_rub IS NULL OR p_amount_rub < 100 OR p_amount_rub > 100000 THEN
        RAISE EXCEPTION 'INVALID_AMOUNT';
    END IF;

    SELECT id INTO v_waiting FROM qr_ref.payment_statuses WHERE code = 'waiting';
    IF v_waiting IS NULL THEN RAISE EXCEPTION 'PAYMENT_STATUS_MISSING'; END IF;

    INSERT INTO qr_commerce.wallet_top_up_payments (
        id, user_id, status_id, amount_rub,
        provider, provider_payment_id, idempotence_key, confirmation_url
    ) VALUES (
        p_payment_id, p_user_id, v_waiting, p_amount_rub,
        'yookassa', p_provider_payment_id, p_idempotence_key, p_confirmation_url
    );
    RETURN p_payment_id;
END;
$function$
